INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cacr92/WeReply/ipc-communication', 'community', 'cacr92', 'WeReply', 'cacr92/WeReply', 'ipc-communication', 0, 0, 70, '2026-02-18T01:08:43.448Z', '2026-02-18T06:30:21.131Z', NULL, '{"id":"cacr92/WeReply/ipc-communication","name":"ipc-communication","description":{"zh":"IPC 通信技能提供了微信聊天自动回复助手的实现，使用 JSON 协议进行 Rust Orchestrator 和 Platform Agents 之间的通信","ja":"IPC 通信スキルは、WeChat チャット自動応答アシスタントの実装を提供し、Rust Orchestrator と Platform Agents 間で JSON プロトコルを使用して通信します","ko":"IPC 통신 스킬은 微信 채팅 자동 응답 도우미의 구현을 제공하며, Rust Orchestrator와 Platform Agents 사이에서 JSON 프로토콜을 사용하여 통신합니다","es":"La comunicación IPC permite la interacción entre procesos en Rust. Aprende a implementarla con protocolo JSON y stdin/stdout","fr":"La communication IPC permet l''interaction entre processus en Rust. Découvrez comment l''implémenter avec protocole JSON et stdin/stdout","de":"Die IPC-Kommunikation ermöglicht die Interaktion zwischen Prozessen in Rust. Erfahren Sie, wie Sie sie mit JSON-Protokoll und stdin/stdout implementieren","pt":"A comunicação IPC é um componente fundamental para a integração de sistemas. Neste artigo, você aprenderá a implementar a comunicação entre processos em Rust com o protocolo JSON via stdin/stdout.","ru":"IPC-коммуникация является важнейшим компонентом для интеграции систем. В этой статье вы узнаете, как реализовать межпроцессное общение в Rust с помощью JSON-протокола через stdin/stdout.","ar":"اتصال IPC هو مكون أساسي لدمج النظم. في هذه المقالة ، ستتعلم كيفية تنفيذ اتصال بين العمليات في روست باستخدام بروتوكول JSON عبر stdin/stdout.","en":"微信聊天自动回复助手"},"seo":{"title":{"zh":"IPC 通信技能 - 微信聊天自动回复助手","ja":"IPC 通信スキル - WeChat チャット自動応答アシスタント","ko":"IPC 통신 스킬 - 微信 채팅 자동 응답 도우미","es":"Comunicación IPC para Desarrolladores","fr":"Communication IPC pour Développeurs","de":"IPC-Kommunikation für Entwickler","pt":"Comunicação IPC: Guia de Implementação em Rust","ru":"IPC-коммуникация: Руководство по реализации на Rust","ar":"اتصال IPC: دليل تنفيذ الرسوم في روست","en":"ipc-communication"},"description":{"zh":"IPC 通信技能提供了微信聊天自动回复助手的实现，使用 JSON 协议进行 Rust Orchestrator 和 Platform Agents 之间的通信","ja":"IPC 通信スキルは、WeChat チャット自動応答アシスタントの実装を提供し、Rust Orchestrator と Platform Agents 間で JSON プロトコルを使用して通信します","ko":"IPC 통신 스킬은 微信 채팅 자동 응답 도우미의 구현을 제공하며, Rust Orchestrator와 Platform Agents 사이에서 JSON 프로토콜을 사용하여 통신합니다","es":"La comunicación IPC permite la interacción entre procesos en Rust. Aprende a implementarla con protocolo JSON y stdin/stdout","fr":"La communication IPC permet l''interaction entre processus en Rust. Découvrez comment l''implémenter avec protocole JSON et stdin/stdout","de":"Die IPC-Kommunikation ermöglicht die Interaktion zwischen Prozessen in Rust. Erfahren Sie, wie Sie sie mit JSON-Protokoll und stdin/stdout implementieren","pt":"A comunicação IPC é um componente fundamental para a integração de sistemas. Neste artigo, você aprenderá a implementar a comunicação entre processos em Rust...","ru":"IPC-коммуникация является важнейшим компонентом для интеграции систем. В этой статье вы узнаете, как реализовать межпроцессное общение в Rust с помощью JSON-...","ar":"اتصال IPC هو مكون أساسي لدمج النظم. في هذه المقالة ، ستتعلم كيفية تنفيذ اتصال بين العمليات في روست باستخدام بروتوكول JSON عبر stdin/stdout.","en":"微信聊天自动回复助手"},"definition":{"en":"微信聊天自动回复助手"},"features":{"zh":["使用 JSON 协议进行进程间通信","支持 Rust Orchestrator 和 Platform Agents 之间的通信","提供微信聊天自动回复助手的实现","使用 stdin/stdout 进行通信","支持 UTF-8 字符编码"],"ja":["JSON プロトコルを使用したプロセス間通信","Rust Orchestrator と Platform Agents 間の通信をサポート","WeChat チャット自動応答アシスタントの実装を提供","stdin/stdout を使用した通信","UTF-8 文字コードをサポート"],"ko":["JSON 프로토콜을 사용한 프로세스 간 통신","Rust Orchestrator와 Platform Agents 사이의 통신을 지원","微信 채팅 자동 응답 도우미의 구현을 제공","stdin/stdout를 사용한 통신","UTF-8 문자 인코딩을 지원"],"es":["Protocolo JSON para la comunicación","Comunicación bidireccional entre procesos","Uso de stdin/stdout para la comunicación","Codificación de caracteres UTF-8","Mensajes delimitados por líneas en JSON"],"fr":["Protocole JSON pour la communication","Communication bidirectionnelle entre processus","Utilisation de stdin/stdout pour la communication","Codage de caractères UTF-8","Messages délimités par des lignes en JSON"],"de":["JSON-Protokoll für die Kommunikation","Bidirektionale Kommunikation zwischen Prozessen","Verwendung von stdin/stdout für die Kommunikation","Zeichenkodierung UTF-8","Nachrichten mit JSON-Liniendelimitierung"],"pt":["Protocolo JSON para comunicação entre processos","Comunicação bidirecional entre Orchestrator e Agentes","Formatação de mensagem em JSON com delimitação por linha","Codificação de caracteres UTF-8","Implementação em Rust"],"ru":["JSON-протокол для межпроцессного общения","Бидирекциональная связь между Orchestrator и агентами","Формат сообщения в JSON с разделением по строкам","Кодировка символов UTF-8","Реализация на Rust"],"ar":["بروتوكول JSON للاتصال بين العمليات","اتصال ثنائي الاتجاه بين الاوركسترا والوكلاء","تنسيق الرسالة في JSON مع التجزئة السطرية","ترميز الأحرف UTF-8","تنفيذ في روست"]},"keywords":{"zh":["IPC 通信","JSON 协议","Rust Orchestrator","Platform Agents","微信聊天自动回复助手","进程间通信"],"ja":["IPC 通信","JSON プロトコル","Rust Orchestrator","Platform Agents","WeChat チャット自動応答アシスタント","プロセス間通信"],"ko":["IPC 통신","JSON 프로토콜","Rust Orchestrator","Platform Agents","微信 채팅 자동 응답 도우미","프로세스 간 통신"],"es":["comunicación IPC","Rust","protocolo JSON","stdin/stdout","desarrollo de software","interacción entre procesos"],"fr":["communication IPC","Rust","protocole JSON","stdin/stdout","développement de logiciels","interaction entre processus"],"de":["IPC-Kommunikation","Rust","JSON-Protokoll","stdin/stdout","Softwareentwicklung","Interaktion zwischen Prozessen"],"pt":["comunicação ipc","rust","protocolo json","stdin/stdout","comunicação entre processos","orquestrador","agentes","desenvolvimento de software"],"ru":["ipc-коммуникация","rust","json-протокол","stdin/stdout","межпроцессное общение","оркестратор","агенты","разработка программного обеспечения"],"ar":["اتصال ipc","روست","بروتوكول json","stdin/stdout","اتصال بين العمليات","الاوركسترا","الوكلاء","تطوير البرمجيات"]}},"owner":"cacr92","repo":"WeReply","repoPath":"cacr92/WeReply","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"ipc-communication","description":"当用户要求IPC 通信、进程通信、Agent 协议、stdin/stdout、JSON 消息、Orchestrator 通信、消息序列化，或者提到进程间通信、Agent 集成、消息协议时使用此技能。用于实现 Rust Orchestrator 和 Platform Agents 之间的 IPC 通信，包括消息格式定义、序列化、错误处理和性能优化。","version":"1.0.0","bodyPreview":"# IPC Communication Skill\n\nExpert guidance for implementing Inter-Process Communication between Rust Orchestrator and Platform Agents using JSON protocol via stdin/stdout.\n\n## Overview\n\nWeReply uses JSON-based IPC protocol for communication:\n- **Protocol**: JSON messages via stdin/stdout\n- **Direction**: Bidirectional (Orchestrator ↔ Agent)\n- **Message Format**: Line-delimited JSON (one message per line)\n- **Character Encoding**: UTF-8\n\n## Message Protocol Design\n\n### Message Types\n\n```rust\nuse","body":"# IPC Communication Skill\n\nExpert guidance for implementing Inter-Process Communication between Rust Orchestrator and Platform Agents using JSON protocol via stdin/stdout.\n\n## Overview\n\nWeReply uses JSON-based IPC protocol for communication:\n- **Protocol**: JSON messages via stdin/stdout\n- **Direction**: Bidirectional (Orchestrator ↔ Agent)\n- **Message Format**: Line-delimited JSON (one message per line)\n- **Character Encoding**: UTF-8\n\n## Message Protocol Design\n\n### Message Types\n\n```rust\nuse serde::{Deserialize, Serialize};\nuse specta::Type;\n\n// Agent → Orchestrator 消息\n#[derive(Serialize, Deserialize, Type, Debug)]\n#[serde(tag = \"type\")]\npub enum AgentMessage {\n    MessageNew {\n        content: String,\n        sender: String,\n        timestamp: String,\n    },\n    CommandResponse {\n        success: bool,\n        #[serde(skip_serializing_if = \"Option::is_none\")]\n        error: Option<String>,\n    },\n    HealthStatus {\n        status: String,  // \"ok\", \"degraded\", \"error\"\n        agent_type: String,  // \"windows_wxauto\", \"macos_accessibility\"\n    },\n    Heartbeat {\n        timestamp: f64,\n    },\n    Error {\n        message: String,\n        #[serde(skip_serializing_if = \"Option::is_none\")]\n        code: Option<String>,\n    },\n}\n\n// Orchestrator → Agent 消息\n#[derive(Serialize, Deserialize, Type, Debug)]\n#[serde(tag = \"type\")]\npub enum OrchestratorCommand {\n    WriteInput {\n        content: String,\n    },\n    ClearInput,\n    HealthCheck,\n    Stop,\n}\n```\n\n### Message Format Examples\n\n```json\n// Agent → Orchestrator: 新消息\n{\n  \"type\": \"MessageNew\",\n  \"content\": \"你好，最近怎么样？\",\n  \"sender\": \"张三\",\n  \"timestamp\": \"2024-01-23T10:30:00\"\n}\n\n// Orchestrator → Agent: 写入输入框\n{\n  \"type\": \"WriteInput\",\n  \"content\": \"很好，谢谢！\"\n}\n\n// Agent → Orchestrator: 命令响应\n{\n  \"type\": \"CommandResponse\",\n  \"success\": true\n}\n\n// Agent → Orchestrator: 错误\n{\n  \"type\": \"Error\",\n  \"message\": \"无法访问微信窗口\",\n  \"code\": \"ACCESS_DENIED\"\n}\n```\n\n## Rust Orchestrator Implementation\n\n### Agent Process Manager\n\n```rust\nuse tokio::process::{Child, Command};\nuse tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};\nuse std::process::Stdio;\n\npub struct AgentProcess {\n    child: Child,\n    stdin: tokio::process::ChildStdin,\n    stdout_reader: BufReader<tokio::process::ChildStdout>,\n}\n\nimpl AgentProcess {\n    pub async fn spawn(agent_path: &str) -> anyhow::Result<Self> {\n        let mut child = Command::new(agent_path)\n            .stdin(Stdio::piped())\n            .stdout(Stdio::piped())\n            .stderr(Stdio::piped())\n            .spawn()?;\n\n        let stdin = child.stdin.take()\n            .ok_or_else(|| anyhow!(\"无法获取 Agent stdin\"))?;\n\n        let stdout = child.stdout.take()\n            .ok_or_else(|| anyhow!(\"无法获取 Agent stdout\"))?;\n\n        let stdout_reader = BufReader::new(stdout);\n\n        Ok(Self {\n            child,\n            stdin,\n            stdout_reader,\n        })\n    }\n\n    pub async fn send_command(&mut self, command: OrchestratorCommand) -> anyhow::Result<()> {\n        let json = serde_json::to_string(&command)?;\n        self.stdin.write_all(json.as_bytes()).await?;\n        self.stdin.write_all(b\"\\n\").await?;\n        self.stdin.flush().await?;\n        Ok(())\n    }\n\n    pub async fn read_message(&mut self) -> anyhow::Result<AgentMessage> {\n        let mut line = String::new();\n        self.stdout_reader.read_line(&mut line).await?;\n\n        if line.is_empty() {\n            return Err(anyhow!(\"Agent 已关闭输出\"));\n        }\n\n        let message = serde_json::from_str(&line)?;\n        Ok(message)\n    }\n\n    pub async fn kill(&mut self) -> anyhow::Result<()> {\n        self.child.kill().await?;\n        Ok(())\n    }\n}\n```\n\n### Message Handler Pattern\n\n```rust\nuse tokio::sync::mpsc;\n\npub struct AgentHandler {\n    agent: AgentProcess,\n    message_tx: mpsc::UnboundedSender<AgentMessage>,\n}\n\nimpl AgentHandler {\n    pub async fn start(agent_path: &str) -> anyhow::Result<(Self, mpsc::UnboundedReceiver<AgentMessage>)> {\n        let agent = AgentProcess::spawn(agent_path).await?;\n        let (message_tx, message_rx) = mpsc::unbounded_channel();\n\n        let handler = Self {\n            agent,\n            message_tx,\n        };\n\n        Ok((handler, message_rx))\n    }\n\n    pub async fn run(mut self) {\n        loop {\n            match self.agent.read_message().await {\n                Ok(message) => {\n                    if self.message_tx.send(message).is_err() {\n                        tracing::error!(\"消息接收器已关闭\");\n                        break;\n                    }\n                }\n                Err(e) => {\n                    tracing::error!(error = %e, \"读取 Agent 消息失败\");\n                    break;\n                }\n            }\n        }\n    }\n\n    pub async fn send_command(&mut self, command: OrchestratorCommand) -> anyhow::Result<()> {\n        self.agent.send_command(command).await\n    }\n}\n```\n\n### Error Handling with Timeout\n\n```rust\nuse tokio::time::{timeout, Duration};\n\npub async fn send_command_with_timeout(\n    agent: &mut AgentProcess,\n    command: OrchestratorCommand,\n    timeout_secs: u64,\n) -> anyhow::Result<()> {\n    timeout(\n        Duration::from_secs(timeout_secs),\n        agent.send_command(command)\n    )\n    .await\n    .map_err(|_| anyhow!(\"发送命令超时\"))?\n}\n\npub async fn read_message_with_timeout(\n    agent: &mut AgentProcess,\n    timeout_secs: u64,\n) -> anyhow::Result<AgentMessage> {\n    timeout(\n        Duration::from_secs(timeout_secs),\n        agent.read_message()\n    )\n    .await\n    .map_err(|_| anyhow!(\"读取消息超时\"))?\n}\n```\n\n## Python Agent Implementation\n\n### Message Sender Pattern\n\n```python\nimport json\nimport sys\nfrom typing import Dict, Any\n\nclass MessageSender:\n    \"\"\"发送消息到 Rust Orchestrator (stdout)\"\"\"\n\n    @staticmethod\n    def send_message(message: Dict[str, Any]):\n        \"\"\"\n        发送 JSON 消息到 stdout\n\n        Args:\n            message: 消息字典，必须包含 ''type'' 字段\n        \"\"\"\n        json_str = json.dumps(message, ensure_ascii=False)\n        print(json_str, flush=True)\n\n    @staticmethod\n    def send_message_new(content: str, sender: str, timestamp: str):\n        \"\"\"发送新消息通知\"\"\"\n        message = {\n            \"type\": \"MessageNew\",\n            \"content\": content,\n            \"sender\": sender,\n            \"timestamp\": timestamp\n        }\n        MessageSender.send_message(message)\n\n    @staticmethod\n    def send_command_response(success: bool, error: str = None):\n        \"\"\"发送命令响应\"\"\"\n        message = {\n            \"type\": \"CommandResponse\",\n            \"success\": success\n        }\n        if error:\n            message[\"error\"] = error\n        MessageSender.send_message(message)\n\n    @staticmethod\n    def send_error(error_message: str, code: str = None):\n        \"\"\"发送错误\"\"\"\n        message = {\n            \"type\": \"Error\",\n            \"message\": error_message\n        }\n        if code:\n            message[\"code\"] = code\n        MessageSender.send_message(message)\n\n    @staticmethod\n    def send_heartbeat(timestamp: float):\n        \"\"\"发送心跳\"\"\"\n        message = {\n            \"type\": \"Heartbeat\",\n            \"timestamp\": timestamp\n        }\n        MessageSender.send_message(message)\n```\n\n### Command Receiver Pattern\n\n```python\nimport threading\nfrom typing import Callable, Dict, Any\n\nclass CommandReceiver:\n    \"\"\"从 Rust Orchestrator 接收命令 (stdin)\"\"\"\n\n    def __init__(self):\n        self.handlers: Dict[str, Callable] = {}\n        self.running = True\n\n    def register_handler(self, command_type: str, handler: Callable):\n        \"\"\"注册命令处理器\"\"\"\n        self.handlers[command_type] = handler\n\n    def start_listening(self):\n        \"\"\"开始监听命令（阻塞）\"\"\"\n        try:\n            for line in sys.stdin:\n                if not self.running:\n                    break\n\n                try:\n                    command = json.loads(line.strip())\n                    self.handle_command(command)\n                except json.JSONDecodeError as e:\n                    MessageSender.send_error(f\"JSON 解析失败: {str(e)}\", \"JSON_PARSE_ERROR\")\n                except Exception as e:\n                    MessageSender.send_error(f\"处理命令失败: {str(e)}\", \"COMMAND_HANDLER_ERROR\")\n\n        except KeyboardInterrupt:\n            pass\n        except Exception as e:\n            MessageSender.send_error(f\"命令监听错误: {str(e)}\", \"LISTENER_ERROR\")\n\n    def start_listening_async(self):\n        \"\"\"在后台线程中监听命令\"\"\"\n        thread = threading.Thread(target=self.start_listening, daemon=True)\n        thread.start()\n        return thread\n\n    def handle_command(self, command: Dict[str, Any]):\n        \"\"\"处理收到的命令\"\"\"\n        command_type = command.get(''type'')\n\n        if command_type not in self.handlers:\n            MessageSender.send_error(f\"未知命令类型: {command_type}\", \"UNKNOWN_COMMAND\")\n            return\n\n        try:\n            handler = self.handlers[command_type]\n            result = handler(command)\n\n            # 如果处理器返回 True，发送成功响应\n            if result is True or result is None:\n                MessageSender.send_command_response(success=True)\n            elif result is False:\n                MessageSender.send_command_response(success=False, error=\"处理失败\")\n\n        except Exception as e:\n            MessageSender.send_command_response(success=False, error=str(e))\n\n    def stop(self):\n        \"\"\"停止监听\"\"\"\n        self.running = False\n```\n\n### Complete Agent Example\n\n```python\nfrom wechat_monitor import WeChatMonitor\nfrom input_writer import WeChatInputWriter\n\nclass Agent:\n    def __init__(self):\n        self.monitor = WeChatMonitor()\n        self.input_writer = WeChatInputWriter()\n        self.command_receiver = CommandReceiver()\n\n        # 注册命令处理器\n        self.command_receiver.register_handler(\"WriteInput\", self.handle_write_input)\n        self.command_receiver.register_handler(\"ClearInput\", self.handle_clear_input)\n        self.command_receiver.register_handler(\"HealthCheck\", self.handle_health_check)\n        self.command_receiver.register_handler(\"Stop\", self.handle_stop)\n\n    def handle_write_input(self, command: Dict[str, Any]) -> bool:\n        \"\"\"处理写入输入框命令\"\"\"\n        content = command.get(''content'', '''')\n        return self.input_writer.write_to_input(content)\n\n    def handle_clear_input(self, command: Dict[str, Any]) -> bool:\n        \"\"\"处理清空输入框命令\"\"\"\n        return self.input_writer.clear_input()\n\n    def handle_health_check(self, command: Dict[str, Any]) -> bool:\n        \"\"\"处理健康检查\"\"\"\n        message = {\n            \"type\": \"HealthStatus\",\n            \"status\": \"ok\",\n            \"agent_type\": \"windows_wxauto\"\n        }\n        MessageSender.send_message(message)\n        return None  # 不发送 CommandResponse\n\n    def handle_stop(self, command: Dict[str, Any]) -> bool:\n        \"\"\"处理停止命令\"\"\"\n        self.command_receiver.stop()\n        return True\n\n    def run(self):\n        \"\"\"启动 Agent\"\"\"\n        # 启动命令监听（后台线程）\n        self.command_receiver.start_listening_async()\n\n        # 启动微信监听（主线程，阻塞）\n        self.monitor.start_monitoring()\n\nif __name__ == ''__main__'':\n    agent = Agent()\n    agent.run()\n```\n\n## Swift Agent Implementation\n\n### Message Sender Pattern\n\n```swift\nimport Foundation\n\nclass MessageSender {\n    static func sendMessage(_ message: [String: Any]) {\n        guard let jsonData = try? JSONSerialization.data(withJSONObject: message),\n              let jsonString = String(data: jsonData, encoding: .utf8) else {\n            return\n        }\n\n        print(jsonString)\n        fflush(stdout)\n    }\n\n    static func sendMessageNew(content: String, sender: String, timestamp: String) {\n        let message: [String: Any] = [\n            \"type\": \"MessageNew\",\n            \"content\": content,\n            \"sender\": sender,\n            \"timestamp\": timestamp\n        ]\n        sendMessage(message)\n    }\n\n    static func sendCommandResponse(success: Bool, error: String? = nil) {\n        var message: [String: Any] = [\n            \"type\": \"CommandResponse\",\n            \"success\": success\n        ]\n        if let error = error {\n            message[\"error\"] = error\n        }\n        sendMessage(message)\n    }\n\n    static func sendError(message errorMessage: String, code: String? = nil) {\n        var message: [String: Any] = [\n            \"type\": \"Error\",\n            \"message\": errorMessage\n        ]\n        if let code = code {\n            message[\"code\"] = code\n        }\n        sendMessage(message)\n    }\n}\n```\n\n### Command Receiver Pattern\n\n```swift\nclass CommandReceiver {\n    private var handlers: [String: (([String: Any]) -> Bool)] = [:]\n    private var running = true\n\n    func registerHandler(commandType: String, handler: @escaping ([String: Any]) -> Bool) {\n        handlers[commandType] = handler\n    }\n\n    func startListening() {\n        while running {\n            guard let line = readLine() else {\n                break\n            }\n\n            guard let data = line.data(using: .utf8),\n                  let command = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {\n                MessageSender.sendError(message: \"JSON 解析失败\", code: \"JSON_PARSE_ERROR\")\n                continue\n            }\n\n            handleCommand(command)\n        }\n    }\n\n    func startListeningAsync() {\n        DispatchQueue.global(qos: .userInitiated).async {\n            self.startListening()\n        }\n    }\n\n    private func handleCommand(_ command: [String: Any]) {\n        guard let commandType = command[\"type\"] as? String else {\n            MessageSender.sendError(message: \"命令缺少 type 字段\", code: \"INVALID_COMMAND\")\n            return\n        }\n\n        guard let handler = handlers[commandType] else {\n            MessageSender.sendError(message: \"未知命令类型: \\(commandType)\", code: \"UNKNOWN_COMMAND\")\n            return\n        }\n\n        let success = handler(command)\n        MessageSender.sendCommandResponse(success: success)\n    }\n\n    func stop() {\n        running = false\n    }\n}\n```\n\n## Message Validation\n\n### Rust Validation\n\n```rust\npub fn validate_agent_message(message: &AgentMessage) -> Result<(), String> {\n    match message {\n        AgentMessage::MessageNew { content, sender, .. } => {\n            if content.is_empty() {\n                return Err(\"消息内容为空\".to_string());\n            }\n            if sender.is_empty() {\n                return Err(\"发送者为空\".to_string());\n            }\n            if content.len() > 100000 {\n                return Err(\"消息内容过长\".to_string());\n            }\n        }\n        AgentMessage::Error { message, .. } => {\n            if message.is_empty() {\n                return Err(\"错误消息为空\".to_string());\n            }\n        }\n        _ => {}\n    }\n    Ok(())\n}\n```\n\n### Python Validation\n\n```python\ndef validate_command(command: Dict[str, Any]) -> bool:\n    \"\"\"验证命令格式\"\"\"\n    # 检查必需字段\n    if ''type'' not in command:\n        return False\n\n    cmd_type = command[''type'']\n\n    # 验证特定命令的字段\n    if cmd_type == ''WriteInput'':\n        if ''content'' not in command:\n            return False\n        content = command[''content'']\n        if len(content) > 10000:  # 最大 10KB\n            return False\n\n    return True\n```\n\n## Performance Optimization\n\n### Batch Message Processing\n\n```rust\npub struct MessageBatcher {\n    buffer: Vec<AgentMessage>,\n    max_batch_size: usize,\n    flush_interval: Duration,\n    last_flush: Instant,\n}\n\nimpl MessageBatcher {\n    pub fn new(max_batch_size: usize, flush_interval: Duration) -> Self {\n        Self {\n            buffer: Vec::new(),\n            max_batch_size,\n            flush_interval,\n            last_flush: Instant::now(),\n        }\n    }\n\n    pub fn add_message(&mut self, message: AgentMessage) -> Option<Vec<AgentMessage>> {\n        self.buffer.push(message);\n\n        // 达到批量大小或超时，返回批次\n        if self.buffer.len() >= self.max_batch_size\n            || self.last_flush.elapsed() >= self.flush_interval\n        {\n            return Some(self.flush());\n        }\n\n        None\n    }\n\n    pub fn flush(&mut self) -> Vec<AgentMessage> {\n        let messages = std::mem::take(&mut self.buffer);\n        self.last_flush = Instant::now();\n        messages\n    }\n}\n```\n\n### Async Message Queue\n\n```rust\nuse tokio::sync::mpsc;\n\npub struct AsyncMessageQueue {\n    tx: mpsc::UnboundedSender<AgentMessage>,\n    rx: mpsc::UnboundedReceiver<AgentMessage>,\n}\n\nimpl AsyncMessageQueue {\n    pub fn new() -> Self {\n        let (tx, rx) = mpsc::unbounded_channel();\n        Self { tx, rx }\n    }\n\n    pub fn sender(&self) -> mpsc::UnboundedSender<AgentMessage> {\n        self.tx.clone()\n    }\n\n    pub async fn receive(&mut self) -> Option<AgentMessage> {\n        self.rx.recv().await\n    }\n}\n```\n\n## Testing\n\n### Mock Agent Process\n\n```rust\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use tokio::io::{duplex, AsyncWriteExt};\n\n    #[tokio::test]\n    async fn test_send_command() {\n        let (mut client, mut server) = duplex(1024);\n\n        // 模拟发送命令\n        let command = OrchestratorCommand::WriteInput {\n            content: \"测试内容\".to_string(),\n        };\n        let json = serde_json::to_string(&command).unwrap();\n        client.write_all(json.as_bytes()).await.unwrap();\n        client.write_all(b\"\\n\").await.unwrap();\n\n        // 模拟接收\n        let mut buf = String::new();\n        use tokio::io::AsyncBufReadExt;\n        let mut reader = BufReader::new(server);\n        reader.read_line(&mut buf).await.unwrap();\n\n        let received: OrchestratorCommand = serde_json::from_str(&buf).unwrap();\n        match received {\n            OrchestratorCommand::WriteInput { content } => {\n                assert_eq!(content, \"测试内容\");\n            }\n            _ => panic!(\"错误的命令类型\"),\n        }\n    }\n}\n```\n\n## When to Use This Skill\n\nActivate this skill when:\n- Implementing IPC between Orchestrator and Agents\n- Designing message protocols\n- Working with stdin/stdout communication\n- Handling JSON serialization/deserialization\n- Implementing message validation\n- Optimizing IPC performance\n- Testing Agent communication\n- Debugging IPC issues\n"},"lastSynced":"2026-02-18T06:30:21.131Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring seamless Inter-Process Communication, such as Cursor, Windsurf, or Claude Code, needing to exchange JSON messages via stdin/stdout.","zh":"适用于需要无缝进程间通信的AI代理，例如Cursor、Windsurf或Claude Code，需要通过stdin/stdout交换JSON消息。","ja":"シームレスなプロセス間通信を必要とするAIエージェントに適しています。例えば、Cursor、Windsurf、またはClaude Codeなど、stdin/stdout経由でJSONメッセージを交換する必要があります。","ko":"무엇무엇한 프로세스 간 통신이 필요한 AI 에이전트에 적합합니다. 예를 들어, Cursor, Windsurf 또는 Claude Code와 같은 에이전트는 stdin/stdout을 통해 JSON 메시지를 교환해야 합니다.","es":"Ideal para agentes de IA que requieren una comunicación entre procesos sin problemas, como Cursor, Windsurf o Claude Code, que necesitan intercambiar mensajes JSON a través de stdin/stdout.","fr":"Idéal pour les agents IA nécessitant une communication entre processus transparente, tels que Cursor, Windsurf ou Claude Code, ayant besoin d''échanger des messages JSON via stdin/stdout.","de":"Ideal für KI-Agents, die eine nahtlose Interprozesskommunikation erfordern, wie z. B. Cursor, Windsurf oder Claude Code, die JSON-Nachrichten über stdin/stdout austauschen müssen.","pt":"Ideal para agentes de IA que exigem comunicação entre processos sem interrupções, como Cursor, Windsurf ou Claude Code, que precisam trocar mensagens JSON via stdin/stdout.","ru":"Идеально для агентов ИИ, требующих бесперебойную межпроцессную связь, такой как Cursor, Windsurf или Claude Code, нуждающихся в обмене сообщениями JSON через stdin/stdout.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يتطلب اتصالًا متزامنًا بين العمليات، مثل Cursor أو Windsurf أو Claude Code، والذي يحتاج إلى交換 رسائل JSON من خلال stdin/stdout."},"recommendation":{"en":"Empowers agents to establish bidirectional communication using a JSON protocol, enabling the exchange of line-delimited JSON messages with UTF-8 character encoding, and facilitates integration with Rust Orchestrator and Platform Agents.","zh":"赋予代理建立双向通信的能力，使用JSON协议，实现以UTF-8字符编码的行分隔JSON消息的交换，并促进与Rust Orchestrator和平台代理的集成。","ja":"エージェントが双方向通信を確立する能力を提供します。JSONプロトコルを使用し、UTF-8文字コードの行区切りのJSONメッセージの交換を可能にし、Rust Orchestratorおよびプラットフォームエージェントとの統合を促進します。","ko":"에이전트가 양방향 통신을 설정할 수 있는 능력을 제공하며, JSON 프로토콜을 사용하여 UTF-8 문자 인코딩의 줄 단위 JSON 메시지 교환을 가능하게하며, Rust Orchestrator 및 플랫폼 에이전트와의 통합을 촉진합니다.","es":"Habilita a los agentes a establecer una comunicación bidireccional utilizando un protocolo JSON, lo que permite el intercambio de mensajes JSON delimitados por líneas con codificación de caracteres UTF-8, y facilita la integración con Rust Orchestrator y Platform Agents.","fr":"Permet aux agents d''établir une communication bidirectionnelle en utilisant un protocole JSON, permettant l''échange de messages JSON délimités par des lignes avec une codage de caractères UTF-8, et facilite l''intégration avec Rust Orchestrator et Platform Agents.","de":"Ermöglicht es Agents, eine bidirektionale Kommunikation mit einem JSON-Protokoll herzustellen, wodurch der Austausch von zeilenbegrenzten JSON-Nachrichten mit UTF-8-Zeichencodierung ermöglicht wird, und erleichtert die Integration mit Rust Orchestrator und Platform Agents.","pt":"Permite que os agentes estabeleçam comunicação bidirecional usando um protocolo JSON, possibilitando a troca de mensagens JSON delimitadas por linha com codificação de caracteres UTF-8, e facilita a integração com o Rust Orchestrator e os agentes da plataforma.","ru":"Наделяет агентов возможностью устанавливать двустороннюю связь с использованием протокола JSON, что позволяет обмениваться сообщениями JSON с разделением строк и кодированием символов UTF-8, и облегчает интеграцию с Rust Orchestrator и агентами платформы.","ar":"تمكّن العميل من إنشاء اتصال ثنائي الاتجاه باستخدام بروتوكول JSON، مما يسمح بمشاركة رسائل JSON محددة بفاصل الأسطر وتشفير UTF-8 للأحرف، ويُسهل التكامل مع Rust Orchestrator والعملاء منصة."},"useCases":{"en":["Implementing automated chat reply assistants","Enabling agent-to-agent communication via JSON protocol","Debugging IPC communication issues between agents"],"zh":["实现自动聊天回复助手","通过JSON协议实现代理间通信","调试代理间IPC通信问题"],"ja":["自動チャット応答アシスタントの実装","JSONプロトコルによるエージェント間通信の実現","エージェント間のIPC通信問題のデバッグ"],"ko":["자동 채팅 응답 어시스턴트 구현","JSON 프로토콜을 통한 에이전트 간 통신","에이전트 간 IPC 통신 문제 디버깅"],"es":["Implementar asistentes de respuesta automática de chat","Habilitar la comunicación entre agentes mediante protocolo JSON","Depurar problemas de comunicación IPC entre agentes"],"fr":["Mettre en œuvre des assistants de réponse automatique de chat","Permettre la communication entre agents via le protocole JSON","Déboguer les problèmes de communication IPC entre les agents"],"de":["Automatisierte Chat-Antwort-Assistenten implementieren","Agent-zu-Agent-Kommunikation über JSON-Protokoll ermöglichen","IPC-Kommunikationsprobleme zwischen Agents debuggen"],"pt":["Implementar assistentes de resposta automática de chat","Habilitar comunicação entre agentes via protocolo JSON","Depurar problemas de comunicação IPC entre agentes"],"ru":["Реализовать автоматических помощников для ответов в чате","Включить связь между агентами через протокол JSON","Отладить проблемы связи IPC между агентами"],"ar":["تنفيذ مساعدين للاستجابة الآلية ل دردشة","تمكين الاتصال بين العملاء عبر بروتوكول JSON","تصحيح مشاكل الاتصال بين العمليات بين العملاء"]},"limitations":{"en":["Requires Rust Orchestrator and Platform Agents setup","Limited to JSON protocol via stdin/stdout","UTF-8 character encoding required"],"zh":["需要Rust Orchestrator和平台代理设置","仅限通过stdin/stdout的JSON协议","需要UTF-8字符编码"],"ja":["Rust Orchestratorおよびプラットフォームエージェントの設定が必要","stdin/stdout経由のJSONプロトコルに限定","UTF-8文字コードが必要"],"ko":["Rust Orchestrator 및 플랫폼 에이전트 설정이 필요","stdin/stdout을 통한 JSON 프로토콜만 가능","UTF-8 문자 인코딩 필요"],"es":["Requiere la configuración de Rust Orchestrator y Platform Agents","Limitado al protocolo JSON a través de stdin/stdout","Se requiere codificación de caracteres UTF-8"],"fr":["Nécessite la configuration de Rust Orchestrator et Platform Agents","Limité au protocole JSON via stdin/stdout","Codage de caractères UTF-8 requis"],"de":["Benötigt die Einrichtung von Rust Orchestrator und Platform Agents","Begrenzt auf JSON-Protokoll über stdin/stdout","UTF-8-Zeichencodierung erforderlich"],"pt":["Requer configuração do Rust Orchestrator e dos agentes da plataforma","Limitado ao protocolo JSON via stdin/stdout","Requer codificação de caracteres UTF-8"],"ru":["Требует настройки Rust Orchestrator и агентов платформы","Ограничен протоколом JSON через stdin/stdout","Требует кодировки символов UTF-8"],"ar":["يتطلب إعداد Rust Orchestrator وعملاء المنصة","محدود ببروتوكول JSON عبر stdin/stdout","يتطلب ترميز UTF-8 للأحرف"]},"version":3},"qualityScore":70}');
