INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cortesi/skills/shared-name', 'community', 'cortesi', 'skills', 'cortesi/skills', 'shared-name', 0, 0, 40, '2026-02-18T01:08:43.448Z', '2026-02-18T06:31:30.980Z', NULL, '{"id":"cortesi/skills/shared-name","name":"shared-name","description":{"zh":"共享名称技能（Codex）用于测试多处同名的冲突检测，提供开发者社区分享技能和最佳实践的平台","ja":"共有名前_skill（Codex）は、同一スキル名の複数箇所でのコンフリクト検出をテストするために使用され、開発者コミュニティでスキルとベストプラクティスを共有するプラットフォームを提供する","ko":"공유 이름 스킬(Codex)은 여러 곳에서 동일한 이름 충돌 감지를 테스트하는 데 사용되며 개발자 커뮤니티에서 스킬과 모범 사례를 공유하는 플랫폼을 제공합니다","es":"La habilidad de nombre compartido en Codex existe para probar la detección de conflictos","fr":"La compétence de nom partagé dans Codex existe pour tester la détection des conflits","de":"Die geteilte Name-Fähigkeit in Codex dient zum Testen der Konflikt-Erkennung","pt":"A habilidade de nome compartilhado é uma ferramenta de teste para detecção de conflitos","ru":"Общая навык имени - это инструмент для тестирования обнаружения конфликтов","ar":"مهارات الاسم المشترك هي أداة اختبار للكشف عن الت冲突ات","en":""},"seo":{"title":{"zh":"共享名称技能（Codex）- 多处同名冲突检测","ja":"共有名前_skill（Codex）- 同一スキル名の複数箇所でのコンフリクト検出","ko":"공유 이름 스킬(Codex) - 여러 곳에서 동일한 이름 충돌 감지","es":"Habilidad de nombre compartido: Codex","fr":"Compétence de nom partagé: Codex","de":"Geteilte Name-Fähigkeit: Codex","pt":"Habilidades de Nome Compartilhado - Desenvolvedores","ru":"Общая навык имени - Разработчики","ar":"مهارات الاسم المشترك - مطورون","en":"shared-name"},"description":{"zh":"共享名称技能（Codex）用于测试多处同名的冲突检测，提供开发者社区分享技能和最佳实践的平台","ja":"共有名前_skill（Codex）は、同一スキル名の複数箇所でのコンフリクト検出をテストするために使用され、開発者コミュニティでスキルとベストプラクティスを共有するプラットフォームを提供する","ko":"공유 이름 스킬(Codex)은 여러 곳에서 동일한 이름 충돌 감지를 테스트하는 데 사용되며 개발자 커뮤니티에서 스킬과 모범 사례를 공유하는 플랫폼을 제공합니다","es":"La habilidad de nombre compartido en Codex existe para probar la detección de conflictos","fr":"La compétence de nom partagé dans Codex existe pour tester la détection des conflits","de":"Die geteilte Name-Fähigkeit in Codex dient zum Testen der Konflikt-Erkennung","pt":"A habilidade de nome compartilhado é uma ferramenta de teste para detecção de conflitos","ru":"Общая навык имени - это инструмент для тестирования обнаружения конфликтов","ar":"مهارات الاسم المشترك هي أداة اختبار للكشف عن الت冲突ات","en":""},"definition":{"en":""},"features":{"zh":["冲突检测","多处同名测试","开发者社区","技能分享","最佳实践"],"ja":["コンフリクト検出","同一スキル名の複数箇所でのテスト","開発者コミュニティ","スキルの共有","ベストプラクティス"],"ko":["충돌 감지","여러 곳에서 동일한 이름 테스트","개발자 커뮤니티","스킬 공유","모범 사례"],"es":["Detección de conflictos","Nombre compartido","Función de prueba","Integración con Codex","Informes de conflictos"],"fr":["Détection des conflits","Nom partagé","Fonction de test","Intégration avec Codex","Rapports de conflits"],"de":["Konflikt-Erkennung","Geteilte Name","Testfunktion","Integration mit Codex","Konfliktberichte"],"pt":["Detecção de conflitos","Teste de habilidades","Desenvolvimento de software","Ferramenta de teste","Codex"],"ru":["Обнаружение конфликтов","Тестирование навыков","Разработка программного обеспечения","Инструмент для тестирования","Codex"],"ar":["اكتشاف الت冲突ات","اختبار المهارات","تطوير البرمجيات","أداة اختبار","كودكس"]},"keywords":{"zh":["共享名称技能","Codex","冲突检测","开发者社区","技能分享","最佳实践","同名测试"],"ja":["共有名前_skill","Codex","コンフリクト検出","開発者コミュニティ","スキルの共有","ベストプラクティス","同一スキル名のテスト"],"ko":["공유 이름 스킬","Codex","충돌 감지","개발자 커뮤니티","스킬 공유","모범 사례","여러 곳에서 동일한 이름 테스트"],"es":["nombre compartido","detección de conflictos","Codex","desarrollo de habilidades","integración de habilidades","pruebas de habilidades"],"fr":["nom partagé","détection des conflits","Codex","développement de compétences","intégration de compétences","tests de compétences"],"de":["geteilte Name","Konflikt-Erkennung","Codex","Fähigkeitsentwicklung","Fähigkeitsintegration","Fähigkeitstests"],"pt":["habilidade de nome compartilhado","desenvolvimento de software","teste de habilidades","detecção de conflitos","ferramenta de teste","codex","desenvolvedores"],"ru":["общая навык имени","разработка программного обеспечения","тестирование навыков","обнаружение конфликтов","инструмент для тестирования","codex","разработчики"],"ar":["مهارات الاسم المشترك","تطوير البرمجيات","اختبار المهارات","اكتشاف الت冲突ات","أداة اختبار","كودكس","مطورون"]}},"owner":"cortesi","repo":"skills","repoPath":"cortesi/skills","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"shared-name","description":"A skill with a name that might conflict. Use for testing conflict detection.","bodyPreview":"# Shared Name Skill (Codex)\n\nThis skill exists to test conflict detection when the same skill name appears in multiple places.\n\n## Instructions\n\nReport that this is the Codex version of the shared-name skill.","body":"# Shared Name Skill (Codex)\n\nThis skill exists to test conflict detection when the same skill name appears in multiple places.\n\n## Instructions\n\nReport that this is the Codex version of the shared-name skill.\n"},"lastSynced":"2026-02-18T06:31:30.980Z","agentAnalysis":{"suitability":{"en":"Perfect for Conflict Detection Agents needing to identify duplicate skill names across multiple repositories.","zh":"非常适合需要在多个仓库中识别重复技能名称的冲突检测代理。","ja":"複数のリポジトリで重複するスキル名を識別する必要があるコンフリクト検出エージェントに最適です。","ko":"複수 저장소에서 중복되는 스킬 이름을 식별해야 하는 충돌 감지 에이전트에게 완벽합니다.","es":"Perfecto para agentes de detección de conflictos que necesitan identificar nombres de habilidades duplicados en varios repositorios.","fr":"Parfait pour les agents de détection de conflits ayant besoin d''identifier des noms de compétences en double dans plusieurs référentiels.","de":"Perfekt für Konflikt-Erkennungsagenten, die doppelte Fertigkeitsnamen in mehreren Repositorien identifizieren müssen.","pt":"Perfeito para Agentes de Detecção de Conflitos que precisam identificar nomes de habilidades duplicados em vários repositórios.","ru":"Идеально подходит для агентов обнаружения конфликтов, которым необходимо определять дублирующиеся имена навыков в нескольких репозиториях.","ar":"مثالي لعمليات وكيل الكشف عن الصراعات التي تحتاج إلى تحديد أسماء المهارات المكررة عبر مستودعات متعددة."},"recommendation":{"en":"Empowers agents to detect and report conflicts when the same skill name appears in multiple places, ensuring data integrity and preventing errors using conflict detection protocols and filename analysis.","zh":"赋予代理检测和报告冲突的能力，当同一个技能名称出现在多个地方时，确保数据完整性并防止使用冲突检测协议和文件名分析的错误。","ja":"エージェントに複数の場所で同じスキル名が表示される場合のコンフリクトを検出して報告する機能を付与し、データの完全性を確保し、コンフリクト検出プロトコルとファイル名分析を使用してエラーを防ぎます。","ko":"에이전트가 동일한 스킬 이름이 여러 곳에 표시될 때 충돌을 감지하고 보고하는 기능을 부여하여 데이터 무결성을 보장하고 충돌 감지 프로토콜 및 파일 이름 분석을 사용하여 오류를 방지합니다.","es":"Habilita a los agentes a detectar y informar conflictos cuando el mismo nombre de habilidad aparece en varios lugares, garantizando la integridad de los datos y evitando errores mediante protocolos de detección de conflictos y análisis de nombres de archivos.","fr":"Permet aux agents de détecter et de signaler les conflits lorsque le même nom de compétence apparaît à plusieurs endroits, assurant l''intégrité des données et prévenant les erreurs en utilisant des protocoles de détection de conflits et d''analyse de noms de fichiers.","de":"Ermächtigt Agenten, Konflikte zu erkennen und zu melden, wenn derselbe Fertigkeitsname an mehreren Stellen erscheint, und gewährleistet so die Datenintegrität und verhindert Fehler unter Verwendung von Konflikt-Erkennungsprotokollen und Dateinamenanalyse.","pt":"Habilita os agentes a detectar e relatar conflitos quando o mesmo nome de habilidade aparece em vários lugares, garantindo a integridade dos dados e prevenindo erros usando protocolos de detecção de conflitos e análise de nomes de arquivos.","ru":"Наделяет агентов возможностью обнаруживать и сообщать о конфликтах, когда одно и то же имя навыка появляется в нескольких местах, обеспечивая целостность данных и предотвращая ошибки с помощью протоколов обнаружения конфликтов и анализа имен файлов.","ar":"تمكين الوكلاء من الكشف عن الصراعات وتقديم تقارير عندما يظهر نفس اسم المهارة في أماكن متعددة، مما يضمن سلامة البيانات ومنع الأخطاء باستخدام بروتوكولات الكشف عن الصراعات وتحليل أسماء الملفات."},"useCases":{"en":["Detecting duplicate skill names","Resolving naming conflicts","Testing skill name uniqueness"],"zh":["检测重复技能名称","解决命名冲突","测试技能名称唯一性"],"ja":["重複するスキル名の検出","命名のコンフリクトを解決する","スキル名の一意性をテストする"],"ko":["중복 스킬 이름 감지","이름 충돌 해결","스킬 이름 고유성 테스트"],"es":["Detección de nombres de habilidades duplicados","Resolución de conflictos de nomenclatura","Pruebas de unicidad de nombres de habilidades"],"fr":["Détection de noms de compétences en double","Résolution de conflits de dénomination","Tests d''unicité des noms de compétences"],"de":["Erkennung doppelter Fertigkeitsnamen","Auflösung von Benennungskonflikten","Tests der Eindeutigkeit von Fertigkeitsnamen"],"pt":["Detecção de nomes de habilidades duplicados","Resolução de conflitos de nomenclatura","Teste de unicidade de nomes de habilidades"],"ru":["Обнаружение дублирующихся имен навыков","Решение конфликтов именования","Тестирование уникальности имен навыков"],"ar":["الكشف عن أسماء المهارات المكررة","حل النزاعات في التسمية","اختبار فريدية أسماء المهارات"]},"limitations":{"en":["Requires access to skill repository metadata","Limited to text-based skill name analysis"],"zh":["需要访问技能仓库元数据","仅限基于文本的技能名称分析"],"ja":["スキルリポジトリのメタデータへのアクセスが必要","テキストベースのスキル名分析のみ"],"ko":["스킬 저장소 메타데이터에 대한 액세스가 필요함","텍스트 기반의 스킬 이름 분석만 가능"],"es":["Requiere acceso a metadatos del repositorio de habilidades","Limitado al análisis de nombres de habilidades basado en texto"],"fr":["Nécessite un accès aux métadonnées du référentiel de compétences","Limité à l''analyse des noms de compétences basée sur le texte"],"de":["Erfordert Zugriff auf Metadaten des Fertigkeits-Repositorys","Begrenzt auf textbasierte Fertigkeitsnamenanalyse"],"pt":["Requer acesso a metadados do repositório de habilidades","Limitado à análise de nomes de habilidades baseada em texto"],"ru":["Требует доступа к метаданным репозитория навыков","Ограничен анализом имен навыков на основе текста"],"ar":["يتطلب الوصول إلى بيانات تعريف المستودع للمهارات","محدود بالتحليل القائم على النص لأسماء المهارات"]},"version":3},"qualityScore":40}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('djaiss/journalOS/modules-readme-updater', 'community', 'djaiss', 'journalOS', 'djaiss/journalOS', 'modules-readme-updater', 0, 0, 55, '2026-02-18T01:08:43.448Z', '2026-02-18T06:31:26.529Z', NULL, '{"id":"djaiss/journalOS/modules-readme-updater","name":"modules-readme-updater","description":{"zh":"modules-readme-updater 技能自动更新 JournalOS 项目的 README.md 文档，确保模块文档准确、最新","ja":"modules-readme-updater スキルは JournalOS プロジェクトの README.md ドキュメントを自動更新し、モジュールのドキュメントを正確に保つ","ko":"modules-readme-updater 스킬은 JournalOS 프로젝트의 README.md 문서를 자동으로 업데이트 하여 모듈 문서를 정확하게 유지합니다","es":"El actualizador de README de módulos es una habilidad que actualiza la documentación de proyecto para reflejar los módulos existentes de forma clara y consistente.","fr":"La mise à jour de la page de garde des modules est une fonctionnalité qui met à jour la documentation du projet pour refléter les modules existants de manière claire et cohérente.","de":"Der Modul-README-Aktualisierer ist eine Funktion, die die Projektdokumentation aktualisiert, um die vorhandenen Module klar und konsistent widerzuspiegeln.","pt":"O atualizador de README de módulos é uma ferramenta que atualiza o arquivo README.md do projeto para refletir os módulos existentes de forma clara e consistente.","ru":"Обновлятор README модулей - это инструмент, который обновляет файл README.md проекта, чтобы он точно отражал существующие модули в четкой и последовательной форме.","ar":"محدّث ملف README للمكونات الإضافية هو أداة تحديث ملف README.md للمشروع ليعكس المكونات الإضافية الحالية بطريقة واضحة ومنسقة.","en":"JournalOS is a privacy-first, self-hosted personal journaling system with modular daily tracking (sleep, mood, work, health, and more)."},"seo":{"title":{"zh":"JournalOS 模块自动生成文档","ja":"JournalOS モジュール自動ドキュメント更新","ko":"JournalOS 모듈 자동 문서화 업데이트","es":"Actualizador de README de módulos","fr":"Mise à jour de la page de garde des modules","de":"Modul-README-Aktualisierer","pt":"Atualizador de README de Módulos","ru":"Обновлятор README модулей","ar":"محدّث ملف README للمكونات الإضافية","en":"modules-readme-updater"},"description":{"zh":"modules-readme-updater 技能自动更新 JournalOS 项目的 README.md 文档，确保模块文档准确、最新","ja":"modules-readme-updater スキルは JournalOS プロジェクトの README.md ドキュメントを自動更新し、モジュールのドキュメントを正確に保つ","ko":"modules-readme-updater 스킬은 JournalOS 프로젝트의 README.md 문서를 자동으로 업데이트 하여 모듈 문서를 정확하게 유지합니다","es":"El actualizador de README de módulos es una habilidad que actualiza la documentación de proyecto para reflejar los módulos existentes de forma clara y consis...","fr":"La mise à jour de la page de garde des modules est une fonctionnalité qui met à jour la documentation du projet pour refléter les modules existants de manièr...","de":"Der Modul-README-Aktualisierer ist eine Funktion, die die Projektdokumentation aktualisiert, um die vorhandenen Module klar und konsistent widerzuspiegeln.","pt":"O atualizador de README de módulos é uma ferramenta que atualiza o arquivo README.md do projeto para refletir os módulos existentes de forma clara e consiste...","ru":"Обновлятор README модулей - это инструмент, который обновляет файл README.md проекта, чтобы он точно отражал существующие модули в четкой и последовательной ...","ar":"محدّث ملف README للمكونات الإضافية هو أداة تحديث ملف README.md للمشروع ليعكس المكونات الإضافية الحالية بطريقة واضحة ومنسقة.","en":"JournalOS is a privacy-first, self-hosted personal journaling system with modular daily tracking (sleep, mood, work, health, and more)."},"definition":{"en":"JournalOS is a privacy-first, self-hosted personal journaling system with modular daily tracking (sleep, mood, work, health, and more)."},"features":{"zh":["自动更新 README.md 文档","确保模块文档准确、最新","支持模块添加、删除和重命名","文档以清晰、连贯的结构组织","模块列表按字母顺序排列"],"ja":["README.md ドキュメントを自動更新","モジュールのドキュメントを正確に保つ","モジュールの追加、削除、名前変更をサポート","ドキュメントを明確な構造で組織","モジュールリストをアルファベット順に並べる"],"ko":["README.md 문서를 자동으로 업데이트","모듈 문서를 정확하게 유지","모듈 추가, 삭제, 이름 변경을 지원","문서를 명확한 구조로 조직","모듈 목록을 알파벳 순으로 정렬"],"es":["Actualiza la documentación de proyecto de forma automática","Mantiene la consistencia en la documentación de módulos","Refleja los módulos existentes de forma clara y organizada","Permite la actualización de la documentación después de agregar o eliminar módulos","Mantiene la documentación alfabéticamente organizada"],"fr":["Met à jour la documentation du projet de manière automatique","Maintient la cohérence dans la documentation des modules","Réfléchit les modules existants de manière claire et organisée","Permet la mise à jour de la documentation après ajout ou suppression de modules","Maintient la documentation organisée de manière alphabétique"],"de":["Aktualisiert die Projektdokumentation automatisch","Hält die Konsistenz in der Modul-Dokumentation aufrecht","Spiegelt die vorhandenen Module klar und organisiert wider","Ermöglicht die Aktualisierung der Dokumentation nach Hinzufügen oder Entfernen von Modulen","Hält die Dokumentation alphabetisch organisiert"],"pt":["Atualiza o arquivo README.md do projeto","Reflete os módulos existentes de forma clara e consistente","Garante a organização e a consistência da documentação","Atualiza a documentação automaticamente quando novos módulos são adicionados ou removidos","Mantém a documentação organizada alfabeticamente"],"ru":["Обновляет файл README.md проекта","Точно отражает существующие модули в четкой и последовательной форме","Гарантирует организацию и последовательность документации","Автоматически обновляет документацию при добавлении или удалении новых модулей","Сохраняет документацию в алфавитном порядке"],"ar":["يحديث ملف README.md للمشروع","يعكس المكونات الإضافية الحالية بطريقة واضحة ومنسقة","يضمن تنظيم الوثائق و συνέافتها","يحديث الوثائق تلقائيًا عند إضافة أو إزالة مكونات إضافية جديدة","يحافظ على الوثائق منظمة أبجديًا"]},"keywords":{"zh":["JournalOS","模块自动文档","README.md 更新","模块管理","自动化工具","开发者工具"],"ja":["JournalOS","モジュール自動ドキュメント","README.md 更新","モジュール管理","自動化ツール","開発者ツール"],"ko":["JournalOS","모듈 자동 문서화","README.md 업데이트","모듈 관리","자동화 도구","개발자 도구"],"es":["actualizador de README","documentación de módulos","automatización de documentación","herramientas de desarrollo","gestión de proyectos","documentación de proyecto","módulos de journaling","JournalOS"],"fr":["mise à jour de la page de garde","documentation des modules","automatisation de la documentation","outils de développement","gestion de projets","documentation de projet","modules de journaling","JournalOS"],"de":["README-Aktualisierer","Modul-Dokumentation","Automatisierung der Dokumentation","Entwicklungstools","Projektmanagement","Projektdokumentation","Journaling-Module","JournalOS"],"pt":["atualizador de README","módulos de projeto","documentação de projeto","organização de documentação","ferramentas de desenvolvimento","desenvolvimento de software","gestão de projeto"],"ru":["обновлятор README","модули проекта","документация проекта","организация документации","инструменты разработки","разработка программного обеспечения","управление проектом"],"ar":["محدّث ملف README","مكونات إضافية للمشروع","وثائق المشروع","تنظيم الوثائق","أدوات التطوير","تطوير البرمجيات","إدارة المشروع"]}},"owner":"djaiss","repo":"journalOS","repoPath":"djaiss/journalOS","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"modules-readme-updater","description":"Update the README.md file to list all available journal modules under the Features section. Use when adding, removing, or reorganizing modules and keeping documentation in sync.","bodyPreview":"# Modules README Updater\n\nThis Skill updates the project README.md to accurately document all existing journal modules in a clear, consistent, and properly indented structure under the Features section.\n\n## When to use this Skill\n\nUse this Skill when:\n- A new module is added or removed\n- Module names change\n- The README documentation is outdated\n- You want to ensure modules are documented consistently and alphabetically\n\n## Instructions\n\n### Step 1: Locate the insertion point\n\n1. Open README.md.","body":"# Modules README Updater\n\nThis Skill updates the project README.md to accurately document all existing journal modules in a clear, consistent, and properly indented structure under the Features section.\n\n## When to use this Skill\n\nUse this Skill when:\n- A new module is added or removed\n- Module names change\n- The README documentation is outdated\n- You want to ensure modules are documented consistently and alphabetically\n\n## Instructions\n\n### Step 1: Locate the insertion point\n\n1. Open README.md.\n2. Start updating from line 12.\n3. Preserve existing indentation and formatting.\n\n### Step 2: Update the Features section\n\n1. Ensure the section header exists:\n\n### Features\n\n2. Under Features, add or update the parent bullet:\n\n- Daily logging of your life\n\n### Step 3: List all modules as sub-items\n\n1. Add all modules as child list items under “Daily logging of your life”.\n2. Each module must:\n   - Be indented as a sub-list\n   - Represent exactly one module\n   - Use consistent naming\n\nExample structure:\n\n### Features\n\n- Daily logging of your life\n  - Energy\n  - Health\n  - Mood\n  - Sexual activity\n  - Sleep\n\n### Step 4: Alphabetical ordering\n\n1. Sort all module names alphabetically.\n2. Do not group, filter, or reorder manually beyond alphabetical order.\n3. Do not omit any existing module.\n\n### Step 5: Formatting rules\n\n- Use spaces, not tabs\n- Keep indentation consistent\n- Do not add descriptions or extra text\n- Do not modify other sections of README.md\n\n## Validation checklist\n\n- README.md updated starting at line 12\n- Features section exists\n- “Daily logging of your life” is the parent item\n- All modules are listed\n- Modules are alphabetically ordered\n- Markdown indentation is correct\n- No unrelated content was changed\n\n## Output expectation\n\nThe Features section clearly documents all journal modules as sub-features of daily life logging, using clean and valid Markdown.\n"},"lastSynced":"2026-02-18T06:31:26.529Z","agentAnalysis":{"suitability":{"en":"Perfect for Maintenance Agents needing automated documentation updates for modular projects like JournalOS","zh":"非常适合需要为模块化项目（如JournalOS）进行自动化文档更新的维护型智能体","ja":"JournalOSのようなモジュール型プロジェクトの自動化されたドキュメント更新を必要とするメンテナンスエージェントに最適です","ko":"JournalOS와 같은 모듈식 프로젝트를 위한 자동화된 문서 업데이트가 필요한 유지보수 에이전트에 완벽하게 적합합니다","es":"Perfecto para agentes de mantenimiento que necesitan actualizaciones de documentación automatizadas para proyectos modulares como JournalOS","fr":"Parfait pour les agents de maintenance ayant besoin de mises à jour de documentation automatisées pour des projets modulaires comme JournalOS","de":"Perfekt für Wartungsagenten, die automatisierte Dokumentenaktualisierungen für modulare Projekte wie JournalOS benötigen","pt":"Perfeito para Agentes de Manutenção que necessitam de atualizações de documentação automatizadas para projetos modulares como o JournalOS","ru":"Идеально подходит для агентов обслуживания, которым необходимы автоматические обновления документации для модульных проектов, таких как JournalOS","ar":"مثالي لعميل الصيانة الذين يحتاجون إلى تحديثات وثائقية آلية لمشاريع مودULAR مثل JournalOS"},"recommendation":{"en":"Empowers agents to maintain accurate and consistent README documentation by automatically updating module lists in Markdown format, ensuring compliance with project standards and alleviating manual documentation burdens","zh":"通过自动以Markdown格式更新模块列表，使智能体能够维护准确且一致的README文档，确保符合项目标准并减轻手动文档负担","ja":"Markdown形式でモジュールリストを自動更新することで、エージェントが正確で一貫性のあるREADMEドキュメントを維持できるようにし、プロジェクト標準への準拠を確保し、手動ドキュメント作業の負担を軽減します","ko":"Markdown 형식으로 모듈 목록을 자동 업데이트하여 에이전트가 정확하고 일관된 README 문서를 유지할 수 있도록 지원하며, 프로젝트 표준을 준수하고 수동 문서화 부담을 덜어줍니다","es":"Habilita a los agentes a mantener una documentación de README precisa y coherente actualizando automáticamente las listas de módulos en formato Markdown, garantizando el cumplimiento de los estándares del proyecto y reduciendo las cargas de documentación manual","fr":"Permet aux agents de maintenir une documentation de README précise et cohérente en mettant à jour automatiquement les listes de modules au format Markdown, assurant ainsi le respect des normes du projet et allégeant les charges de documentation manuelle","de":"Ermächtigt die Agenten, eine genaue und konsistente README-Dokumentation zu pflegen, indem sie automatisch Modullisten im Markdown-Format aktualisieren, was die Einhaltung der Projektstandards gewährleistet und die manuelle Dokumentationsbelastung verringert","pt":"Habilita os agentes a manter a documentação precisa e consistente do README, atualizando automaticamente as listas de módulos no formato Markdown, garantindo a conformidade com os padrões do projeto e aliviando as cargas de documentação manual","ru":"Наделяет агентов возможностью поддерживать точную и последовательную документацию README, автоматически обновляя списки модулей в формате Markdown, обеспечивая соответствие стандартам проекта и снижая ручные документационные нагрузки","ar":"يمنح الوكلاء القدرة على الحفاظ على توثيق دقيق ومتسق لملف README، من خلال تحديث قوائم الوحدات تلقائيًا بالتنسيق Markdown، وضمان الامتثال لمعايير المشروع وتخفيف العبء الوثائقي اليدوي"},"useCases":{"en":["Updating module documentation after adding or removing features","Standardizing module lists across multiple repositories","Automating README maintenance for projects with frequently changing modules"],"zh":["添加或移除功能后更新模块文档","跨多个仓库标准化模块列表","为模块频繁变更的项目自动化README维护"],"ja":["機能の追加または削除後のモジュールドキュメントの更新","複数のリポジトリにわたるモジュールリストの標準化","モジュールが頻繁に変更されるプロジェクトのREADMEメンテナンスの自動化"],"ko":["기능 추가 또는 제거 후 모듈 문서 업데이트","여러 저장소에 걸친 모듈 목록 표준화","모듈이 자주 변경되는 프로젝트의 README 유지보수 자동화"],"es":["Actualizar la documentación de módulos después de agregar o eliminar características","Establecer listas de módulos estándar en varios repositorios","Automatizar el mantenimiento de README para proyectos con módulos que cambian con frecuencia"],"fr":["Mettre à jour la documentation de modules après avoir ajouté ou supprimé des fonctionnalités","Normaliser les listes de modules à travers plusieurs référentiels","Automatiser la maintenance de README pour les projets ayant des modules qui changent fréquemment"],"de":["Aktualisieren der Moduldokumentation nach dem Hinzufügen oder Entfernen von Funktionen","Standardisieren von Modullisten in mehreren Repositorys","Automatisieren der Wartung von README für Projekte mit häufig ändernden Modulen"],"pt":["Atualizar a documentação do módulo após adicionar ou remover recursos","Padronizar as listas de módulos em vários repositórios","Automatizar a manutenção do arquivo README para projetos com módulos que mudam frequentemente"],"ru":["Обновление документации модуля после добавления или удаления функций","Стандартизация списков модулей в нескольких репозиториях","Автоматизация обслуживания файла README для проектов с часто меняющимися модулями"],"ar":["تحديث توثيق الوحدة بعد إضافة أو إزالة الميزات","تقييس قوائم الوحدات عبر مستودعات متعددة","تأهيل صيانة ملف README لأي مشاريع ذات وحدات تتغير بشكل متكرر"]},"limitations":{"en":["Requires access to the project''s README.md file","Limited to updating module documentation in Markdown format"],"zh":["需要访问项目的README.md文件","仅限于以Markdown格式更新模块文档"],"ja":["プロジェクトのREADME.mdファイルへのアクセスが必要","Markdown形式でのモジュールドキュメントの更新に限定される"],"ko":["프로젝트의 README.md 파일에 대한 접근 권한이 필요함","Markdown 형식으로 모듈 문서를 업데이트하는 데 제한됨"],"es":["Requiere acceso al archivo README.md del proyecto","Limitado a la actualización de la documentación de módulos en formato Markdown"],"fr":["Nécessite l''accès au fichier README.md du projet","Limité à la mise à jour de la documentation de modules au format Markdown"],"de":["Benötigt Zugriff auf die README.md-Datei des Projekts","Begrenzt auf die Aktualisierung der Moduldokumentation im Markdown-Format"],"pt":["Requer acesso ao arquivo README.md do projeto","Limitado à atualização da documentação do módulo no formato Markdown"],"ru":["Требует доступа к файлу README.md проекта","Ограничен обновлением документации модуля в формате Markdown"],"ar":["يتطلب الوصول إلى ملف README.md للمشروع","محدود بالتحديث التوثيق لوحدة في تنسيق Markdown"]},"version":3},"qualityScore":55}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MykolaPinchuk/TML-bench/checkpoint', 'community', 'MykolaPinchuk', 'TML-bench', 'MykolaPinchuk/TML-bench', 'checkpoint', 0, 0, 0, '2026-02-18T01:08:43.448Z', '2026-02-18T06:31:19.159Z', NULL, '{"id":"MykolaPinchuk/TML-bench/checkpoint","name":"checkpoint","description":{"zh":"Checkpoint技术是一种用于优化Git工作流的方法，确保代码安全和高效。它通过执行一系列的检查和验证来确保代码的完整性","ja":"Checkpoint技術は、Gitワークフローを最適化するための方法です。コードの安全性と効率性を確保するために、一連のチェックと検証を実行します","ko":"체크포인트 기술은 Git 워크플ロー 최적화를 위한 방법으로, 코드의 안전성과 효율성을 보장하기 위해 일련의 체크와 검증을 수행합니다","es":"El punto de referencia de ML con Tabular es una herramienta para evaluar el rendimiento de los modelos de aprendizaje automático","fr":"La référence de ML avec Tabular est un outil pour évaluer les performances des modèles de machine learning","de":"Die ML-Referenz mit Tabular ist ein Werkzeug zur Bewertung der Leistung von Machine-Learning-Modellen","pt":"O Checkpoint é um benchmark de ML em tabela que executa verificações de pré-voo e guardrails de sanidade para garantir a integridade do código e a segurança dos dados","ru":"Checkpoint - табличный бенчмарк ML, который выполняет предварительные проверки и guardaills для обеспечения целостности кода и безопасности данных","ar":"نقطة التحقق هي معيار ملائم للتعلم الآلي في الجداول التي تقوم بتشغيل عمليات التحقق المسبقة ومراقبة الصحة لضمان سلامة الشفرة وأمان البيانات","en":"Tabular ML benchmark"},"seo":{"title":{"zh":"Checkpoint 技术：优化 Git 工作流","ja":"チェックポイント技術：Gitワークフローの最適化","ko":"체크포인트 기술: Git 워크플로 최적화","es":"Punto de referencia de ML con Tabular","fr":"Référence de ML avec Tabular","de":"ML-Referenz mit Tabular","pt":"Checkpoint: Benchmark de ML em Tabela","ru":"Checkpoint: табличный бенчмарк ML","ar":"نقطة التحقق: معيار ملائم للتعلم الآلي","en":"checkpoint"},"description":{"zh":"Checkpoint技术是一种用于优化Git工作流的方法，确保代码安全和高效。它通过执行一系列的检查和验证来确保代码的完整性","ja":"Checkpoint技術は、Gitワークフローを最適化するための方法です。コードの安全性と効率性を確保するために、一連のチェックと検証を実行します","ko":"체크포인트 기술은 Git 워크플ロー 최적화를 위한 방법으로, 코드의 안전성과 효율성을 보장하기 위해 일련의 체크와 검증을 수행합니다","es":"El punto de referencia de ML con Tabular es una herramienta para evaluar el rendimiento de los modelos de aprendizaje automático","fr":"La référence de ML avec Tabular est un outil pour évaluer les performances des modèles de machine learning","de":"Die ML-Referenz mit Tabular ist ein Werkzeug zur Bewertung der Leistung von Machine-Learning-Modellen","pt":"O Checkpoint é um benchmark de ML em tabela que executa verificações de pré-voo e guardrails de sanidade para garantir a integridade do código e a segurança ...","ru":"Checkpoint - табличный бенчмарк ML, который выполняет предварительные проверки и guardaills для обеспечения целостности кода и безопасности данных","ar":"نقطة التحقق هي معيار ملائم للتعلم الآلي في الجداول التي تقوم بتشغيل عمليات التحقق المسبقة ومراقبة الصحة لضمان سلامة الشفرة وأمان البيانات","en":"Tabular ML benchmark"},"definition":{"en":"Tabular ML benchmark"},"features":{"zh":["优化Git工作流","确保代码安全","提高代码效率","自动执行检查和验证","支持多种Git操作"],"ja":["Gitワークフローの最適化","コードの安全性の確保","コードの効率性の向上","自動でのチェックと検証","多種のGit操作のサポート"],"ko":["Git 워크플ロー 최적화","코드 보안성 보장","코드 효율성 향상","자동 체크 및 검증","다양한 Git 연산 지원"],"es":["Ejecuta comandos de git para verificar el estado del repositorio","Verifica la sincronización del archivo de registro","Evita la ejecución de comandos de git peligrosos","Protege los secretos y credenciales","Proporciona un resumen del estado del repositorio"],"fr":["Exécute des commandes git pour vérifier l''état du référentiel","Vérifie la synchronisation du fichier de journal","Évite l''exécution de commandes git dangereuses","Protège les secrets et les informations d''identification","Fournit un résumé de l''état du référentiel"],"de":["Führt Git-Befehle aus, um den Zustand des Repository zu überprüfen","Überprüft die Synchronisation der Log-Datei","Verhindert die Ausführung gefährlicher Git-Befehle","Schützt Geheimnisse und Anmeldeinformationen","Bietet eine Zusammenfassung des Repository-Zustands"],"pt":["Verificação de pré-voo com git status e git diff","Guardrails de sanidade para prevenir a perda de dados","Verificação de sincronização do id do agente","Prevenção de commit de segredos e credenciais","Proteção contra operações de git perigosas"],"ru":["Предварительная проверка с git status и git diff","Гардаилы для предотвращения потери данных","Проверка синхронизации идентификатора агента","Предотвращение коммита секретов и учетных данных","Защита от опасных операций git"],"ar":["عمليات التحقق المسبقة مع git status و git diff","مراقبة الصحة للوقاية من فقدان البيانات","التحقق من مزامنة معرف العميل","منع Commit للأسرار والأرصدة","حماية ضد عمليات git الخطرة"]},"keywords":{"zh":["Checkpoint技术","Git工作流优化","代码安全","代码效率","自动检查","Git操作"],"ja":["Checkpoint技術","Gitワークフローの最適化","コードの安全性","コードの効率性","自動でのチェック","Git操作"],"ko":["체크포인트 기술","Git 워크플ロー 최적화","코드 보안","코드 효율","자동 체크","Git 연산"],"es":["punto de referencia de ML","benchmark de aprendizaje automático","tabular ML","git","seguridad de datos","protección de secretos"],"fr":["référence de ML","benchmark de machine learning","tabular ML","git","sécurité des données","protection des secrets"],"de":["ML-Referenz","Benchmark für Machine Learning","Tabular ML","Git","Datensicherheit","Schutz von Geheimnissen"],"pt":["Checkpoint","benchmark de ML","tabular ML","git status","git diff","segurança de dados","integridade do código"],"ru":["Checkpoint","табличный бенчмарк ML","табличный ML","git status","git diff","безопасность данных","целостность кода"],"ar":["نقطة التحقق","معيار ملائم للتعلم الآلي","التعلم الآلي في الجداول","git status","git diff","أمان البيانات","سلامة الشفرة"]}},"owner":"MykolaPinchuk","repo":"TML-bench","repoPath":"MykolaPinchuk/TML-bench","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"checkpoint","description":"Create a safe checkpoint git commit on the current branch (avoid competition data, runs, artifacts, secrets).","bodyPreview":"When invoked (or when the user says `checkpoint`), do this in order.\n\n## 1) Preflight (must do; show output)\n- `git status`\n- `git diff --stat`\n- Verify `agent_logs/current.md` `id:` is synced to the kickoff `AgentNN` for this chat. If stale, fix `current.md` before commit.\n\n## 2) Sanity guardrails (must do)\n- Never run: `git push`, `git commit --amend`, `git rebase`, `git reset --hard`, `git clean -fdx`, or modify git remotes.\n- Never stage/commit secrets/credentials: `.env*`, `*.pem`, `*.key`,","body":"When invoked (or when the user says `checkpoint`), do this in order.\n\n## 1) Preflight (must do; show output)\n- `git status`\n- `git diff --stat`\n- Verify `agent_logs/current.md` `id:` is synced to the kickoff `AgentNN` for this chat. If stale, fix `current.md` before commit.\n\n## 2) Sanity guardrails (must do)\n- Never run: `git push`, `git commit --amend`, `git rebase`, `git reset --hard`, `git clean -fdx`, or modify git remotes.\n- Never stage/commit secrets/credentials: `.env*`, `*.pem`, `*.key`, `id_rsa*`, `id_ed25519*`, tokens.\n- Never stage/commit competition data or run artifacts:\n  - `competitions/**/{public,private,raw,downloads}/**`\n  - `runs/**`\n  - sqlite/db files\n\n## 3) Stage (default: include safe tracked files)\nStage only source/docs/config files and small markdown:\n- root `*.md`, `*.yml`\n- `docs/**`\n- `local_context_enrichments/**`\n- `.codex/**`\n\nIf anything looks suspicious (bulk files, data-like payloads), stop and report before staging.\n\nBefore committing, show:\n- `git diff --cached --stat`\n\n## 4) Commit (auto message)\n- Create a structured message that includes the agent id:\n  - `agentNN: checkpoint(<area>): <short summary>`\n  - Derive `agentNN` from kickoff-synced `agent_logs/current.md` (field `id:`). If missing/ambiguous, stop and ask the human.\n  - Choose `<area>` from: `workflow`, `docs`, `orchestrator`, `competitions`, `prompts`, `ci`, `misc`.\n- Run `git commit -m \"<message>\"`.\n\n## 5) Postflight (must do; show output)\n- `git status`\n- Report the commit hash.\n"},"lastSynced":"2026-02-18T06:31:19.159Z","agentAnalysis":{"suitability":{"en":"Ideal for Git-based AI Agents requiring version control and integrity checks, such as Cursor, Windsurf, or Claude Code.","zh":"适用于需要版本控制和完整性检查的基于Git的AI代理，例如Cursor、Windsurf或Claude Code。","ja":"GitベースのAIエージェントでバージョン管理と整合性チェックを必要とする場合に適しています。たとえば、Cursor、Windsurf、またはClaude Codeなどです。","ko":"버전 관리 및 무결성 확인이 필요한 Git 기반 AI 에이전트에 적합합니다. 예를 들어, Cursor, Windsurf 또는 Claude Code와 같은 에이전트입니다.","es":"Ideal para agentes de IA basados en Git que requieren control de versiones y verificaciones de integridad, como Cursor, Windsurf o Claude Code.","fr":"Idéal pour les agents d''IA basés sur Git nécessitant une gestion de version et des vérifications d''intégrité, tels que Cursor, Windsurf ou Claude Code.","de":"Ideal für Git-basierte KI-Agents, die Versionskontrolle und Integritätsprüfungen benötigen, wie z. B. Cursor, Windsurf oder Claude Code.","pt":"Ideal para Agentes de IA baseados em Git que exigem controle de versão e verificações de integridade, como Cursor, Windsurf ou Claude Code.","ru":"Идеально подходит для агентов ИИ на основе Git, требующих контроля версий и проверок целостности, таких как Cursor, Windsurf или Claude Code.","ar":"مثالية لعميل الذكاء الاصطناعي المستند إلى Git الذي يتطلب التحكم في الإصدار وفحوصات السلامة، مثل Cursor أو Windsurf أو Claude Code."},"recommendation":{"en":"Empowers agents to maintain repository integrity by running `git status` and `git diff --stat`, ensuring synced `agent_logs/current.md` files and preventing accidental pushes or commits of sensitive data like `.env*`, `*.pem`, or `*.key` files.","zh":"赋予代理维护仓库完整性能力，通过运行`git status`和`git diff --stat`，确保`agent_logs/current.md`文件同步，并防止意外推送或提交敏感数据，如`.env*`、`*.pem`或`*.key`文件。","ja":"`git status`と`git diff --stat`を実行することで、リポジトリの整合性を維持するエージェントの能力を付与します。また、`agent_logs/current.md`ファイルを同期し、`.env*`、`*.pem`、または`*.key`ファイルなどの機密データを意図せずにプッシュまたはコミットすることを防ぎます。","ko":"`git status`와 `git diff --stat`를 실행하여 리포지토리의 무결성을 유지할 수 있는 에이전트의 능력을 부여합니다. 또한 `agent_logs/current.md` 파일을 동기화하고 `.env*`, `*.pem` 또는 `*.key` 파일과 같은敏感 데이터를 의도하지 않게 푸시하거나 커밋하는 것을 방지합니다.","es":"Permite a los agentes mantener la integridad del repositorio mediante la ejecución de `git status` y `git diff --stat`, asegurando la sincronización de los archivos `agent_logs/current.md` y evitando pushes o commits accidentales de datos sensibles como archivos `.env*`, `*.pem` o `*.key`.","fr":"Permet aux agents de maintenir l''intégrité du référentiel en exécutant `git status` et `git diff --stat`, en garantissant la synchronisation des fichiers `agent_logs/current.md` et en empêchant les pushes ou les commits accidentels de données sensibles comme les fichiers `.env*`, `*.pem` ou `*.key`.","de":"Ermöglicht es den Agents, die Integrität des Repositorys durch Ausführen von `git status` und `git diff --stat` aufrechtzuerhalten, die synchronisierten Dateien `agent_logs/current.md` sicherzustellen und versehentliche Pushes oder Commits von sensitiven Daten wie Dateien `.env*`, `*.pem` oder `*.key` zu verhindern.","pt":"Habilita os agentes a manter a integridade do repositório executando `git status` e `git diff --stat`, garantindo arquivos `agent_logs/current.md` sincronizados e impedindo pushes ou commits acidentais de dados sensíveis como arquivos `.env*`, `*.pem` ou `*.key`.","ru":"Позволяет агентам поддерживать целостность репозитория, выполняя `git status` и `git diff --stat`, обеспечивая синхронизированные файлы `agent_logs/current.md` и предотвращая случайные пуши или коммиты конфиденциальных данных, таких как файлы `.env*`, `*.pem` или `*.key`.","ar":"تمكّن الوكيل من الحفاظ على سلامة المستودع من خلال تشغيل `git status` و `git diff --stat`، مما يضمن تنسق ملفات `agent_logs/current.md` ومنع الضغط أو الالتزام العرضي للبيانات الحساسة مثل الملفات `.env*` أو `*.pem` أو `*.key`."},"useCases":{"en":["Verifying repository status before committing changes","Syncing agent logs with kickoff AgentNN for consistency","Preventing accidental exposure of secrets or credentials"],"zh":["提交更改前验证仓库状态","将代理日志与kickoff AgentNN同步以保持一致性","防止意外暴露机密或凭据"],"ja":["変更をコミットする前にリポジトリの状態を検証する","エージェントログをkickoff AgentNNと同期して一貫性を維持する","機密情報や資格情報の意図しない公開を防ぐ"],"ko":["변경 사항을 커밋하기 전에 리포지토리의 상태를 검증합니다.","에이전트 로그를 kickoff AgentNN와 동기화하여 일관성을 유지합니다.","비밀번호 또는 자격 증명의 의도하지 않은 노출을 방지합니다."],"es":["Verificar el estado del repositorio antes de realizar cambios","Sincronizar los registros del agente con kickoff AgentNN para garantizar la coherencia","Prevenir la exposición accidental de secretos o credenciales"],"fr":["Vérifier l''état du référentiel avant d''apporter des modifications","Synchroniser les journaux de l''agent avec kickoff AgentNN pour assurer la cohérence","Empêcher l''exposition accidentelle de secrets ou d''informations d''identification"],"de":["Überprüfen des Repository-Zustands vor der Durchführung von Änderungen","Synchronisieren der Agent-Protokolle mit kickoff AgentNN für Konsistenz","Verhindern der versehentlichen Offenlegung von Geheimnissen oder Anmeldeinformationen"],"pt":["Verificar o status do repositório antes de realizar alterações","Sincronizar logs do agente com kickoff AgentNN para consistência","Prevenir exposição acidental de segredos ou credenciais"],"ru":["Проверять статус репозитория перед внесением изменений","Синхронизировать журналы агента с kickoff AgentNN для согласованности","Предотвращать случайную утечку секретов или учетных данных"],"ar":["التحقق من حالة المستودع قبل إجراء التغييرات","تنسيق سجلات الوكيل مع kickoff AgentNN للاتساق","منع الكشف العرضي عن الأسرار أو بيانات الاعتماد"]},"limitations":{"en":["Requires Git installation and configuration","Must have write access to `agent_logs/current.md`","Restricts certain Git commands like `git push`, `git commit --amend`, or `git rebase` for safety"],"zh":["需要Git安装和配置","必须具有`agent_logs/current.md`的写入访问权限","出于安全考虑，限制某些Git命令，如`git push`、`git commit --amend`或`git rebase`"],"ja":["Gitのインストールと設定が必要","`agent_logs/current.md`への書き込みアクセス権が必要","安全上の理由で、`git push`、`git commit --amend`、または`git rebase`などの特定のGitコマンドが制限される"],"ko":["Git 설치 및 구성이 필요합니다.","`agent_logs/current.md`에 대한 쓰기 액세스 권한이 필요합니다.","안전을 위해 `git push`, `git commit --amend` 또는 `git rebase`와 같은 특정 Git 명령이 제한됩니다."],"es":["Requiere la instalación y configuración de Git","Debe tener acceso de escritura a `agent_logs/current.md`","Restringe ciertos comandos de Git como `git push`, `git commit --amend` o `git rebase` por motivos de seguridad"],"fr":["Nécessite l''installation et la configuration de Git","Doit avoir un accès en écriture à `agent_logs/current.md`","Restreint certaines commandes Git comme `git push`, `git commit --amend` ou `git rebase` pour des raisons de sécurité"],"de":["Benötigt die Installation und Konfiguration von Git","Muss Schreibzugriff auf `agent_logs/current.md` haben","Einschränkung bestimmter Git-Befehle wie `git push`, `git commit --amend` oder `git rebase` aus Sicherheitsgründen"],"pt":["Exige instalação e configuração do Git","Deve ter acesso de gravação para `agent_logs/current.md`","Restringe certos comandos Git, como `git push`, `git commit --amend` ou `git rebase`, por motivos de segurança"],"ru":["Требует установки и настройки Git","Должен иметь доступ на запись к `agent_logs/current.md`","Ограничивает определенные команды Git, такие как `git push`, `git commit --amend` или `git rebase`, по соображениям безопасности"],"ar":["يتطلب تثبيت وتفاصيل Git","يجب أن يكون لديه حق الوصول إلى كتابة `agent_logs/current.md`","يقيد بعض أوامر Git، مثل `git push` أو `git commit --amend` أو `git rebase`، لأسباب أمنية"]},"version":3},"qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('semanticdreams/space/git-commit', 'community', 'semanticdreams', 'space', 'semanticdreams/space', 'git-commit', 0, 0, 35, '2026-02-18T01:08:43.448Z', '2026-02-18T06:31:13.688Z', NULL, '{"id":"semanticdreams/space/git-commit","name":"git-commit","description":{"zh":"Git Commit 消息是代码变更的重要记录，需要清晰、简洁地描述变更内容","ja":"Git Commit メッセージはコードの変更を記録するための重要な手段です","ko":"Git Commit 메시지는 코드의 변경을 기록하는 중요한 수단입니다","es":"Git Commit es una interfaz de computación novel que ayuda a los desarrolladores a escribir mensajes de commit efectivos. Mejora tu flujo de trabajo y seguridad.","fr":"Git Commit est une interface de calcul novel qui aide les développeurs à écrire des messages de commit efficaces. Améliorez votre flux de travail et votre sécurité.","de":"Git Commit ist eine novel Computer-Schnittstelle, die Entwicklern hilft, effektive Commit-Nachrichten zu schreiben. Verbessern Sie Ihren Arbeitsfluss und Ihre Sicherheit.","pt":"O skill git-commit ajuda a criar mensagens de commit claras e concisas. Verifique o conjunto de alterações e evite committar segredos ou credenciais","ru":"Навык git-commit помогает создавать ясные и краткие сообщения о фиксации. Проверьте набор изменений и избегайте фиксации секретов или учетных данных","ar":"مهارة git-commit تساعد على إنشاء رسائل إلتزام واضحة وموجزة. تحقق من مجموعة التغييرات وتجنب الإلتزام الأسرار أو بيانات الاعتماد","en":"Novel computing interface"},"seo":{"title":{"zh":"Git Commit 消息技巧","ja":"Git Commit メッセージの書き方","ko":"Git Commit 메시지 작성 방법","es":"Git Commit: Mejora tus mensajes de commit","fr":"Git Commit: Améliorez vos messages de commit","de":"Git Commit: Verbessern Sie Ihre Commit-Nachrichten","pt":"Git Commit: Melhore suas mensagens de commit","ru":"Git Commit: Улучшите свои сообщения о фиксации","ar":"Git Commit: تحسين رسائل الإلتزام","en":"git-commit"},"description":{"zh":"Git Commit 消息是代码变更的重要记录，需要清晰、简洁地描述变更内容","ja":"Git Commit メッセージはコードの変更を記録するための重要な手段です","ko":"Git Commit 메시지는 코드의 변경을 기록하는 중요한 수단입니다","es":"Git Commit es una interfaz de computación novel que ayuda a los desarrolladores a escribir mensajes de commit efectivos. Mejora tu flujo de trabajo y seguridad.","fr":"Git Commit est une interface de calcul novel qui aide les développeurs à écrire des messages de commit efficaces. Améliorez votre flux de travail et votre sé...","de":"Git Commit ist eine novel Computer-Schnittstelle, die Entwicklern hilft, effektive Commit-Nachrichten zu schreiben. Verbessern Sie Ihren Arbeitsfluss und Ihr...","pt":"O skill git-commit ajuda a criar mensagens de commit claras e concisas. Verifique o conjunto de alterações e evite committar segredos ou credenciais","ru":"Навык git-commit помогает создавать ясные и краткие сообщения о фиксации. Проверьте набор изменений и избегайте фиксации секретов или учетных данных","ar":"مهارة git-commit تساعد على إنشاء رسائل إلتزام واضحة وموجزة. تحقق من مجموعة التغييرات وتجنب الإلتزام الأسرار أو بيانات الاعتماد","en":"Novel computing interface"},"definition":{"en":"Novel computing interface"},"features":{"zh":["验证变更集","分阶段提交","避免提交敏感信息","使用 git status 和 git diff","优化提交消息"],"ja":["変更セットの検証","ステージされた変更のコミット","機密情報のコミットを避ける","git status と git diff の使用","コミットメッセージの最適化"],"ko":["변경 집합의 검증","스테이지된 변경의 커밋","기밀 정보의 커밋을 피함","git status 및 git diff 사용","커밋 메시지 최적화"],"es":["Verificación del conjunto de cambios","Etapa solo lo que se va a enviar","Evitar la commisión de secretos y credenciales","Uso de git add -p para diferencias mixtas","Verificación de la seguridad con git diff"],"fr":["Vérification de l''ensemble de modifications","Étape uniquement ce qui va être envoyé","Éviter la commisión de secrets et d''informations d''identification","Utilisation de git add -p pour les différences mixtes","Vérification de la sécurité avec git diff"],"de":["Überprüfung des Änderungssatzes","Stufen Sie nur das ein, was Sie senden möchten","Vermeiden Sie die Committierung von Geheimnissen und Anmeldeinformationen","Verwenden Sie git add -p für gemischte Diffs","Sicherheitsüberprüfung mit git diff"],"pt":["Verificação do conjunto de alterações","Evitar committar segredos ou credenciais","Criação de mensagens de commit claras e concisas","Uso de comandos Git como git status e git diff","Integração com o fluxo de trabalho Git"],"ru":["Проверка набора изменений","Избегание фиксации секретов или учетных данных","Создание ясных и кратких сообщений о фиксации","Использование команд Git, таких как git status и git diff","Интеграция с рабочим процессом Git"],"ar":["تحقق من مجموعة التغييرات","تجنب الإلتزام الأسرار أو بيانات الاعتماد","إنشاء رسائل إلتزام واضحة وموجزة","استخدام أوامر Git مثل git status و git diff","التكامل مع تدفق العمل Git"]},"keywords":{"zh":["Git Commit","代码变更","提交消息","代码审查","Git 工作流","版本控制"],"ja":["Git Commit","コード変更","コミットメッセージ","コードレビュー","Git ワークフロー","バージョン管理"],"ko":["Git Commit","코드 변경","커밋 메시지","코드 리뷰","Git 워크플로우","버전 관리"],"es":["git commit","mensajes de commit","flujo de trabajo","seguridad","desarrollo de software","git add","git diff","git status"],"fr":["git commit","messages de commit","flux de travail","sécurité","développement de logiciels","git add","git diff","git status"],"de":["git commit","Commit-Nachrichten","Arbeitsfluss","Sicherheit","Software-Entwicklung","git add","git diff","git status"],"pt":["git commit","mensagens de commit","fluxo de trabalho git","verificação de alterações","segredos e credenciais","comandos git","produtividade no git","organização no git"],"ru":["git commit","сообщения о фиксации","рабочий процесс git","проверка изменений","секреты и учетные данные","команды git","производительность в git","организация в git"],"ar":["git commit","رسائل إلتزام","تدفق العمل git","تحقق من التغييرات","أسرار وبيانات الاعتماد","أوامر Git","إنتاجية في Git","تنظيم في Git"]}},"owner":"semanticdreams","repo":"space","repoPath":"semanticdreams/space","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"git-commit","description":"Commit changes (git commit) for this repo and write consistent commit messages (type(scope) prefix, impact/risk, what/why/how, testing summary, follow-ups, references).","bodyPreview":"# Git Commit Messages (space)\n\nUse this skill whenever you''re about to create a commit (or when asked to \"commit\", \"write a commit message\", \"draft a commit\", etc.).\n\n## Workflow and safety\n\n- Verify the change set:\n  - `git status`\n  - `git diff`\n  - `git diff --staged`\n- Stage only what you intend to ship; prefer `git add -p` for mixed diffs.\n- Never commit secrets/credentials. When in doubt:\n  - `git diff --staged | rg -n -i \"api[_-]?key|secret|token|password|-----begin|private key\"`\n- Avoid","body":"# Git Commit Messages (space)\n\nUse this skill whenever you''re about to create a commit (or when asked to \"commit\", \"write a commit message\", \"draft a commit\", etc.).\n\n## Workflow and safety\n\n- Verify the change set:\n  - `git status`\n  - `git diff`\n  - `git diff --staged`\n- Stage only what you intend to ship; prefer `git add -p` for mixed diffs.\n- Never commit secrets/credentials. When in doubt:\n  - `git diff --staged | rg -n -i \"api[_-]?key|secret|token|password|-----begin|private key\"`\n- Avoid destructive history ops unless explicitly asked (`reset --hard`, `clean -fdx`, `rebase`, `--amend`, force-push).\n\n## Commit subject line\n\n- Format: `type(scope): <imperative subject>` (scope optional).\n- Keep it <= 72 chars and in imperative mood (\"Add\", \"Fix\", \"Refactor\").\n- Types: `feat`, `fix`, `docs`, `style`, `refactor`, `perf`, `test`, `build`, `ci`, `chore`, `revert`.\n- Scopes (when useful): `engine`, `render`, `physics`, `audio`, `lua`, `ui`, `assets`, `scripts`.\n- Breaking changes: append an exclamation mark after type/scope (e.g. feat!:) and call it out in Impact + Risk.\n\n## Body (required for non-trivial changes)\n\nBe explicit about **impact** (user-visible) vs **what** changed (code/data). Include **risk** when plausible.\n\nTemplate:\n\n```\ntype(scope): Short imperative subject (<= 72 chars)\n\nImpact:\n- <user-visible result / behavior change; include repro if useful>\n\nWhat:\n- <key code/data changes>\n\nWhy:\n- <motivation / constraints>\n\nHow:\n- <implementation approach, key files/systems>\n\nRisk:\n- <what could go wrong + mitigations/rollback>\n\nTesting:\n- <commands run + brief summary; DO NOT paste full logs>\n\nFollow-ups:\n- <next steps / cleanup / tech debt>\n\nReferences:\n- Refs: #123\n```\n\n## Testing section expectations\n\n- Prefer running the full suite before committing:\n  - `SKIP_KEYRING_TESTS=1 XDG_DATA_HOME=/tmp/space/tests/xdg-data SPACE_DISABLE_AUDIO=1 SPACE_ASSETS_PATH=$(pwd)/assets make test`\n- For targeted runs, include the command and a short result summary (e.g., “passed” / “failed: <test name>”).\n- Do not paste full test output into the commit message; keep it to a couple lines.\n\n## Practical: avoid shell-quoting footguns\n\n- Prefer writing the message to a file and committing with `-F`, especially if the body contains backticks:\n  - `cat > /tmp/commitmsg.txt <<''EOF'' ... EOF`\n  - `git commit -F /tmp/commitmsg.txt`\n"},"lastSynced":"2026-02-18T06:31:13.688Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing precise Git commit message management and verification.","zh":"非常适合需要精确 Git 提交消息管理和验证的开发代理。","ja":"開発エージェントが Git コミット メッセージの管理と検証を正確に必要とする場合に最適です。","ko":"정확한 Git 커밋 메시지 관리 및 확인이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión y verificación precisas de los mensajes de commit de Git.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion et d''une vérification précises des messages de commit Git.","de":"Perfekt für Entwicklungssagenten, die eine präzise Git-Commit-Mitteilungsverwaltung und -verifizierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento e verificação preciso de mensagens de commit do Git.","ru":"Идеально для агентов разработки, которым требуется точное управление и проверка сообщений о фиксации Git.","ar":"مثالي للوكلاء النمطية الذين يحتاجون إلى إدارة دقيقة وتأكيد رسائل الالتزام في جيت"},"recommendation":{"en":"Empowers agents to verify change sets using `git status` and `git diff`, stage intentional changes with `git add -p`, and avoid committing secrets by scanning with `rg` for keywords like ''api_key'' or ''secret''.","zh":"赋予代理人使用 `git status` 和 `git diff` 验证更改集、使用 `git add -p` 分阶段确认更改以及通过使用 `rg` 扫描关键字（如 ''api_key'' 或 ''secret''）以避免提交机密信息的能力。","ja":"エージェントが `git status` と `git diff` を使用して変更セットを検証し、`git add -p` を使用して意図的な変更をステージし、`rg` を使用して ''api_key'' または ''secret'' などのキーワードをスキャンして機密情報をコミットしないようにする機能を提供します。","ko":"에이전트가 `git status`와 `git diff`를 사용하여 변경 세트를 확인하고, `git add -p`를 사용하여 의도적인 변경을 스테이징하며, `rg`를 사용하여 ''api_key'' 또는 ''secret''와 같은 키워드를 스캔하여 기밀 정보를 커밋하지 않도록 하는 기능을 제공합니다.","es":"Habilita a los agentes a verificar conjuntos de cambios con `git status` y `git diff`, a preparar cambios intencionados con `git add -p` y a evitar la confirmación de secretos mediante el análisis con `rg` para palabras clave como ''api_key'' o ''secret''.","fr":"Permet aux agents de vérifier les ensembles de modifications avec `git status` et `git diff`, de préparer des modifications intentionnelles avec `git add -p` et d''éviter de confirmer des secrets en analysant avec `rg` pour des mots clés comme ''api_key'' ou ''secret''.","de":"Ermächtigt Agenten, Änderungssätze mit `git status` und `git diff` zu überprüfen, beabsichtigte Änderungen mit `git add -p` zu staging und das Kommittieren von Geheimnissen durch Scannen mit `rg` für Schlüsselwörter wie ''api_key'' oder ''secret'' zu vermeiden.","pt":"Habilita os agentes a verificar conjuntos de alterações usando `git status` e `git diff`, a preparar alterações intencionais com `git add -p` e a evitar a commitear segredos ao digitalizar com `rg` para palavras-chave como ''api_key'' ou ''secret''.","ru":"Наделяет агентов возможностью проверять наборы изменений с помощью `git status` и `git diff`, подготовки намеренных изменений с помощью `git add -p` и избегает фиксации секретов, сканируя с помощью `rg` ключевые слова, такие как ''api_key'' или ''secret''.","ar":"يمنح الوكلاء القدرة على التحقق من مجموعات التغييرات باستخدام `git status` و `git diff` ، ومرحلة التغييرات المتعمدة باستخدام `git add -p` ، وتجنب الالتزام بالاسرار من خلال مسحها باستخدام `rg` للكلمات الرئيسية مثل ''api_key'' أو ''secret''"},"useCases":{"en":["Verifying change sets before commit","Staging selective changes with `git add -p`","Scanning staged changes for sensitive information"],"zh":["在提交之前验证更改集","使用 `git add -p` 分阶段选择性变化","扫描已分阶段的变化以查找敏感信息"],"ja":["コミット前の変更セットの検証","`git add -p` を使用した選択的な変更のステージング","ステージングされた変更のスキャニングによる機密情報の検出"],"ko":["커밋 전 변경 세트 확인","`git add -p`를 사용한 선택적 변경 스테이징","스테이징된 변경에 대한 스캔을 통한 민감한 정보 검색"],"es":["Verificar conjuntos de cambios antes de confirmar","Preparar cambios selectivos con `git add -p`","Analizar cambios preparados para información sensible"],"fr":["Vérifier les ensembles de modifications avant de confirmer","Préparer des modifications sélectives avec `git add -p`","Analyser les modifications préparées pour des informations sensibles"],"de":["Änderungssätze vor dem Commit überprüfen","Selektive Änderungen mit `git add -p` staging","Gestagte Änderungen auf sensible Informationen scannen"],"pt":["Verificar conjuntos de alterações antes do commit","Preparar alterações seletivas com `git add -p`","Digitalizar alterações preparadas para informações sensíveis"],"ru":["Проверка наборов изменений перед фиксацией","Подготовка выбранных изменений с помощью `git add -p`","Сканирование подготовленных изменений для конфиденциальной информации"],"ar":["التحقق من مجموعات التغييرات قبل الالتزام","مرحلة التغييرات الانتقائية مع `git add -p`","فحص التغييرات المُرحلة للمعلومات الحساسة"]},"limitations":{"en":["Requires Git installation and configuration","Needs access to the terminal or command line for execution"],"zh":["需要 Git 安装和配置","需要终端或命令行访问以执行"],"ja":["Git のインストールと設定が必要","実行するにはターミナルまたはコマンドラインへのアクセスが必要"],"ko":["Git 설치 및 구성이 필요","실행하기 위해 터미널 또는 명령줄에 대한 액세스가 필요"],"es":["Requiere instalación y configuración de Git","Necesita acceso a la terminal o línea de comandos para la ejecución"],"fr":["Nécessite l''installation et la configuration de Git","A besoin d''un accès au terminal ou à la ligne de commande pour l''exécution"],"de":["Benötigt Git-Installation und -Konfiguration","Benötigt Zugriff auf die Terminal- oder Kommandozeile für die Ausführung"],"pt":["Exige instalação e configuração do Git","Necessita acesso ao terminal ou linha de comando para execução"],"ru":["Требует установки и конфигурации Git","Требует доступа к терминалу или командной строке для выполнения"],"ar":["يتطلب تثبيت وتكوين جيت","يحتاج إلى الوصول إلى المحطة أو سطر الأوامر للتنفيذ"]},"version":3},"qualityScore":35}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ANcpLua/qyl/feature-dev', 'community', 'ANcpLua', 'qyl', 'ANcpLua/qyl', 'feature-dev', 0, 0, 0, '2026-02-18T01:08:43.448Z', '2026-02-18T06:31:13.121Z', NULL, '{"id":"ANcpLua/qyl/feature-dev","name":"feature-dev","description":{"zh":"AI AI OTLP DuckDB","ja":"AI AI OTLP DuckDB","ko":"AI AI OTLP DuckDB","es":"Feature-dev es una plataforma de observabilidad de IA que ayuda a los desarrolladores a implementar nuevas características de manera sistemática","fr":"Feature-dev est une plateforme d''observabilité de l''IA qui aide les développeurs à mettre en œuvre de nouvelles fonctionnalités de manière systématique","de":"Feature-dev ist eine AI-Observability-Plattform, die Entwicklern hilft, neue Funktionen systematisch umzusetzen","pt":"O feature-dev é uma plataforma de observabilidade de IA que ajuda os desenvolvedores a entender e melhorar suas cargas de trabalho de GenAI/LLM","ru":"Feature-dev - это платформа для наблюдения за ИИ, которая помогает разработчикам понимать и улучшать свои рабочие нагрузки GenAI/LLM","ar":"feature-dev هي منصة مراقبة الذكاء الاصطناعي التي تساعد المطورين على فهم وتحسين أعباء العمل GenAI/LLM","en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"seo":{"title":{"zh":"AI","ja":"AI","ko":"AI ","es":"Desarrollo de características con feature-dev","fr":"Développement de fonctionnalités avec feature-dev","de":"Feature-Entwicklung mit feature-dev","pt":"Desenvolvimento de Recursos com feature-dev","ru":"Разработка функций с feature-dev","ar":"تطوير الميزات مع feature-dev","en":"feature-dev"},"description":{"zh":"AI AI OTLP DuckDB","ja":"AI AI OTLP DuckDB","ko":"AI AI OTLP DuckDB","es":"Feature-dev es una plataforma de observabilidad de IA que ayuda a los desarrolladores a implementar nuevas características de manera sistemática","fr":"Feature-dev est une plateforme d''observabilité de l''IA qui aide les développeurs à mettre en œuvre de nouvelles fonctionnalités de manière systématique","de":"Feature-dev ist eine AI-Observability-Plattform, die Entwicklern hilft, neue Funktionen systematisch umzusetzen","pt":"O feature-dev é uma plataforma de observabilidade de IA que ajuda os desenvolvedores a entender e melhorar suas cargas de trabalho de GenAI/LLM","ru":"Feature-dev - это платформа для наблюдения за ИИ, которая помогает разработчикам понимать и улучшать свои рабочие нагрузки GenAI/LLM","ar":"feature-dev هي منصة مراقبة الذكاء الاصطناعي التي تساعد المطورين على فهم وتحسين أعباء العمل GenAI/LLM","en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"definition":{"en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"features":{"zh":["AI OTLP","DuckDB","AI","AI","AI"],"ja":["AI OTLP","DuckDB","AI","AI","AI"],"ko":["AI OTLP","DuckDB","AI","AI","AI"],"es":["Ingestión de OTLP","Almacenamiento en DuckDB","Convenciones semánticas para telemetría de IA","Exploración del código","Diseño de arquitectura","Revisión de calidad"],"fr":["Ingestion OTLP","Stockage DuckDB","Conventions sémantiques pour la télémétrie de l''IA","Exploration du code","Conception d''architecture","Révision de qualité"],"de":["OTLP-Ingestion","DuckDB-Speicher","Semantische Konventionen für AI-Telemetrie","Code-Exploration","Architektur-Design","Qualitätsprüfung"],"pt":["Ingestão de OTLP","Armazenamento de DuckDB","Convenções semânticas para telemetria de IA","Fluxo de trabalho de desenvolvimento de recursos abrangente","Agentes especializados para exploração de código","Revisão de qualidade de arquitetura"],"ru":["Ввод данных OTLP","Хранение DuckDB","Семантические конвенции для телеметрии ИИ","Комплексный рабочий процесс разработки функций","Специализированные агенты для изучения кода","Проверка качества архитектуры"],"ar":["استيعاب OTLP","تخزين DuckDB","اتفاقيات دلالية لتحليلات الذكاء الاصطناعي","تدفق عمل شامل لتطوير الميزات","وكلاء متخصصون لاستكشاف الكود","مراجعة جودة الهندسة المعمارية"]},"keywords":{"zh":["AI","OTLP","DuckDB","AI","AI","AI"],"ja":["AI","OTLP","DuckDB","AI","AI","AI"],"ko":["AI","OTLP","DuckDB","AI","AI","AI"],"es":["desarrollo de características","observabilidad de IA","GenAI","LLM","OTLP","DuckDB","telemetría de IA"],"fr":["développement de fonctionnalités","observabilité de l''IA","GenAI","LLM","OTLP","DuckDB","télémétrie de l''IA"],"de":["Feature-Entwicklung","AI-Observability","GenAI","LLM","OTLP","DuckDB","AI-Telemetrie"],"pt":["desenvolvimento de recursos","feature-dev","GenAI","LLM","observabilidade de IA","OTLP","DuckDB","telemetria de IA"],"ru":["разработка функций","feature-dev","GenAI","LLM","наблюдение за ИИ","OTLP","DuckDB","телеметрия ИИ"],"ar":["تطوير الميزات","feature-dev","GenAI","LLM","مراقبة الذكاء الاصطناعي","OTLP","DuckDB","تحليلات الذكاء الاصطناعي"]}},"owner":"ANcpLua","repo":"qyl","repoPath":"ANcpLua/qyl","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"feature-dev","description":"|","bodyPreview":"## Source Metadata\n\n```yaml\nfrontmatter:\n  argument-hint: Optional feature description\nplugin:\n  name: \"feature-dev\"\n  version: \"1.0.0\"\n  description: \"Comprehensive feature development workflow with specialized agents for codebase exploration, architecture design, and quality review\"\n  author:\n    name: \"Sid Bidasaria\"\n    email: \"sbidasaria@anthropic.com\"\n```\n\n\n# Feature Development\n\nYou are helping a developer implement a new feature. Follow a systematic approach: understand the codebase deep","body":"## Source Metadata\n\n```yaml\nfrontmatter:\n  argument-hint: Optional feature description\nplugin:\n  name: \"feature-dev\"\n  version: \"1.0.0\"\n  description: \"Comprehensive feature development workflow with specialized agents for codebase exploration, architecture design, and quality review\"\n  author:\n    name: \"Sid Bidasaria\"\n    email: \"sbidasaria@anthropic.com\"\n```\n\n\n# Feature Development\n\nYou are helping a developer implement a new feature. Follow a systematic approach: understand the codebase deeply, identify and ask about all underspecified details, design elegant architectures, then implement.\n\n## Core Principles\n\n- **Ask clarifying questions**: Identify all ambiguities, edge cases, and underspecified behaviors. Ask specific, concrete questions rather than making assumptions. Wait for user answers before proceeding with implementation. Ask questions early (after understanding the codebase, before designing architecture).\n- **Understand before acting**: Read and comprehend existing code patterns first\n- **Read files identified by agents**: When launching agents, ask them to return lists of the most important files to read. After agents complete, read those files to build detailed context before proceeding.\n- **Simple and elegant**: Prioritize readable, maintainable, architecturally sound code\n- **Use TodoWrite**: Track all progress throughout\n\n---\n\n## Phase 1: Discovery\n\n**Goal**: Understand what needs to be built\n\nInitial request: $ARGUMENTS\n\n**Actions**:\n1. Create todo list with all phases\n2. If feature unclear, ask user for:\n   - What problem are they solving?\n   - What should the feature do?\n   - Any constraints or requirements?\n3. Summarize understanding and confirm with user\n\n---\n\n## Phase 2: Codebase Exploration\n\n**Goal**: Understand relevant existing code and patterns at both high and low levels\n\n**Actions**:\n1. Launch 2-3 code-explorer agents in parallel. Each agent should:\n   - Trace through the code comprehensively and focus on getting a comprehensive understanding of abstractions, architecture and flow of control\n   - Target a different aspect of the codebase (eg. similar features, high level understanding, architectural understanding, user experience, etc)\n   - Include a list of 5-10 key files to read\n\n   **Example agent prompts**:\n   - \"Find features similar to [feature] and trace through their implementation comprehensively\"\n   - \"Map the architecture and abstractions for [feature area], tracing through the code comprehensively\"\n   - \"Analyze the current implementation of [existing feature/area], tracing through the code comprehensively\"\n   - \"Identify UI patterns, testing approaches, or extension points relevant to [feature]\"\n\n2. Once the agents return, please read all files identified by agents to build deep understanding\n3. Present comprehensive summary of findings and patterns discovered\n\n---\n\n## Phase 3: Clarifying Questions\n\n**Goal**: Fill in gaps and resolve all ambiguities before designing\n\n**CRITICAL**: This is one of the most important phases. DO NOT SKIP.\n\n**Actions**:\n1. Review the codebase findings and original feature request\n2. Identify underspecified aspects: edge cases, error handling, integration points, scope boundaries, design preferences, backward compatibility, performance needs\n3. **Present all questions to the user in a clear, organized list**\n4. **Wait for answers before proceeding to architecture design**\n\nIf the user says \"whatever you think is best\", provide your recommendation and get explicit confirmation.\n\n---\n\n## Phase 4: Architecture Design\n\n**Goal**: Design a clean, maintainable architecture\n\n**Actions**:\n1. Launch code-architect agent with focus on: clean architecture (maintainability, elegant abstractions, proper separation of concerns, extensibility)\n2. Design for long-term maintainability - no shortcuts, no minimal patches, no quick fixes\n3. Present the architecture design to user with implementation details\n4. Proceed with the clean architecture approach (no alternative approaches - always choose quality)\n\n---\n\n## Phase 5: Implementation\n\n**Goal**: Build the feature\n\n**DO NOT START WITHOUT USER APPROVAL**\n\n**Actions**:\n1. Wait for explicit user approval\n2. Read all relevant files identified in previous phases\n3. Implement following chosen architecture\n4. Follow codebase conventions strictly\n5. Write clean, well-documented code\n6. Update todos as you progress\n\n---\n\n## Phase 6: Quality Review\n\n**Goal**: Ensure code is simple, DRY, elegant, easy to read, and functionally correct\n\n**Actions**:\n1. Launch 3 code-reviewer agents in parallel with different focuses: simplicity/DRY/elegance, bugs/functional correctness, project conventions/abstractions\n2. Consolidate findings and identify highest severity issues that you recommend fixing\n3. **Present findings to user and ask what they want to do** (fix now, fix later, or proceed as-is)\n4. Address issues based on user decision\n\n---\n\n## Phase 7: Summary\n\n**Goal**: Document what was accomplished\n\n**Actions**:\n1. Mark all todos complete\n2. Summarize:\n   - What was built\n   - Key decisions made\n   - Files modified\n   - Suggested next steps\n\n---\n"},"lastSynced":"2026-02-18T06:31:13.121Z","agentAnalysis":{"suitability":{"en":"Perfect for GenAI/LLM Agents needing comprehensive feature development workflows with OTLP ingestion and DuckDB storage","zh":"非常适合需要全面特性开发工作流的 GenAI/LLM 代理，具有 OTLP 吸收和 DuckDB 存储","ja":"GenAI/LLM エージェントに最適で、OTLP 組み込みと DuckDB ストレージを備えた包括的な機能開発ワークフローを必要とする","ko":"GenAI/LLM 에이전트에 적합하며, OTLP 수신 및 DuckDB 저장소가 있는 포괄적인 기능 개발 워크플로가 필요한 경우","es":"Perfecto para agentes de GenAI/LLM que necesitan flujos de trabajo de desarrollo de características integrales con ingesta de OTLP y almacenamiento de DuckDB","fr":"Parfait pour les agents GenAI/LLM qui ont besoin de flux de travail de développement de fonctionnalités complets avec ingestion OTLP et stockage DuckDB","de":"Perfekt für GenAI/LLM-Agents, die umfassende Funktionsentwicklungs-Workflows mit OTLP-Einbindung und DuckDB-Speicherung benötigen","pt":"Perfeito para Agentes GenAI/LLM que precisam de fluxos de trabalho de desenvolvimento de recursos abrangentes com ingestão OTLP e armazenamento DuckDB","ru":"Идеально подходит для агентов GenAI/LLM, требующих комплексных рабочих процессов разработки функций с ингестией OTLP и хранилищем DuckDB","ar":"مثالي للوكلاء GenAI/LLM الذين يحتاجون إلى سير عمل شاملة لتنمية الميزات مع استهلاك OTLP وتخزين DuckDB"},"recommendation":{"en":"Empowers agents to implement new features with a systematic approach, utilizing semantic conventions for AI telemetry and specialized agents for codebase exploration, architecture design, and quality review, all while leveraging OTLP and DuckDB for efficient data management","zh":"赋予代理以系统的方法实现新功能，利用语义约定进行 AI 遥测，使用专用代理进行代码库探索、架构设计和质量审查，同时利用 OTLP 和 DuckDB 进行高效的数据管理","ja":"エージェントに新しい機能を体系的に実装できるようサポートし、AI 遠隔測定のためのセマンティック規約を利用し、コードベースの探索、設計、品質レビューのための専用エージェントを使用し、OTLP と DuckDB を使用した効率的なデータ管理を可能にします","ko":"에이전트가 체계적인 접근 방식을 사용하여 새로운 기능을 구현할 수 있도록 합니다. AI 원격 측정을 위한 의미 규약을 사용하고 코드베이스 탐색, 아키텍처 디자인 및 품질 검토를 위한 전문 에이전트를 사용하며, OTLP 및 DuckDB를 사용하여 효율적인 데이터 관리를 가능하게 합니다.","es":"Habilita a los agentes a implementar nuevas funciones con un enfoque sistemático, utilizando convenciones semánticas para telemetría de IA y agentes especializados para exploración de código, diseño de arquitectura y revisión de calidad, todo mientras aprovecha OTLP y DuckDB para una gestión de datos eficiente","fr":"Permet aux agents de mettre en œuvre de nouvelles fonctionnalités avec une approche systématique, en utilisant des conventions sémantiques pour la télémétrie de l''IA et des agents spécialisés pour l''exploration du code, la conception d''architecture et l''examen de la qualité, le tout en exploitant OTLP et DuckDB pour une gestion de données efficace","de":"Ermöglicht es Agents, neue Funktionen mit einem systematischen Ansatz umzusetzen, indem sie semantische Konventionen für die Telemetrie von künstlicher Intelligenz und spezielle Agents für die Codebasis-Exploration, Architektur-Design und Qualitätsprüfung verwenden, und dabei OTLP und DuckDB für eine effiziente Datenverwaltung nutzen","pt":"Habilita os agentes a implementar novos recursos com uma abordagem sistemática, utilizando convenções semânticas para telemetria de IA e agentes especializados para exploração de código, design de arquitetura e revisão de qualidade, tudo isso aproveitando OTLP e DuckDB para gerenciamento de dados eficiente","ru":"Позволяет агентам реализовывать новые функции систематическим подходом, используя семантические конвенции для телеметрии ИИ и специализированные агенты для изучения кодовой базы, проектирования архитектуры и проверки качества, все это при эффективном управлении данными с помощью OTLP и DuckDB","ar":"تمكن الوكلاء من تنفيذ ميزات جديدة بطريقة منهجية، باستخدام الاتفاقيات الدلالية لتحكم تелеметريا الذكاء الاصطناعي والوكلاء المتخصصين لاستكشاف القاعدة البرمجية وتصميم البنية والتفتيش على الجودة، كل ذلك مع الاستفادة من OTLP وDuckDB لإدارة البيانات الفعالة"},"useCases":{"en":["Debugging AI model performance with OTLP ingestion","Analyzing codebase architecture with specialized agents","Reviewing feature quality with semantic conventions for AI telemetry"],"zh":["使用 OTLP 吸收进行 AI 模型性能调试","使用专用代理分析代码库架构","使用 AI 遥测的语义约定进行功能质量审查"],"ja":["OTLP 組み込みを使用した AI モデル パフォーマンスのデバッグ","専用エージェントを使用したコードベース アーキテクチャの分析","AI 遠隔測定のセマンティック規約を使用した機能品質のレビュー"],"ko":["OTLP 수신을 사용한 AI 모델 성능 디버깅","전문 에이전트를 사용한 코드베이스 아키텍처 분석","AI 원격 측정을 위한 의미 규약을 사용한 기능 품질 검토"],"es":["Depuración del rendimiento del modelo de IA con ingesta de OTLP","Análisis de la arquitectura de la base de código con agentes especializados","Revisión de la calidad de las funciones con convenciones semánticas para telemetría de IA"],"fr":["Débogage des performances du modèle d''IA avec ingestion OTLP","Analyse de l''architecture de la base de code avec des agents spécialisés","Examen de la qualité des fonctionnalités avec des conventions sémantiques pour la télémétrie de l''IA"],"de":["Fehlerbehebung der Leistung des KI-Modells mit OTLP-Einbindung","Analyse der Codebasis-Architektur mit speziellen Agents","Überprüfung der Funktionsqualität mit semantischen Konventionen für die Telemetrie von künstlicher Intelligenz"],"pt":["Depuração do desempenho do modelo de IA com ingestão OTLP","Análise da arquitetura da base de código com agentes especializados","Revisão da qualidade dos recursos com convenções semânticas para telemetria de IA"],"ru":["Отладка производительности модели ИИ с ингестией OTLP","Анализ архитектуры кодовой базы с помощью специализированных агентов","Проверка качества функций с использованием семантических конвенций для телеметрии ИИ"],"ar":["تصحيح أداء نموذج الذكاء الاصطناعي باستخدام استهلاك OTLP","تحليل هيكل قاعدة البرمجيات باستخدام وكلاء متخصصين","مراجعة جودة الميزات باستخدام الاتفاقيات الدلالية لتحكم تелеметريا الذكاء الاصطناعي"]},"limitations":{"en":["Requires OTLP ingestion setup","DuckDB storage configuration needed","Limited to GenAI/LLM workloads"],"zh":["需要 OTLP 吸收设置","需要 DuckDB 存储配置","仅限于 GenAI/LLM 工作负载"],"ja":["OTLP 組み込みの設定が必要","DuckDB ストレージの設定が必要","GenAI/LLM ワークロードのみに限定"],"ko":["OTLP 수신 설정이 필요합니다.","DuckDB 저장소 구성이 필요합니다.","GenAI/LLM 워크로드에만 제한됨"],"es":["Requiere configuración de ingesta de OTLP","Se necesita configuración de almacenamiento de DuckDB","Limitado a cargas de trabajo de GenAI/LLM"],"fr":["Nécessite une configuration d''ingestion OTLP","Une configuration de stockage DuckDB est nécessaire","Limité aux charges de travail GenAI/LLM"],"de":["Benötigt OTLP-Einbindungskonfiguration","DuckDB-Speicherkonfiguration erforderlich","Begrenzt auf GenAI/LLM-Workloads"],"pt":["Requer configuração de ingestão OTLP","Configuração de armazenamento DuckDB necessária","Limitado a cargas de trabalho GenAI/LLM"],"ru":["Требуется настройка ингестии OTLP","Необходима конфигурация хранилища DuckDB","Ограничен для рабочих нагрузок GenAI/LLM"],"ar":["يتطلب إعداد استهلاك OTLP","يتطلب إعداد تخزين DuckDB","محدود لتحميل العمل GenAI/LLM"]},"version":3},"qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ANcpLua/qyl/brainstorming', 'community', 'ANcpLua', 'qyl', 'ANcpLua/qyl', 'brainstorming', 0, 0, 0, '2026-02-18T01:08:43.448Z', '2026-02-18T06:32:26.180Z', NULL, '{"id":"ANcpLua/qyl/brainstorming","name":"brainstorming","description":{"es":"Brainstorming es una habilidad que ayuda a convertir ideas en diseños y especificaciones a través del diálogo colaborativo","fr":"Brainstorming est une compétence qui aide à convertir des idées en conceptions et spécifications à travers le dialogue collaboratif","de":"Brainstorming ist eine Fähigkeit, die dabei hilft, Ideen in Designs und Spezifikationen durch Zusammenarbeit umzuwandeln","en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"seo":{"title":{"es":"Generación de ideas con Brainstorming","fr":"Génération d''idées avec Brainstorming","de":"Ideen generieren mit Brainstorming","en":"brainstorming"},"description":{"es":"Brainstorming es una habilidad que ayuda a convertir ideas en diseños y especificaciones a través del diálogo colaborativo","fr":"Brainstorming est une compétence qui aide à convertir des idées en conceptions et spécifications à travers le dialogue collaboratif","de":"Brainstorming ist eine Fähigkeit, die dabei hilft, Ideen in Designs und Spezifikationen durch Zusammenarbeit umzuwandeln","en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"definition":{"en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"features":{"es":["Generación de ideas a través del diálogo colaborativo","Conversión de ideas en diseños y especificaciones","Integración con la plataforma de observabilidad de AI","Almacenamiento de datos con DuckDB","Soporte para convenciones semánticas para telemetría de AI"],"fr":["Génération d''idées à travers le dialogue collaboratif","Conversion d''idées en conceptions et spécifications","Intégration avec la plateforme d''observabilité de l''IA","Stockage de données avec DuckDB","Prise en charge des conventions sémantiques pour la télémétrie de l''IA"],"de":["Generierung von Ideen durch Zusammenarbeit","Umwandlung von Ideen in Designs und Spezifikationen","Integration mit der AI-Überwachungsplattform","DatenSpeicherung mit DuckDB","Unterstützung für semantische Konventionen für AI-Telemetrie"]},"keywords":{"es":["brainstorming","generación de ideas","diseño colaborativo","observabilidad de AI","DuckDB","telemetría de AI","desarrollo de software","colaboración en equipo"],"fr":["brainstorming","génération d''idées","conception collaborative","observabilité de l''IA","DuckDB","télémétrie de l''IA","développement de logiciels","collaboration d''équipe"],"de":["brainstorming","ideengenerierung","zusammenarbeitsdesign","ai-überwachung","DuckDB","ai-telemetrie","softwareentwicklung","teamzusammenarbeit"]}},"owner":"ANcpLua","repo":"qyl","repoPath":"ANcpLua/qyl","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"brainstorming","description":"|","bodyPreview":"## Source Metadata\n\n```yaml\nplugin:\n  name: \"superpowers\"\n  version: \"4.1.1\"\n  description: \"Core skills library for Claude Code: TDD, debugging, collaboration patterns, and proven techniques\"\n  author:\n    name: \"Jesse Vincent\"\n    email: \"jesse@fsck.com\"\n```\n\n\n# Brainstorming Ideas Into Designs\n\n## Overview\n\nHelp turn ideas into fully formed designs and specs through natural collaborative dialogue.\n\nStart by understanding the current project context, then ask questions one at a time to refine","body":"## Source Metadata\n\n```yaml\nplugin:\n  name: \"superpowers\"\n  version: \"4.1.1\"\n  description: \"Core skills library for Claude Code: TDD, debugging, collaboration patterns, and proven techniques\"\n  author:\n    name: \"Jesse Vincent\"\n    email: \"jesse@fsck.com\"\n```\n\n\n# Brainstorming Ideas Into Designs\n\n## Overview\n\nHelp turn ideas into fully formed designs and specs through natural collaborative dialogue.\n\nStart by understanding the current project context, then ask questions one at a time to refine the idea. Once you understand what you''re building, present the design in small sections (200-300 words), checking after each section whether it looks right so far.\n\n## The Process\n\n**Understanding the idea:**\n- Check out the current project state first (files, docs, recent commits)\n- Ask questions one at a time to refine the idea\n- Prefer multiple choice questions when possible, but open-ended is fine too\n- Only one question per message - if a topic needs more exploration, break it into multiple questions\n- Focus on understanding: purpose, constraints, success criteria\n\n**Exploring approaches:**\n- Propose 2-3 different approaches with trade-offs\n- Present options conversationally with your recommendation and reasoning\n- Lead with your recommended option and explain why\n\n**Presenting the design:**\n- Once you believe you understand what you''re building, present the design\n- Break it into sections of 200-300 words\n- Ask after each section whether it looks right so far\n- Cover: architecture, components, data flow, error handling, testing\n- Be ready to go back and clarify if something doesn''t make sense\n\n## After the Design\n\n**Documentation:**\n- Write the validated design to `docs/plans/YYYY-MM-DD-<topic>-design.md`\n- Use elements-of-style:writing-clearly-and-concisely skill if available\n- Commit the design document to git\n\n**Implementation (if continuing):**\n- Ask: \"Ready to set up for implementation?\"\n- Use superpowers:using-git-worktrees to create isolated workspace\n- Use superpowers:writing-plans to create detailed implementation plan\n\n## Key Principles\n\n- **One question at a time** - Don''t overwhelm with multiple questions\n- **Multiple choice preferred** - Easier to answer than open-ended when possible\n- **YAGNI ruthlessly** - Remove unnecessary features from all designs\n- **Explore alternatives** - Always propose 2-3 approaches before settling\n- **Incremental validation** - Present design in sections, validate each\n- **Be flexible** - Go back and clarify when something doesn''t make sense\n"},"lastSynced":"2026-02-18T06:32:26.180Z","agentAnalysis":{"suitability":{"en":"Ideal for Conversational AI Agents like Claude Code, AutoGPT, and LangChain needing collaborative dialogue for idea refinement and design specs.","zh":"适合需要协作对话来完善想法和设计规范的对话式 AI 代理，如 Claude Code、AutoGPT 和 LangChain。","ja":"Claude Code、AutoGPT、LangChain などのアイデアの洗練と設計仕様のためにコラボレーション ダイアログが必要な会話型 AI エージェントに最適です。","ko":"아이디어를 정제하고 설계 사양을 위해 협력 대화를 필요로 하는 Claude Code, AutoGPT, LangChain 등의 대화형 AI 에이전트에 적합합니다.","es":"Ideal para agentes de inteligencia artificial conversacional como Claude Code, AutoGPT y LangChain que necesitan diálogo colaborativo para la refinación de ideas y especificaciones de diseño.","fr":"Idéal pour les agents d''intelligence artificielle conversationnelle comme Claude Code, AutoGPT et LangChain qui nécessitent un dialogue collaboratif pour l''affinement des idées et les spécifications de conception.","de":"Ideal für Conversational-AI-Agents wie Claude Code, AutoGPT und LangChain, die ein kollaboratives Dialogsystem für die Verfeinerung von Ideen und Designspezifikationen benötigen.","pt":"Ideal para Agentes de IA Conversacional como Claude Code, AutoGPT e LangChain que necessitam de diálogo colaborativo para refinar ideias e especificações de design.","ru":"Идеально подходит для разговорных агентов ИИ, таких как Claude Code, AutoGPT и LangChain, которым требуется совместный диалог для усовершенствования идей и спецификаций дизайна.","ar":"مثالي لوكلاء الذكاء الاصطناعي للتعاملات الحوارية مثل Claude Code و AutoGPT و LangChain الذين يحتاجون إلى حوار تعاوني لتنقية الأفكار ومواصفات التصميم."},"recommendation":{"en":"Empowers agents to engage in natural collaborative dialogue, utilizing semantic conventions for AI telemetry and OTLP ingestion to refine ideas into fully formed designs and specs, leveraging DuckDB storage for efficient data management.","zh":"赋予代理以自然的协作对话能力，利用语义约定进行 AI 遥测和 OTLP 摄取，以完善想法并形成完整的设计和规范，同时利用 DuckDB 存储进行高效的数据管理。","ja":"エージェントが自然なコラボレーション ダイアログに従事できるようにし、AI テレメトリと OTLP イングェストのためのセマンティック規約を利用して、アイデアを完全な設計と仕様に洗練し、DuckDB ストレージを使用して効率的なデータ管理を実現します。","ko":"에이전트가 자연스러운 협력 대화를 수행할 수 있도록 하여 아이디어를 완전히 설계하고 사양으로 정제하고, AI 원격 측정 및 OTLP 摄取을 위한 의미 규약을 활용하며, 효율적인 데이터 관리를 위해 DuckDB 저장소를 사용합니다.","es":"Permite a los agentes participar en un diálogo colaborativo natural, utilizando convenciones semánticas para la telemetría de inteligencia artificial y la ingesta de OTLP para refinar ideas en diseños y especificaciones completamente formados, aprovechando el almacenamiento de DuckDB para una gestión de datos eficiente.","fr":"Permet aux agents de s''engager dans un dialogue collaboratif naturel, en utilisant des conventions sémantiques pour la télémétrie d''intelligence artificielle et l''ingestion de OTLP pour affiner les idées en conceptions et spécifications entièrement formées, en exploitant le stockage DuckDB pour une gestion de données efficace.","de":"Ermächtigt die Agenten, an einem natürlichen kollaborativen Dialog teilzunehmen, indem sie semantische Konventionen für die Telemetrie von künstlicher Intelligenz und die OTLP-Einbindung nutzen, um Ideen in vollständig ausgebildete Entwürfe und Spezifikationen zu verfeinern, und dabei den DuckDB-Speicher für eine effiziente Datenverwaltung nutzen.","pt":"Habilita os agentes a se engajarem em diálogo colaborativo natural, utilizando convenções semânticas para telemetria de IA e ingestão de OTLP para refinar ideias em designs e especificações totalmente formados, aproveitando o armazenamento DuckDB para gerenciamento de dados eficiente.","ru":"Наделяет агентов возможностью участвовать в естественном совместном диалоге, используя семантические конвенции для телеметрии ИИ и ингестии OTLP для усовершенствования идей в полностью сформированные дизайны и спецификации, используя хранилище DuckDB для эффективного управления данными.","ar":"تمكن الوكلاء من المشاركة في حوار تعاوني طبيعي، باستخدام الاتفاقيات الدلالية لتелеметريا الذكاء الاصطناعي وامتصاص OTLP لتنقية الأفكار إلى تصاميم ومواصفات متكاملة، مستفيداً من تخزين DuckDB للإدارة الفعالة للبيانات."},"useCases":{"en":["Refining project ideas through iterative questioning","Generating fully formed design specs through collaborative dialogue","Analyzing project context to inform design decisions"],"zh":["通过迭代提问来完善项目想法","通过协作对话生成完整的设计规范","分析项目背景以指导设计决策"],"ja":["イテレーティブな質問を通じてプロジェクトのアイデアを洗練する","コラボレーション ダイアログを通じて完全な設計仕様を生成する","設計の決定を導くためにプロジェクトの背景を分析する"],"ko":["반복적인 질문을 통해 프로젝트 아이디어를 정제한다","협력 대화를 통해 완전한 설계 사양을 생성한다","설계 결정에 대한 정보를 제공하기 위해 프로젝트 맥락을 분석한다"],"es":["Perfeccionar ideas de proyectos a través de preguntas iterativas","Generar especificaciones de diseño completamente formadas a través de diálogo colaborativo","Analizar el contexto del proyecto para informar las decisiones de diseño"],"fr":["Affiner les idées de projet par questions iteratives","Générer des spécifications de conception entièrement formées par dialogue collaboratif","Analyser le contexte du projet pour éclairer les décisions de conception"],"de":["Projektideen durch iterative Fragen verfeinern","Vollständig ausgebildete Entwürfe und Spezifikationen durch kollaborativen Dialog generieren","Projektkontext analysieren, um Designentscheidungen zu treffen"],"pt":["Refinamento de ideias de projetos por meio de questionamento iterativo","Geração de especificações de design totalmente formadas por meio de diálogo colaborativo","Análise do contexto do projeto para informar decisões de design"],"ru":["Усовершенствование идей проекта посредством итеративного вопросирования","Генерация полностью сформированных спецификаций дизайна посредством совместного диалога","Анализ контекста проекта для информирования решений по дизайну"],"ar":["تنقية أفكار المشروع من خلال الاستفهام التكراري","توليد مواصفات التصميم المتكاملة بالكامل من خلال الحوار التعاوني","تحليل سياق المشروع لتهديد قرارات التصميم"]},"limitations":{"en":["Requires integration with AI Observability Platform","Dependent on plugin version compatibility (e.g., ''superpowers'' version 4.1.1)"],"zh":["需要与 AI 可观察性平台集成","依赖于插件版本兼容性（例如 ''superpowers'' 版本 4.1.1）"],"ja":["AI オブザーバビリティ プラットフォームとの統合が必要","プラグインのバージョン互換性 (例: ''superpowers'' バージョン 4.1.1) 依存"],"ko":["AI 관측 가능성 플랫폼과의 통합이 필요합니다","플러그인 버전 호환성에 의존합니다 (예: ''superpowers'' 버전 4.1.1)"],"es":["Requiere integración con la Plataforma de Observabilidad de Inteligencia Artificial","Dependiente de la compatibilidad de la versión del plugin (por ejemplo, la versión ''superpowers'' 4.1.1)"],"fr":["Nécessite une intégration avec la plate-forme d''observabilité d''intelligence artificielle","Dépend de la compatibilité de la version du plugin (par exemple, la version ''superpowers'' 4.1.1)"],"de":["Erfordert Integration mit der künstlichen Intelligenz-Beobachtungsplattform","Abhängig von der Kompatibilität der Plugin-Version (z. B. ''superpowers''-Version 4.1.1)"],"pt":["Requer integração com Plataforma de Observabilidade de IA","Dependente da compatibilidade da versão do plugin (por exemplo, versão ''superpowers'' 4.1.1)"],"ru":["Требует интеграции с платформой наблюдения за ИИ","Зависит от совместимости версии плагина (например, версия ''superpowers'' 4.1.1)"],"ar":["يتطلب التكامل مع منصة مراقبة الذكاء الاصطناعي","يعتمد على توافق إصدار البرنامج المساعد (على سبيل المثال، إصدار ''superpowers'' 4.1.1)"]},"version":3},"qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sanmak/kritarch-lite/security-env', 'community', 'sanmak', 'kritarch-lite', 'sanmak/kritarch-lite', 'security-env', 0, 0, 50, '2026-02-18T01:08:43.448Z', '2026-02-18T06:31:50.943Z', NULL, '{"id":"sanmak/kritarch-lite/security-env","name":"security-env","description":{"zh":"安全环境配置（security-env）帮助您安全地存储和管理密钥和配置，防止泄露，提高代码安全性。","ja":"セキュリティ環境設定（security-env）は、キーと設定を安全に保存および管理し、漏洩を防ぎ、コードのセキュリティを向上させます。","ko":"보안 환경 구성（security-env）は 키와 설정을 안전하게 저장하고 관리하여泄露를 방지하고 코드 보안을 강화합니다.","es":"El skill de seguridad de entorno te ayuda a mantener tus secretos a salvo. Aprende a almacenar claves y tokens de manera segura.","fr":"Le skill de sécurité de l''environnement vous aide à garder vos secrets en sécurité. Découvrez comment stocker vos clés et tokens de manière sécurisée.","de":"Das Umgebungsicherheits-Skill hilft Ihnen, Ihre Geheimnisse sicher zu bewahren. Erfahren Sie, wie Sie Ihre Schlüssel und Token sicher speichern können.","pt":"O security-env ajuda a manter seus segredos em segurança, fornecendo uma forma segura de armazenar e gerenciar variáveis de ambiente","ru":"Security-env помогает сохранить свои секреты в безопасности, предоставляя безопасный способ хранить и управлять переменными среды","ar":"يحافظ security-env على أمان أسرارك، ويقدم طريقة أمنية لتحديث وتنظيم متغيرات البيئة","en":"Kritarch Lite gives you a panel of AI agents that analyze the problem from competing angles, challenge each other''s reasoning, and deliver a structured verdict. You review the conclusion, not the process."},"seo":{"title":{"zh":"安全环境配置 - Security-env","ja":"セキュリティ環境設定 - Security-env","ko":"보안 환경 구성 - Security-env","es":"Seguridad de entorno: protege tus secretos","fr":"Sécurité de l''environnement: protégez vos secrets","de":"Umgebungsicherheit: schütze deine Geheimnisse","pt":"Segurança de Ambiente: Proteja Seus Segredos","ru":"Безопасность среды: защищайте свои секреты","ar":"أمان البيئة: احمِ أسرارك","en":"security-env"},"description":{"zh":"安全环境配置（security-env）帮助您安全地存储和管理密钥和配置，防止泄露，提高代码安全性。","ja":"セキュリティ環境設定（security-env）は、キーと設定を安全に保存および管理し、漏洩を防ぎ、コードのセキュリティを向上させます。","ko":"보안 환경 구성（security-env）は 키와 설정을 안전하게 저장하고 관리하여泄露를 방지하고 코드 보안을 강화합니다.","es":"El skill de seguridad de entorno te ayuda a mantener tus secretos a salvo. Aprende a almacenar claves y tokens de manera segura.","fr":"Le skill de sécurité de l''environnement vous aide à garder vos secrets en sécurité. Découvrez comment stocker vos clés et tokens de manière sécurisée.","de":"Das Umgebungsicherheits-Skill hilft Ihnen, Ihre Geheimnisse sicher zu bewahren. Erfahren Sie, wie Sie Ihre Schlüssel und Token sicher speichern können.","pt":"O security-env ajuda a manter seus segredos em segurança, fornecendo uma forma segura de armazenar e gerenciar variáveis de ambiente","ru":"Security-env помогает сохранить свои секреты в безопасности, предоставляя безопасный способ хранить и управлять переменными среды","ar":"يحافظ security-env على أمان أسرارك، ويقدم طريقة أمنية لتحديث وتنظيم متغيرات البيئة","en":"Kritarch Lite gives you a panel of AI agents that analyze the problem from competing angles, challenge each other''s reasoning, and deliver a structured verdi..."},"definition":{"en":"Kritarch Lite gives you a panel of AI agents that analyze the problem from competing angles, challenge each other''s reasoning, and deliver a structured verdict. You review the conclusion, not the process."},"features":{"zh":["存储密钥和配置在 `.env` 文件中","更新 `.env.example` 文件以包含新变量名和默认值","优先使用服务器端环境变量来存储密钥","清理日志以防止泄露令牌"],"ja":["キーと設定を `.env` ファイルに保存する","`.env.example` ファイルを更新して新しい変数名とデフォルト値を含める","サーバー専用の環境変数を使用してキーを保存することを優先する","ログをクリーンアップしてトークン漏洩を防ぐ"],"ko":["키와 설정을 `.env` 파일에 저장합니다","`.env.example` 파일을 업데이트하여 새로운 변수 이름과 기본 값을 포함합니다","서버 전용 환경 변수를 사용하여 키를 저장하는 것을 우선합니다","로그를 정리하여 토큰 누출을 방지합니다"],"es":["Almacenamiento de secretos en archivos .env","Actualización de .env.example con nuevos nombres de variables y valores predeterminados","Uso preferente de variables de entorno solo en el servidor","Sanitización de registros para evitar fugas de tokens","Evitación de la creación de secretos en el código del cliente"],"fr":["Stockage de secrets dans des fichiers .env","Mise à jour de .env.example avec de nouveaux noms de variables et valeurs par défaut","Utilisation préférée de variables d''environnement uniquement sur le serveur","Sanitisation des journaux pour éviter les fuites de tokens","Évitement de la création de secrets dans le code client"],"de":["Speicherung von Geheimnissen in .env-Dateien","Aktualisierung von .env.example mit neuen Variablenamen und Standardwerten","Bevorzugte Verwendung von Umgebungsvariablen nur auf dem Server","Sanitierung von Logdateien, um Token-Lecks zu vermeiden","Vermeidung der Erstellung von Geheimnissen im Client-Code"],"pt":["Armazenamento seguro de segredos","Gerenciamento de variáveis de ambiente","Proteção de chaves API","Sanitização de logs","Uso preferencial de variáveis de ambiente no servidor"],"ru":["Безопасное хранение секретов","Управление переменными среды","Защита ключей API","Санитизация журналов","Преимущественное использование переменных среды на сервере"],"ar":["تخزين آمن للأسرار","إدارة متغيرات البيئة","حماية مفاتيح API","تنقية السجلات","استخدام متغيرات البيئة على الخادم بشكل首في"]},"keywords":{"zh":["安全环境配置","密钥管理","配置管理","代码安全","环境变量","安全开发"],"ja":["セキュリティ環境設定","キーマネジメント","設定管理","コードセキュリティ","環境変数","セキュア開発"],"ko":["보안 환경 구성","키 관리","설정 관리","코드 보안","환경 변수","보안 개발"],"es":["seguridad de entorno","protección de secretos","almacenamiento de claves","variables de entorno","sanitización de registros","desarrollo de software seguro","mejores prácticas de seguridad"],"fr":["sécurité de l''environnement","protection des secrets","stockage de clés","variables d''environnement","sanitisation des journaux","développement de logiciels sécurisés","meilleures pratiques de sécurité"],"de":["Umgebungsicherheit","Schutz von Geheimnissen","Speicherung von Schlüsseln","Umgebungsvariablen","Sanitierung von Logdateien","sichere Software-Entwicklung","beste Praktiken für Sicherheit"],"pt":["segurança de ambiente","proteção de segredos","gerenciamento de variáveis de ambiente","segurança de API","sanitização de logs","desenvolvimento de software seguro"],"ru":["безопасность среды","защита секретов","управление переменными среды","безопасность API","санитизация журналов","разработка безопасного программного обеспечения"],"ar":["أمان البيئة","حماية الأسرار","إدارة متغيرات البيئة","أمان API","تنقية السجلات","تطوير برامج آمنة"]}},"owner":"sanmak","repo":"kritarch-lite","repoPath":"sanmak/kritarch-lite","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"security-env","description":"Use when adding config, credentials, external services, or environment variables.","bodyPreview":"# Goal\nKeep secrets out of the repo and document required configuration safely.\n\n# Do\n- Store secrets in `.env` only; never commit real keys.\n- Update `.env.example` with new variable names and defaults.\n- Prefer server-only env usage for secrets (API routes, server components).\n- Sanitize logs to avoid leaking tokens.\n\n# Don''t\n- Commit secrets or embed keys in client code.\n\n# Examples\n- \"Add a new API key and update `.env.example`.\"\n- \"Move client-only env usage to a server route.\"","body":"# Goal\nKeep secrets out of the repo and document required configuration safely.\n\n# Do\n- Store secrets in `.env` only; never commit real keys.\n- Update `.env.example` with new variable names and defaults.\n- Prefer server-only env usage for secrets (API routes, server components).\n- Sanitize logs to avoid leaking tokens.\n\n# Don''t\n- Commit secrets or embed keys in client code.\n\n# Examples\n- \"Add a new API key and update `.env.example`.\"\n- \"Move client-only env usage to a server route.\"\n"},"lastSynced":"2026-02-18T06:31:50.943Z","agentAnalysis":{"suitability":{"en":"Ideal for Security-Conscious Agents requiring secrets management and secure configuration practices.","zh":"非常适合注重安全的代理，需要密钥管理和安全配置实践。","ja":"シークレット管理と安全な構成プラクティスを必要とするセキュリティ意識の高いエージェントに最適です。","ko":"비밀 관리와 보안 구성 관행이 필요한 보안 의식이 높은 에이전트에 이상적입니다.","es":"Ideal para agentes conscientes de la seguridad que requieren gestión de secretos y prácticas de configuración seguras.","fr":"Idéal pour les agents conscients de la sécurité nécessitant une gestion des secrets et des pratiques de configuration sécurisées.","de":"Ideal für sicherheitsbewusste Agenten, die eine Secret-Verwaltung und sichere Konfigurationspraktiken erfordern.","pt":"Ideal para agentes conscientes da segurança que exigem gerenciamento de segredos e práticas de configuração seguras.","ru":"Идеально для агентов, осознающих безопасность, требующих управления секретами и безопасных практик конфигурации.","ar":"مثالي للوكلاء المهتمين بالأمور الأمنية الذين يحتاجون إلى إدارة الأسرار وممارسات التهيئة الآمنة."},"recommendation":{"en":"Empowers agents to store secrets securely in `.env` files, sanitize logs to prevent token leaks, and prefer server-only environment usage for sensitive data, ensuring compliance with best practices for API key management and server component security.","zh":"使代理能够安全地将密钥存储在`.env`文件中，清理日志以防止令牌泄漏，并建议对敏感数据仅使用服务器端环境，确保符合API密钥管理和服务器组件安全的最佳实践。","ja":"エージェントが`.env`ファイルにシークレットを安全に保存し、トークン漏洩を防ぐためにログをサニタイズし、機密データにはサーバー側環境の使用を推奨することを可能にし、APIキー管理とサーバーコンポーネントのセキュリティに関するベストプラクティスへの準拠を保証します。","ko":"에이전트가 `.env` 파일에 비밀을 안전하게 저장하고, 토큰 누출을 방지하기 위해 로그를 삭제하며, 민감한 데이터에 대해 서버 전용 환경 사용을 선호하도록 지원하여 API 키 관리 및 서버 구성 요소 보안에 대한 모범 사례를 준수합니다.","es":"Permite a los agentes almacenar secretos de forma segura en archivos `.env`, sanear registros para prevenir fugas de tokens y preferir el uso de entornos de servidor solo para datos sensibles, garantizando el cumplimiento de las mejores prácticas para la gestión de claves de API y la seguridad de los componentes del servidor.","fr":"Permet aux agents de stocker des secrets de manière sécurisée dans des fichiers `.env`, de nettoyer les journaux pour éviter les fuites de tokens et de préférer l''utilisation d''environnements de serveur uniquement pour les données sensibles, garantissant ainsi le respect des meilleures pratiques pour la gestion des clés d''API et la sécurité des composants du serveur.","de":"Ermöglicht es Agenten, Geheimnisse sicher in `.env`-Dateien zu speichern, Protokolle zu säubern, um Token-Leaks zu verhindern und die Verwendung von Server-Only-Umgebungen für sensible Daten zu bevorzugen, um die Einhaltung der Best Practices für die API-Schlüsselverwaltung und die Serverkomponentensicherheit sicherzustellen.","pt":"Permite que os agentes armazenem segredos de forma segura em arquivos `.env`, sanitizem logs para prevenir vazamentos de tokens e prefiram o uso de ambiente somente servidor para dados sensíveis, garantindo conformidade com as melhores práticas para gerenciamento de chaves de API e segurança de componentes de servidor.","ru":"Наделяет агентов возможностью хранить секреты в файлах `.env` безопасно, очищать логи для предотвращения утечки токенов и отдавать предпочтение использованию серверной среды для конфиденциальных данных, обеспечивая соответствие лучшим практикам для управления ключами API и безопасности серверных компонентов.","ar":"تمكن الوكلاء من تخزين الأسرار بشكل آمن في ملفات `.env` ، وتطهير السجلات لمنع تسرب الرموز، والأفضل استخدام بيئة الخادم فقط للبيانات الحساسة، مما يضمن الامتثال لأفضل الممارسات لإدارة مفتاح واجهة البرمجة التطبيقية وأمان مكونات الخادم."},"useCases":{"en":["Securing API keys with `.env` files","Sanitizing logs to prevent token leaks","Migrating client-only env usage to server routes"],"zh":["使用`.env`文件保护API密钥","清理日志以防止令牌泄漏","将仅客户端环境使用迁移到服务器路由"],"ja":["`.env`ファイルを使用したAPIキーの保護","トークン漏洩を防ぐためのログのサニタイズ","クライアントのみの環境使用からサーバールートへの移行"],"ko":["`.env` 파일로 API 키 보안","토큰 누출 방지를 위한 로그 삭제","클라이언트 전용 환경 사용을 서버 경로로 마이그레이션"],"es":["Seguridad de claves de API con archivos `.env`","Limpieza de registros para prevenir fugas de tokens","Migración del uso de entornos de cliente solo a rutas de servidor"],"fr":["Sécurisation des clés d''API avec des fichiers `.env`","Nettoyage des journaux pour éviter les fuites de tokens","Migration de l''utilisation d''environnements de client uniquement vers des itinéraires de serveur"],"de":["Sicherung von API-Schlüsseln mit `.env`-Dateien","Säubern von Protokollen, um Token-Leaks zu verhindern","Migration von client-only-Umgebungsverwendung zu Server-Routen"],"pt":["Proteger chaves de API com arquivos `.env`","Sanitizar logs para prevenir vazamentos de tokens","Migrar o uso de ambiente somente cliente para rotas de servidor"],"ru":["Защищать ключи API с помощью файлов `.env`","Очищать логи для предотвращения утечки токенов","Перемещать использование среды только для клиента на серверные маршруты"],"ar":["حماية مفتاح واجهة البرمجة التطبيقية باستخدام ملفات `.env`","تطهير السجلات لمنع تسرب الرموز","نقل استخدام بيئة العملاء فقط إلى مسارات الخادم"]},"limitations":{"en":["Requires `.env` file setup","Server-only environment usage recommended"],"zh":["需要设置`.env`文件","建议仅使用服务器端环境"],"ja":["`.env`ファイルの設定が必要","サーバー側環境の使用を推奨"],"ko":["`.env` 파일 설정 필요","서버 전용 환경 사용 권장"],"es":["Requiere configuración de archivos `.env`","Se recomienda el uso de entornos de servidor solo"],"fr":["Nécessite une configuration de fichiers `.env`","L''utilisation d''environnements de serveur uniquement est recommandée"],"de":["Benötigt `.env`-Dateieinrichtung","Server-Only-Umgebungsverwendung wird empfohlen"],"pt":["Exige configuração de arquivo `.env`","Uso de ambiente somente servidor recomendado"],"ru":["Требует настройки файла `.env`","Рекомендуется использование серверной среды"],"ar":["يتطلب إعداد ملف `.env`","يوصى باستخدام بيئة الخادم فقط"]},"version":3},"qualityScore":50}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danielcastro-dev/speclet/speclet-learn', 'community', 'danielcastro-dev', 'speclet', 'danielcastro-dev/speclet', 'speclet-learn', 0, 0, 50, '2026-02-18T01:08:43.448Z', '2026-02-18T06:32:38.434Z', NULL, '{"id":"danielcastro-dev/speclet/speclet-learn","name":"speclet-learn","description":{"zh":"Speclet Learn 技术技能是一种代码分析和优化工具，帮助开发者提高代码质量和开发效率","ja":"Speclet Learn スキルは、コード分析と最適化ツールです。開発者のコード品質と開発効率を向上させます","ko":"Speclet Learn 기술 스킬은 코드 분석과 최적화 도구로 개발자의 코드 품질과 개발 효율성을 향상시킵니다","es":"Speclet Learn es una herramienta que genera lecciones explicativas para desarrollar fluidez mecánica en el desarrollo de software","fr":"Speclet Learn est un outil qui génère des leçons explicatives pour développer la fluidité mécanique dans le développement de logiciels","de":"Speclet Learn ist ein Tool, das erklärende Lektionen generiert, um die mechanische Flüssigkeit in der Softwareentwicklung zu entwickeln","pt":"Speclet Learn gera lições explicativas após cada história completada para desenvolver fluidez mecânica","ru":"Speclet Learn генерирует объяснительные уроки после каждой завершенной истории для развития механической грамотности","ar":"Speclet Learn يولد دروسًا توضيحية بعد كل قصة مكتملة لتطوير السهولة الميكانيكية","en":""},"seo":{"title":{"zh":"Speclet Learn 技术技能","ja":"Speclet Learn スキル","ko":"Speclet Learn 기술 스킬","es":"Speclet Learn: Aprende con lecciones automáticas","fr":"Speclet Learn: Apprendre avec des leçons automatiques","de":"Speclet Learn: Lernen mit automatischen Lektionen","pt":"Aprenda com Speclet Learn","ru":"Speclet Learn: инструмент для разработчиков","ar":"تعلم مع Speclet Learn","en":"speclet-learn"},"description":{"zh":"Speclet Learn 技术技能是一种代码分析和优化工具，帮助开发者提高代码质量和开发效率","ja":"Speclet Learn スキルは、コード分析と最適化ツールです。開発者のコード品質と開発効率を向上させます","ko":"Speclet Learn 기술 스킬은 코드 분석과 최적화 도구로 개발자의 코드 품질과 개발 효율성을 향상시킵니다","es":"Speclet Learn es una herramienta que genera lecciones explicativas para desarrollar fluidez mecánica en el desarrollo de software","fr":"Speclet Learn est un outil qui génère des leçons explicatives pour développer la fluidité mécanique dans le développement de logiciels","de":"Speclet Learn ist ein Tool, das erklärende Lektionen generiert, um die mechanische Flüssigkeit in der Softwareentwicklung zu entwickeln","pt":"Speclet Learn gera lições explicativas após cada história completada para desenvolver fluidez mecânica","ru":"Speclet Learn генерирует объяснительные уроки после каждой завершенной истории для развития механической грамотности","ar":"Speclet Learn يولد دروسًا توضيحية بعد كل قصة مكتملة لتطوير السهولة الميكانيكية","en":""},"definition":{"en":""},"features":{"zh":["自动化代码分析","优化代码质量","提高开发效率","生成代码注释","提供错误检测和修复"],"ja":["自動化コード分析","コード品質の最適化","開発効率の向上","コード注釈の生成","エラー検出と修復"],"ko":["자동화 코드 분석","코드 품질 최적화","개발 효율성 향상","코드 주석 생성","오류 검출과 수정"],"es":["Genera lecciones explicativas después de cada historia completada","Analiza los archivos modificados en cada historia","Incluye decisiones técnicas y conceptos explicados","Proporciona código anotado y ejercicios de práctica","Detecta la complejidad y adapta el contenido de la lección"],"fr":["Génère des leçons explicatives après chaque histoire complétée","Analyse les fichiers modifiés dans chaque histoire","Inclut des décisions techniques et des concepts expliqués","Fournit du code annoté et des exercices de pratique","Détecte la complexité et adapte le contenu de la leçon"],"de":["Generiert erklärende Lektionen nach jeder abgeschlossenen Geschichte","Analyisiert die geänderten Dateien in jeder Geschichte","Enthält technische Entscheidungen und erklärte Konzepte","Bietet annotierten Code und Übungsaufgaben","Erkennnt die Komplexität und passt den Lektionsinhalt an"],"pt":["Geração de lições explicativas","Análise de arquivos modificados","Código anotado","Erros comuns","Exercícios de prática"],"ru":["Генерация объяснительных уроков","Анализ измененных файлов","Помеченный код","Распространенные ошибки","Упражнения для практики"],"ar":["توليد دروس توضيحية","تحليل الملفات المعدلة","كود مُشروح","أخطاء شائعة","تمارين للممارسة"]},"keywords":{"zh":["Speclet Learn","代码分析","代码优化","开发效率","代码质量","自动化测试"],"ja":["Speclet Learn","コード分析","コード最適化","開発効率","コード品質","自動テスト"],"ko":["Speclet Learn","코드 분석","코드 최적화","개발 효율성","코드 품질","자동화 테스트"],"es":["aprendizaje automático","desarrollo de software","fluidez mecánica","lecciones explicativas","herramientas de aprendizaje","desarrollo de habilidades","tecnologías de aprendizaje"],"fr":["apprentissage automatique","développement de logiciels","fluidité mécanique","leçons explicatives","outils d''apprentissage","développement de compétences","technologies d''apprentissage"],"de":["automatisches Lernen","Softwareentwicklung","mechanische Flüssigkeit","erklärende Lektionen","Lernwerkzeuge","Fähigkeitsentwicklung","Lerntechnologien"],"pt":["desenvolvimento de software","fluidez mecânica","lições explicativas","speclet learn","ferramentas de desenvolvimento","aprendizado de programação"],"ru":["разработка программного обеспечения","механическая грамотность","объяснительные уроки","speclet learn","инструменты разработки","обучение программированию"],"ar":["تطوير البرمجيات","السهولة الميكانيكية","دروس توضيحية","speclet learn","أدوات التطوير","تعلم البرمجة"]}},"owner":"danielcastro-dev","repo":"speclet","repoPath":"danielcastro-dev/speclet","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"speclet-learn","description":"Generate explanatory lessons after completing speclet stories to develop mechanical coding fluency","bodyPreview":"# Speclet Learn Skill\n\nGenera lecciones explicativas después de cada story completada para desarrollar fluidez mecánica.\n\n## What I Do\n\n- Leo spec.json y encuentro la última story con `passes: true`\n- Analizo los archivos modificados en esa story\n- Genero una lección en `.speclet/lessons/STORY-X.md` con:\n  - Decisiones técnicas (por qué X y no Y)\n  - Conceptos explicados según complejidad detectada\n  - Código anotado\n  - Errores comunes\n  - Ejercicio de práctica (10-15 min, sin LLM)\n\n## When to","body":"# Speclet Learn Skill\n\nGenera lecciones explicativas después de cada story completada para desarrollar fluidez mecánica.\n\n## What I Do\n\n- Leo spec.json y encuentro la última story con `passes: true`\n- Analizo los archivos modificados en esa story\n- Genero una lección en `.speclet/lessons/STORY-X.md` con:\n  - Decisiones técnicas (por qué X y no Y)\n  - Conceptos explicados según complejidad detectada\n  - Código anotado\n  - Errores comunes\n  - Ejercicio de práctica (10-15 min, sin LLM)\n\n## When to Use Me\n\nDespués de completar stories con speclet-loop:\n\n```\n/speclet-learn\n```\n\nIdeal para tu rutina de 30 min de práctica antes del trabajo.\n\n## Your Task\n\n### Step 1: Find Last Completed Story\n\nLee `.speclet/spec.json` y encuentra la última story con `\"passes\": true`.\n\n```bash\n# Busca la story con passes: true y el priority más alto (última completada)\n```\n\nSi no hay stories con `passes: true`, responde:\n\n```\n❌ No hay stories completadas aún. Primero completa al menos una story con /speclet-loop.\n```\n\n### Step 2: Read Modified Files\n\nLee los archivos del campo `\"files\"` de esa story.\n\nAnaliza:\n- Qué patrones se usaron\n- Qué conceptos están presentes\n- Nivel de complejidad\n\n### Step 3: Detect Complexity\n\nClasifica cada concepto encontrado según la **Tabla de Complejidad**:\n\n#### 🟢 Nivel Básico (explicación mínima: 1-2 líneas)\n\n| Patrón | Ejemplo |\n|--------|---------|\n| Variables y tipos | `name: str = \"valor\"` |\n| Condicionales | `if x > 0:` |\n| Loops básicos | `for item in list:` |\n| Funciones simples | `def foo(x): return x + 1` |\n| Imports | `from x import y` |\n| F-strings | `f\"Hola {nombre}\"` |\n| Diccionarios/Listas | `data = {\"key\": \"value\"}` |\n\n**Acción:** Mención breve. \"Ya conoces esto.\"\n\n#### 🟡 Nivel Intermedio (explicación media: 5-10 líneas + ejemplo)\n\n| Patrón | Ejemplo |\n|--------|---------|\n| Clases | `class Product:` |\n| Decoradores básicos | `@router.get(\"/\")` |\n| List/Dict comprehensions | `[x*2 for x in items]` |\n| Type hints | `def foo(x: str) -> int:` |\n| Context managers | `with open(file) as f:` |\n| Excepciones | `try/except/finally` |\n| Args/Kwargs | `def foo(*args, **kwargs):` |\n| Properties | `@property` |\n\n**Acción:** Explicar qué hace, por qué se usa, ejemplo comentado.\n\n#### 🔴 Nivel Avanzado (explicación profunda: 10-20 líneas + múltiples ejemplos)\n\n| Patrón | Ejemplo |\n|--------|---------|\n| Async/Await | `async def fetch():` |\n| Decoradores personalizados | `def my_decorator(func):` |\n| Closures | Función que retorna función |\n| Generadores | `yield` |\n| Metaclasses | `class Meta(type):` |\n| Descriptors | `__get__`, `__set__` |\n| Generic types | `List[T]`, `TypeVar` |\n| Dependency Injection | `Depends()` |\n| SQLAlchemy/SQLModel | Sesiones, queries, relaciones |\n\n**Acción:** Explicar en profundidad: qué es, cómo funciona internamente, cuándo usarlo, errores comunes.\n\n### Step 4: Generate Lesson\n\nCrea `.speclet/lessons/STORY-X.md` con la estructura definida en la sección **Lesson Template**.\n\n### Step 5: Confirm\n\nResponde:\n\n```\n✅ Lección generada: .speclet/lessons/STORY-X.md\n\n📚 Conceptos cubiertos:\n- [Concepto 1] (🟢 básico)\n- [Concepto 2] (🟡 intermedio)\n- [Concepto 3] (🔴 avanzado)\n\n⏱️ Ejercicio de práctica: [Descripción breve] (15 min, sin LLM)\n\nCuando termines el ejercicio, compara tu código con los archivos reales:\n- [archivo1.py]\n- [archivo2.py]\n```\n\n---\n\n## Lesson Template\n\nGenera `.speclet/lessons/STORY-X.md` con esta estructura exacta:\n\n```markdown\n# Lección: STORY-X — [Título de la Story]\n\n**Fecha:** YYYY-MM-DD\n**Archivos:** [lista de archivos modificados]\n**Complejidad detectada:** 🟢/🟡/🔴 [Nivel predominante] ([conceptos principales])\n\n---\n\n## Resumen\n\n[2-3 oraciones: Qué se implementó y por qué importa]\n\n---\n\n## Decisiones Técnicas\n\n### ¿Por qué [decisión 1]?\n\n**Alternativas consideradas:**\n1. [Alternativa A] → [Por qué no]\n2. [Alternativa B] → [Por qué no]\n3. **[Lo que elegimos]** → [Por qué sí] ✅\n\n[Explicación de 3-5 líneas]\n\n### ¿Por qué [decisión 2]?\n\n[Mismo formato...]\n\n---\n\n## Conceptos Explicados\n\n### [Concepto 1] (🟢/🟡/🔴)\n\n[Explicación según nivel de complejidad]\n\n```python\n# Ejemplo de código comentado\n```\n\n### [Concepto 2] (🟢/🟡/🔴)\n\n[Explicación según nivel...]\n\n---\n\n## Errores Comunes\n\n### ❌ [Error 1]\n\n```python\n# MAL\n[código incorrecto]\n\n# BIEN\n[código correcto]\n```\n\n**Por qué falla:** [Explicación breve]\n\n### ❌ [Error 2]\n\n[Mismo formato...]\n\n---\n\n## Ejercicio de Práctica\n\n**Tiempo:** 10-15 minutos\n**Regla:** SIN LLM. Solo docs oficiales si te trabas.\n\n### El Reto\n\n[Descripción clara del ejercicio relacionado con la story]\n\n1. [Paso 1]\n2. [Paso 2]\n3. [Paso 3]\n\n**Archivo a crear:** `[path/to/exercise_file.py]` (no toques el código real)\n\n---\n\n### Hints (solo si te trabas)\n\n<details>\n<summary>Hint 1 (estructura general)</summary>\n\n```python\n# Esqueleto básico sin la lógica\n```\n\n</details>\n\n<details>\n<summary>Hint 2 (concepto clave)</summary>\n\n[Pista sobre el concepto principal que necesitas]\n\n</details>\n\n<details>\n<summary>Hint 3 (casi la respuesta)</summary>\n\n```python\n# Código más completo, falta un detalle\n```\n\n</details>\n\n---\n\n## Próximo Paso\n\nCuando termines (o después de 15 min intentando), compara con:\n- `[archivo_real_1.py]`\n- `[archivo_real_2.py]`\n\n**Pregúntate:**\n- ¿Qué hice diferente?\n- ¿Por qué el código real eligió esa estructura?\n- ¿Qué concepto me falta entender mejor?\n```\n\n---\n\n## Language Rules\n\n- **Código:** Siempre en inglés (variables, funciones, comentarios de código)\n- **Explicaciones:** En español\n- **Prioridad de profundidad:** Python > TypeScript (explicar más Python)\n\n---\n\n## Exercise Generation Rules\n\nEl ejercicio debe:\n\n1. **Estar relacionado con la story** — Mismo dominio, conceptos similares\n2. **Ser alcanzable en 10-15 min** — No más complejo que la story original\n3. **Forzar práctica sin LLM** — El punto es desarrollar fluidez mecánica\n4. **Tener 3 hints progresivos:**\n   - Hint 1: Estructura general (esqueleto)\n   - Hint 2: Concepto clave (pista conceptual)\n   - Hint 3: Casi la respuesta (código parcial)\n5. **NO incluir solución completa** — El usuario debe comparar con código real\n\n### Ejemplos de Buenos Ejercicios\n\n| Story Implementada | Ejercicio Propuesto |\n|--------------------|---------------------|\n| Endpoint GET /products | Crea POST /products con validación |\n| Servicio de búsqueda | Agrega filtro por categoría |\n| Modelo SQLModel | Agrega campo con relación FK |\n| Componente React | Crea variante del mismo componente |\n\n---\n\n## What NOT To Do\n\n- ❌ NO modifiques ningún archivo de código de producción\n- ❌ NO agregues comentarios de enseñanza al código real\n- ❌ NO incluyas soluciones completas a ejercicios\n- ❌ NO expliques conceptos básicos en detalle (sé breve)\n- ❌ NO generes lecciones para stories que no están completadas\n- ❌ NO uses el skill automáticamente — solo cuando el usuario lo invoca\n\n## Global Rules\n\n### Always Show Recommendation + Reason\n\nWhen asking questions with options, ALWAYS:\n1. Mark the recommended option with ⭐\n2. Add `**Reason for recommendation:**` explaining why\n\n**Example format:**\n```\n1. [Question]?\n   A. Option A\n   B. Option B ⭐ Recommended — [brief reason]\n   C. Option C\n\n   **Reason for recommendation:** [Detailed explanation of why B is best]\n```\n"},"lastSynced":"2026-02-18T06:32:38.434Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing automated lesson generation for mechanical fluency development.","zh":"非常适合需要自动化课程生成以开发机械流利度的代码分析代理。","ja":"コード分析エージェントが機械的流暢性の開発のために自動化されたレッスン生成を必要とする場合に最適です。","ko":"코드 분석 에이전트가 기계적 유창성을 개발하기 위해 자동화된 레슨 생성을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan generación de lecciones automatizada para el desarrollo de fluidez mecánica.","fr":"Parfait pour les agents d''analyse de code nécessitant une génération de leçons automatisée pour le développement de la fluidité mécanique.","de":"Perfekt für Code-Analyse-Agenten, die eine automatisierte Lektionenerstellung für die Entwicklung der mechanischen Flüssigkeit benötigen.","pt":"Perfeito para agentes de análise de código que necessitam de geração automática de lições para desenvolvimento de fluência mecânica.","ru":"Идеально подходит для агентов анализа кода, которым необходима автоматизированная генерация уроков для развития механической грамотности.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى توليد دروس تلقائي لتطوير الانسيابية الميكانيكية."},"recommendation":{"en":"Empowers agents to generate explanatory lessons with decision-making insights, annotated code, and practice exercises, utilizing spec.json files and markdown formatting for STORY-X.md lessons.","zh":"赋予代理生成带有决策洞察、注释代码和练习的解释性课程的能力，利用spec.json文件和markdown格式生成STORY-X.md课程。","ja":"エージェントが説明的なレッスンを生成する能力を与え、決定の洞察、注釈付きコード、練習問題を提供し、spec.jsonファイルとMarkdown形式を使用してSTORY-X.mdレッスンを生成します。","ko":"에이전트가 설명적인 레슨을 생성할 수 있는 능력을 부여하며, 의사 결정에 대한 통찰, 주석이 달린 코드 및 연습 문제를 제공하고, spec.json 파일 및 markdown 형식을 사용하여 STORY-X.md 레슨을 생성합니다.","es":"Habilita a los agentes a generar lecciones explicativas con información de toma de decisiones, código anotado y ejercicios de práctica, utilizando archivos spec.json y formato de markdown para lecciones STORY-X.md.","fr":"Permet aux agents de générer des leçons explicatives avec des informations de prise de décision, du code annoté et des exercices de pratique, en utilisant des fichiers spec.json et un format de markdown pour les leçons STORY-X.md.","de":"Ermächtigt die Agenten, erklärende Lektionen mit Entscheidungsfindungsinformationen, annotiertem Code und Übungsaufgaben zu generieren, indem sie spec.json-Dateien und Markdown-Formatierung für STORY-X.md-Lektionen nutzen.","pt":"Habilita os agentes a gerar lições explicativas com insights de tomada de decisões, código anotado e exercícios práticos, utilizando arquivos spec.json e formatação markdown para lições STORY-X.md.","ru":"Наделяет агентов возможностью генерировать объяснительные уроки с информацией о принятии решений, аннотированным кодом и практическими упражнениями, используя файлы spec.json и форматирование markdown для уроков STORY-X.md.","ar":"يتمكن الوكيل من توليد دروس توضيحية مع رؤى اتخاذ القرار والشفرة المُضاف إليها ملاحظات وتدريبات تمارين باستخدام ملفات spec.json وتدوين تنسيق لدرس STORY-X.md."},"useCases":{"en":["Automating lesson generation after completing stories","Generating technical decision explanations with complexity analysis","Creating annotated code snippets for educational purposes"],"zh":["完成故事后自动生成课程","生成带有复杂性分析的技术决策解释","创建用于教育目的的注释代码片段"],"ja":["ストーリーを完了した後に自動的にレッスンを生成する","複雑性分析を含む技術的な意思決定の説明を生成する","教育目的のための注釈付きコードスニペットを作成する"],"ko":["스토리를 완료한 후 자동으로 레슨을 생성한다","복잡성 분석을 포함한 기술적인 의사 결정에 대한 설명을 생성한다","교육 목적을 위한 주석이 달린 코드 스니펫을 생성한다"],"es":["Automatizar la generación de lecciones después de completar historias","Generar explicaciones de decisiones técnicas con análisis de complejidad","Crear fragmentos de código anotados para fines educativos"],"fr":["Automatiser la génération de leçons après avoir terminé les histoires","Générer des explications de décisions techniques avec analyse de complexité","Créer des extraits de code annotés à des fins pédagogiques"],"de":["Automatisieren der Lektionenerstellung nach Abschluss von Geschichten","Erstellen von technischen Entscheidungserklärungen mit Komplexitätsanalyse","Erstellen von annotierten Code-Snippets für Bildungszwecke"],"pt":["Automatizar a geração de lições após a conclusão de histórias","Gerar explicações técnicas de decisões com análise de complexidade","Criar trechos de código anotados para fins educacionais"],"ru":["Автоматизировать генерацию уроков после завершения историй","Генерировать технические объяснения решений с анализом сложности","Создавать аннотированные фрагменты кода для образовательных целей"],"ar":["تولييد 자동ي للدرس بعد إكمال القصص","توليد شروحات تقنية للقرارات مع تحليل التعقيد","إنشاء مقاطع من الشفرة المضافة إليها ملاحظات لأغراض تعليمية"]},"limitations":{"en":["Requires access to spec.json files","Limited to generating lessons in markdown format (.md files)","Dependent on story completion with ''passes: true'' status"],"zh":["需要访问spec.json文件","仅限生成markdown格式(.md文件)的课程","依赖于完成状态为''passes: true''的故事"],"ja":["spec.jsonファイルへのアクセスが必要","Markdown形式(.mdファイル)のレッスンのみを生成可能","状態が''passes: true''のストーリーを完了することへの依存"],"ko":["spec.json 파일에 대한 액세스가 필요합니다","markdown 형식(.md 파일)의 레슨만 생성할 수 있습니다","상태가 ''passes: true''인 스토리를 완료하는 것에 대한 의존"],"es":["Requiere acceso a archivos spec.json","Limitado a la generación de lecciones en formato markdown (.md)","Dependiente de la finalización de la historia con estado ''passes: true''"],"fr":["Nécessite l''accès aux fichiers spec.json","Limité à la génération de leçons au format markdown (.md)","Dépend de la fin de l''histoire avec le statut ''passes: true''"],"de":["Benötigt Zugriff auf spec.json-Dateien","Begrenzt auf die Generierung von Lektionen im Markdown-Format (.md-Dateien)","Abhängig vom Abschluss der Geschichte mit Status ''passes: true''"],"pt":["Requer acesso a arquivos spec.json","Limitado a gerar lições no formato markdown (.md files)","Dependente da conclusão da história com status ''passes: true''"],"ru":["Требует доступа к файлам spec.json","Ограничен генерацией уроков в формате markdown (.md files)","Зависит от завершения истории со статусом ''passes: true''"],"ar":["يتطلب الوصول إلى ملفات spec.json","محدود بتوليد الدروس بتنسيق markdown (.md files)","يعتمد على إكمال القصة بحالة ''passes: true''"]},"version":3},"qualityScore":50}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jabez4jc/Simplifyed/ui-ux-pro-max', 'community', 'jabez4jc', 'Simplifyed', 'jabez4jc/Simplifyed', 'ui-ux-pro-max', 0, 0, 65, '2026-02-18T01:08:43.448Z', '2026-02-18T06:32:38.574Z', NULL, '{"id":"jabez4jc/Simplifyed/ui-ux-pro-max","name":"ui-ux-pro-max","description":{"zh":"UI/UX Pro Max 是一个设计智能指南，包含 50+ 样式、97 色彩板、57 字体组合和 99 用户体验指南","ja":"UI/UX Pro Max は、50 を超えるスタイル、97 のカラーパレット、57 のフォントペア、99 の UX ガイドラインを含むデザイン インテリジェンス ガイドです","ko":"UI/UX Pro Max는 50개 이상의 스타일, 97개의 색상 팔레트, 57개의 폰트 조합 및 99개의 사용자 경험 가이드를 포함하는 디자인 인텔리전스 가이드입니다","es":"UI/UX Pro Max es una guía de diseño integral para aplicaciones web y móviles con una base de datos searchable y recomendaciones basadas en prioridades","fr":"UI/UX Pro Max est un guide de design complet pour les applications web et mobiles avec une base de données searchable et des recommandations basées sur les priorités","de":"UI/UX Pro Max ist ein umfassendes Design-Handbuch für Web- und Mobile-Anwendungen mit einer durchsuchbaren Datenbank und prioritätsbasierten Empfehlungen","pt":"O UI/UX Pro Max é um guia de design abrangente para aplicações web e móveis, contendo estilos, paletas de cores, combinações de fontes e diretrizes de UX.","ru":"UI/UX Pro Max - это комплексное руководство по дизайну для веб- и мобильных приложений, содержащее стили, цветовые палитры, комбинации шрифтов и рекомендации по UX.","ar":"UI/UX Pro Max هو دليل تصميم شامل لتطبيقات الويب والجوال، يحتوي على أنماط و_palettes ألوان وتركيبات خطوط وارشادات تجربة المستخدم.","en":""},"seo":{"title":{"zh":"UI/UX Pro Max - 设计智能指南","ja":"UI/UX Pro Max - デザインインテリジェンス","ko":"UI/UX Pro Max - 디자인 인텔리전스","es":"UI/UX Pro Max: Diseño Inteligente para Desarrolladores","fr":"UI/UX Pro Max : Intelligence de Design pour les Développeurs","de":"UI/UX Pro Max: Design-Intelligenz für Entwickler","pt":"UI/UX Pro Max: Guia de Design Inteligente","ru":"UI/UX Pro Max: Комплексное руководство по дизайну","ar":"UI/UX Pro Max: دليل التصميم الذكي","en":"ui-ux-pro-max"},"description":{"zh":"UI/UX Pro Max 是一个设计智能指南，包含 50+ 样式、97 色彩板、57 字体组合和 99 用户体验指南","ja":"UI/UX Pro Max は、50 を超えるスタイル、97 のカラーパレット、57 のフォントペア、99 の UX ガイドラインを含むデザイン インテリジェンス ガイドです","ko":"UI/UX Pro Max는 50개 이상의 스타일, 97개의 색상 팔레트, 57개의 폰트 조합 및 99개의 사용자 경험 가이드를 포함하는 디자인 인텔리전스 가이드입니다","es":"UI/UX Pro Max es una guía de diseño integral para aplicaciones web y móviles con una base de datos searchable y recomendaciones basadas en prioridades","fr":"UI/UX Pro Max est un guide de design complet pour les applications web et mobiles avec une base de données searchable et des recommandations basées sur les p...","de":"UI/UX Pro Max ist ein umfassendes Design-Handbuch für Web- und Mobile-Anwendungen mit einer durchsuchbaren Datenbank und prioritätsbasierten Empfehlungen","pt":"O UI/UX Pro Max é um guia de design abrangente para aplicações web e móveis, contendo estilos, paletas de cores, combinações de fontes e diretrizes de UX.","ru":"UI/UX Pro Max - это комплексное руководство по дизайну для веб- и мобильных приложений, содержащее стили, цветовые палитры, комбинации шрифтов и рекомендации...","ar":"UI/UX Pro Max هو دليل تصميم شامل لتطبيقات الويب والجوال، يحتوي على أنماط و_palettes ألوان وتركيبات خطوط وارشادات تجربة المستخدم.","en":""},"definition":{"en":""},"features":{"zh":["50+ 样式","97 色彩板","57 字体组合","99 用户体验指南","9 种技术栈"],"ja":["50 を超えるスタイル","97 のカラーパレット","57 のフォントペア","99 の UX ガイドライン","9 つのテクノロジースタック"],"ko":["50개 이상의 스타일","97개의 색상 팔레트","57개의 폰트 조합","99개의 사용자 경험 가이드","9개의 기술 스택"],"es":["50+ estilos de diseño","97 paletas de colores","57 combinaciones de fuentes","99 pautas de UX","25 tipos de gráficos","Base de datos searchable"],"fr":["50+ styles de design","97 palettes de couleurs","57 combinaisons de polices","99 lignes directrices UX","25 types de graphiques","Base de données searchable"],"de":["50+ Design-Stile","97 Farbpaletten","57 Schriftkombinationen","99 UX-Richtlinien","25 Chart-Typen","Durchsuchbare Datenbank"],"pt":["50+ estilos de design","97 paletas de cores","57 combinações de fontes","99 diretrizes de UX","25 tipos de gráficos","9 pilhas de tecnologia"],"ru":["50+ стилей дизайна","97 цветовых палитр","57 комбинаций шрифтов","99 рекомендаций по UX","25 типов графиков","9 технологических стеков"],"ar":["50+ نمط تصميم","97 لوحة ألوان","57 تركيبة خط","99 إرشاد تجربة المستخدم","25 نوع من الرسومات","9 كومة تكنولوجية"]},"keywords":{"zh":["UI/UX 设计","网页设计","移动应用设计","设计智能","用户体验","设计指南"],"ja":["UI/UX デザイン","ウェブ デザイン","モバイル アプリケーション デザイン","デザイン インテリジェンス","ユーザー エクスペリエンス","デザイン ガイド"],"ko":["UI/UX 디자인","웹 디자인","모바일 애플리케이션 디자인","디자인 인텔리전스","사용자 경험","디자인 가이드"],"es":["diseño UI/UX","guias de diseño","estilos de diseño","paletas de colores","pautas de UX","desarrollo web","desarrollo móvil","kit de diseño"],"fr":["design UI/UX","guides de design","styles de design","palettes de couleurs","lignes directrices UX","développement web","développement mobile","kit de design"],"de":["Design UI/UX","Design-Leitfäden","Design-Stile","Farbpaletten","UX-Richtlinien","Web-Entwicklung","Mobile-Entwicklung","Design-Kit"],"pt":["ui/ux design","desenvolvimento web","aplicações móveis","design de interface","experiência de usuário","guias de design","estilos de design","paletas de cores","combinações de fontes"],"ru":["ui/ux дизайн","веб-разработка","мобильные приложения","дизайн интерфейса","пользовательский опыт","руководства по дизайну","стили дизайна","цветовые палитры","комбинации шрифтов"],"ar":["تصميم ui/ux","تطوير الويب","تطبيقات الجوال","تصميم الواجهة","تجربة المستخدم","دلائل التصميم","أنماط التصميم","الوحات الألوان","تركيبات الخط"]}},"owner":"jabez4jc","repo":"Simplifyed","repoPath":"jabez4jc/Simplifyed","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"ui-ux-pro-max","description":"UI/UX design intelligence. 50 styles, 21 palettes, 50 font pairings, 20 charts, 9 stacks (React, Next.js, Vue, Svelte, SwiftUI, React Native, Flutter, Tailwind, shadcn/ui). Actions: plan, build, create, design, implement, review, fix, improve, optimize, enhance, refactor, check UI/UX code. Projects: website, landing page, dashboard, admin panel, e-commerce, SaaS, portfolio, blog, mobile app, .html, .tsx, .vue, .svelte. Elements: button, modal, navbar, sidebar, card, table, form, chart. Styles: glassmorphism, claymorphism, minimalism, brutalism, neumorphism, bento grid, dark mode, responsive, skeuomorphism, flat design. Topics: color palette, accessibility, animation, layout, typography, font pairing, spacing, hover, shadow, gradient. Integrations: shadcn/ui MCP for component search and examples.","bodyPreview":"# UI/UX Pro Max - Design Intelligence\r\n\r\nComprehensive design guide for web and mobile applications. Contains 50+ styles, 97 color palettes, 57 font pairings, 99 UX guidelines, and 25 chart types across 9 technology stacks. Searchable database with priority-based recommendations.\r\n\r\n## When to Apply\r\n\r\nReference these guidelines when:\r\n- Designing new UI components or pages\r\n- Choosing color palettes and typography\r\n- Reviewing code for UX issues\r\n- Building landing pages or dashboards\r\n- Implem","body":"# UI/UX Pro Max - Design Intelligence\r\n\r\nComprehensive design guide for web and mobile applications. Contains 50+ styles, 97 color palettes, 57 font pairings, 99 UX guidelines, and 25 chart types across 9 technology stacks. Searchable database with priority-based recommendations.\r\n\r\n## When to Apply\r\n\r\nReference these guidelines when:\r\n- Designing new UI components or pages\r\n- Choosing color palettes and typography\r\n- Reviewing code for UX issues\r\n- Building landing pages or dashboards\r\n- Implementing accessibility requirements\r\n\r\n## Rule Categories by Priority\r\n\r\n| Priority | Category | Impact | Domain |\r\n|----------|----------|--------|--------|\r\n| 1 | Accessibility | CRITICAL | `ux` |\r\n| 2 | Touch & Interaction | CRITICAL | `ux` |\r\n| 3 | Performance | HIGH | `ux` |\r\n| 4 | Layout & Responsive | HIGH | `ux` |\r\n| 5 | Typography & Color | MEDIUM | `typography`, `color` |\r\n| 6 | Animation | MEDIUM | `ux` |\r\n| 7 | Style Selection | MEDIUM | `style`, `product` |\r\n| 8 | Charts & Data | LOW | `chart` |\r\n\r\n## Quick Reference\r\n\r\n### 1. Accessibility (CRITICAL)\r\n\r\n- `color-contrast` - Minimum 4.5:1 ratio for normal text\r\n- `focus-states` - Visible focus rings on interactive elements\r\n- `alt-text` - Descriptive alt text for meaningful images\r\n- `aria-labels` - aria-label for icon-only buttons\r\n- `keyboard-nav` - Tab order matches visual order\r\n- `form-labels` - Use label with for attribute\r\n\r\n### 2. Touch & Interaction (CRITICAL)\r\n\r\n- `touch-target-size` - Minimum 44x44px touch targets\r\n- `hover-vs-tap` - Use click/tap for primary interactions\r\n- `loading-buttons` - Disable button during async operations\r\n- `error-feedback` - Clear error messages near problem\r\n- `cursor-pointer` - Add cursor-pointer to clickable elements\r\n\r\n### 3. Performance (HIGH)\r\n\r\n- `image-optimization` - Use WebP, srcset, lazy loading\r\n- `reduced-motion` - Check prefers-reduced-motion\r\n- `content-jumping` - Reserve space for async content\r\n\r\n### 4. Layout & Responsive (HIGH)\r\n\r\n- `viewport-meta` - width=device-width initial-scale=1\r\n- `readable-font-size` - Minimum 16px body text on mobile\r\n- `horizontal-scroll` - Ensure content fits viewport width\r\n- `z-index-management` - Define z-index scale (10, 20, 30, 50)\r\n\r\n### 5. Typography & Color (MEDIUM)\r\n\r\n- `line-height` - Use 1.5-1.75 for body text\r\n- `line-length` - Limit to 65-75 characters per line\r\n- `font-pairing` - Match heading/body font personalities\r\n\r\n### 6. Animation (MEDIUM)\r\n\r\n- `duration-timing` - Use 150-300ms for micro-interactions\r\n- `transform-performance` - Use transform/opacity, not width/height\r\n- `loading-states` - Skeleton screens or spinners\r\n\r\n### 7. Style Selection (MEDIUM)\r\n\r\n- `style-match` - Match style to product type\r\n- `consistency` - Use same style across all pages\r\n- `no-emoji-icons` - Use SVG icons, not emojis\r\n\r\n### 8. Charts & Data (LOW)\r\n\r\n- `chart-type` - Match chart type to data type\r\n- `color-guidance` - Use accessible color palettes\r\n- `data-table` - Provide table alternative for accessibility\r\n\r\n## How to Use\r\n\r\nSearch specific domains using the CLI tool below.\r\n\r\n---\r\n\r\n## Prerequisites\r\n\r\nCheck if Python is installed:\r\n\r\n```bash\r\npython3 --version || python --version\r\n```\r\n\r\nIf Python is not installed, install it based on user''s OS:\r\n\r\n**macOS:**\r\n```bash\r\nbrew install python3\r\n```\r\n\r\n**Ubuntu/Debian:**\r\n```bash\r\nsudo apt update && sudo apt install python3\r\n```\r\n\r\n**Windows:**\r\n```powershell\r\nwinget install Python.Python.3.12\r\n```\r\n\r\n---\r\n\r\n## How to Use This Skill\r\n\r\nWhen user requests UI/UX work (design, build, create, implement, review, fix, improve), follow this workflow:\r\n\r\n### Step 1: Analyze User Requirements\r\n\r\nExtract key information from user request:\r\n- **Product type**: SaaS, e-commerce, portfolio, dashboard, landing page, etc.\r\n- **Style keywords**: minimal, playful, professional, elegant, dark mode, etc.\r\n- **Industry**: healthcare, fintech, gaming, education, etc.\r\n- **Stack**: React, Vue, Next.js, or default to `html-tailwind`\r\n\r\n### Step 2: Generate Design System (REQUIRED)\r\n\r\n**Always start with `--design-system`** to get comprehensive recommendations with reasoning:\r\n\r\n```bash\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"<product_type> <industry> <keywords>\" --design-system [-p \"Project Name\"]\r\n```\r\n\r\nThis command:\r\n1. Searches 5 domains in parallel (product, style, color, landing, typography)\r\n2. Applies reasoning rules from `ui-reasoning.csv` to select best matches\r\n3. Returns complete design system: pattern, style, colors, typography, effects\r\n4. Includes anti-patterns to avoid\r\n\r\n**Example:**\r\n```bash\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"beauty spa wellness service\" --design-system -p \"Serenity Spa\"\r\n```\r\n\r\n### Step 3: Supplement with Detailed Searches (as needed)\r\n\r\nAfter getting the design system, use domain searches to get additional details:\r\n\r\n```bash\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"<keyword>\" --domain <domain> [-n <max_results>]\r\n```\r\n\r\n**When to use detailed searches:**\r\n\r\n| Need | Domain | Example |\r\n|------|--------|---------|\r\n| More style options | `style` | `--domain style \"glassmorphism dark\"` |\r\n| Chart recommendations | `chart` | `--domain chart \"real-time dashboard\"` |\r\n| UX best practices | `ux` | `--domain ux \"animation accessibility\"` |\r\n| Alternative fonts | `typography` | `--domain typography \"elegant luxury\"` |\r\n| Landing structure | `landing` | `--domain landing \"hero social-proof\"` |\r\n\r\n### Step 4: Stack Guidelines (Default: html-tailwind)\r\n\r\nGet implementation-specific best practices. If user doesn''t specify a stack, **default to `html-tailwind`**.\r\n\r\n```bash\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"<keyword>\" --stack html-tailwind\r\n```\r\n\r\nAvailable stacks: `html-tailwind`, `react`, `nextjs`, `vue`, `svelte`, `swiftui`, `react-native`, `flutter`, `shadcn`\r\n\r\n---\r\n\r\n## Search Reference\r\n\r\n### Available Domains\r\n\r\n| Domain | Use For | Example Keywords |\r\n|--------|---------|------------------|\r\n| `product` | Product type recommendations | SaaS, e-commerce, portfolio, healthcare, beauty, service |\r\n| `style` | UI styles, colors, effects | glassmorphism, minimalism, dark mode, brutalism |\r\n| `typography` | Font pairings, Google Fonts | elegant, playful, professional, modern |\r\n| `color` | Color palettes by product type | saas, ecommerce, healthcare, beauty, fintech, service |\r\n| `landing` | Page structure, CTA strategies | hero, hero-centric, testimonial, pricing, social-proof |\r\n| `chart` | Chart types, library recommendations | trend, comparison, timeline, funnel, pie |\r\n| `ux` | Best practices, anti-patterns | animation, accessibility, z-index, loading |\r\n| `react` | React/Next.js performance | waterfall, bundle, suspense, memo, rerender, cache |\r\n| `web` | Web interface guidelines | aria, focus, keyboard, semantic, virtualize |\r\n| `prompt` | AI prompts, CSS keywords | (style name) |\r\n\r\n### Available Stacks\r\n\r\n| Stack | Focus |\r\n|-------|-------|\r\n| `html-tailwind` | Tailwind utilities, responsive, a11y (DEFAULT) |\r\n| `react` | State, hooks, performance, patterns |\r\n| `nextjs` | SSR, routing, images, API routes |\r\n| `vue` | Composition API, Pinia, Vue Router |\r\n| `svelte` | Runes, stores, SvelteKit |\r\n| `swiftui` | Views, State, Navigation, Animation |\r\n| `react-native` | Components, Navigation, Lists |\r\n| `flutter` | Widgets, State, Layout, Theming |\r\n| `shadcn` | shadcn/ui components, theming, forms, patterns |\r\n\r\n---\r\n\r\n## Example Workflow\r\n\r\n**User request:** \"Làm landing page cho dịch vụ chăm sóc da chuyên nghiệp\"\r\n\r\n### Step 1: Analyze Requirements\r\n- Product type: Beauty/Spa service\r\n- Style keywords: elegant, professional, soft\r\n- Industry: Beauty/Wellness\r\n- Stack: html-tailwind (default)\r\n\r\n### Step 2: Generate Design System (REQUIRED)\r\n\r\n```bash\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"beauty spa wellness service elegant\" --design-system -p \"Serenity Spa\"\r\n```\r\n\r\n**Output:** Complete design system with pattern, style, colors, typography, effects, and anti-patterns.\r\n\r\n### Step 3: Supplement with Detailed Searches (as needed)\r\n\r\n```bash\r\n# Get UX guidelines for animation and accessibility\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"animation accessibility\" --domain ux\r\n\r\n# Get alternative typography options if needed\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"elegant luxury serif\" --domain typography\r\n```\r\n\r\n### Step 4: Stack Guidelines\r\n\r\n```bash\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"layout responsive form\" --stack html-tailwind\r\n```\r\n\r\n**Then:** Synthesize design system + detailed searches and implement the design.\r\n\r\n---\r\n\r\n## Output Formats\r\n\r\nThe `--design-system` flag supports two output formats:\r\n\r\n```bash\r\n# ASCII box (default) - best for terminal display\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"fintech crypto\" --design-system\r\n\r\n# Markdown - best for documentation\r\npython3 .claude/skills/ui-ux-pro-max/scripts/search.py \"fintech crypto\" --design-system -f markdown\r\n```\r\n\r\n---\r\n\r\n## Tips for Better Results\r\n\r\n1. **Be specific with keywords** - \"healthcare SaaS dashboard\" > \"app\"\r\n2. **Search multiple times** - Different keywords reveal different insights\r\n3. **Combine domains** - Style + Typography + Color = Complete design system\r\n4. **Always check UX** - Search \"animation\", \"z-index\", \"accessibility\" for common issues\r\n5. **Use stack flag** - Get implementation-specific best practices\r\n6. **Iterate** - If first search doesn''t match, try different keywords\r\n\r\n---\r\n\r\n## Common Rules for Professional UI\r\n\r\nThese are frequently overlooked issues that make UI look unprofessional:\r\n\r\n### Icons & Visual Elements\r\n\r\n| Rule | Do | Don''t |\r\n|------|----|----- |\r\n| **No emoji icons** | Use SVG icons (Heroicons, Lucide, Simple Icons) | Use emojis like 🎨 🚀 ⚙️ as UI icons |\r\n| **Stable hover states** | Use color/opacity transitions on hover | Use scale transforms that shift layout |\r\n| **Correct brand logos** | Research official SVG from Simple Icons | Guess or use incorrect logo paths |\r\n| **Consistent icon sizing** | Use fixed viewBox (24x24) with w-6 h-6 | Mix different icon sizes randomly |\r\n\r\n### Interaction & Cursor\r\n\r\n| Rule | Do | Don''t |\r\n|------|----|----- |\r\n| **Cursor pointer** | Add `cursor-pointer` to all clickable/hoverable cards | Leave default cursor on interactive elements |\r\n| **Hover feedback** | Provide visual feedback (color, shadow, border) | No indication element is interactive |\r\n| **Smooth transitions** | Use `transition-colors duration-200` | Instant state changes or too slow (>500ms) |\r\n\r\n### Light/Dark Mode Contrast\r\n\r\n| Rule | Do | Don''t |\r\n|------|----|----- |\r\n| **Glass card light mode** | Use `bg-white/80` or higher opacity | Use `bg-white/10` (too transparent) |\r\n| **Text contrast light** | Use `#0F172A` (slate-900) for text | Use `#94A3B8` (slate-400) for body text |\r\n| **Muted text light** | Use `#475569` (slate-600) minimum | Use gray-400 or lighter |\r\n| **Border visibility** | Use `border-gray-200` in light mode | Use `border-white/10` (invisible) |\r\n\r\n### Layout & Spacing\r\n\r\n| Rule | Do | Don''t |\r\n|------|----|----- |\r\n| **Floating navbar** | Add `top-4 left-4 right-4` spacing | Stick navbar to `top-0 left-0 right-0` |\r\n| **Content padding** | Account for fixed navbar height | Let content hide behind fixed elements |\r\n| **Consistent max-width** | Use same `max-w-6xl` or `max-w-7xl` | Mix different container widths |\r\n\r\n---\r\n\r\n## Pre-Delivery Checklist\r\n\r\nBefore delivering UI code, verify these items:\r\n\r\n### Visual Quality\r\n- [ ] No emojis used as icons (use SVG instead)\r\n- [ ] All icons from consistent icon set (Heroicons/Lucide)\r\n- [ ] Brand logos are correct (verified from Simple Icons)\r\n- [ ] Hover states don''t cause layout shift\r\n- [ ] Use theme colors directly (bg-primary) not var() wrapper\r\n\r\n### Interaction\r\n- [ ] All clickable elements have `cursor-pointer`\r\n- [ ] Hover states provide clear visual feedback\r\n- [ ] Transitions are smooth (150-300ms)\r\n- [ ] Focus states visible for keyboard navigation\r\n\r\n### Light/Dark Mode\r\n- [ ] Light mode text has sufficient contrast (4.5:1 minimum)\r\n- [ ] Glass/transparent elements visible in light mode\r\n- [ ] Borders visible in both modes\r\n- [ ] Test both modes before delivery\r\n\r\n### Layout\r\n- [ ] Floating elements have proper spacing from edges\r\n- [ ] No content hidden behind fixed navbars\r\n- [ ] Responsive at 375px, 768px, 1024px, 1440px\r\n- [ ] No horizontal scroll on mobile\r\n\r\n### Accessibility\r\n- [ ] All images have alt text\r\n- [ ] Form inputs have labels\r\n- [ ] Color is not the only indicator\r\n- [ ] `prefers-reduced-motion` respected\r\n"},"lastSynced":"2026-02-18T06:32:38.574Z","agentAnalysis":{"suitability":{"en":"Perfect for Design-focused Agents needing comprehensive UI/UX guidelines and recommendations for web and mobile applications.","zh":"非常适合需要全面UI/UX指南和网页及移动应用推荐的设计导向型Agent。","ja":"デザインに焦点を当てたエージェントが、Webおよびモバイルアプリケーション向けの包括的なUI/UXガイドラインと推奨事項を必要とする場合に最適です。","ko":"디자인 중심의 에이전트가 웹 및 모바일 애플리케이션을 위한 포괄적인 UI/UX 지침과 권장 사항을 필요로 할 때 적합합니다.","es":"Perfecto para agentes enfocados en el diseño que necesitan directrices y recomendaciones exhaustivas de UI/UX para aplicaciones web y móviles.","fr":"Parfait pour les agents axés sur la conception nécessitant des lignes directrices et des recommandations complètes de UI/UX pour les applications Web et mobiles.","de":"Perfekt für designorientierte Agenten, die umfassende UI/UX-Richtlinien und Empfehlungen für Web- und Mobile-Anwendungen benötigen.","pt":"Perfeito para Agentes focados em Design que necessitam de diretrizes e recomendações abrangentes de UI/UX para aplicações web e móveis.","ru":"Идеально подходит для агентов, ориентированных на дизайн, которым необходимы полные рекомендации и руководящие принципы UI/UX для веб- и мобильных приложений.","ar":"مثالي للوكلاء المهتمين بالتصميم الذين يحتاجون إلى إرشادات شاملة وتوصيات لتنسيق واجهة المستخدم وتجربة المستخدم للويب والتطبيقات المحمولة."},"recommendation":{"en":"Empowers agents to create visually stunning and user-friendly interfaces by leveraging 50+ styles, 97 color palettes, and 57 font pairings, while also ensuring adherence to 99 UX guidelines across 9 technology stacks, utilizing searchable databases with priority-based recommendations for optimal design decisions.","zh":"通过利用50+样式、97种颜色调色板和57种字体配对，同时确保遵守9个技术栈中的99个UX指南，并利用具有优先级推荐的可搜索数据库，使得代理能够创建视觉上惊艳且用户友好的界面，做出最佳的设计决策。","ja":"50以上のスタイル、97のカラーパレット、57のフォントペアを利用し、9つのテクノロジースタックにわたる99のUXガイドラインに準拠し、優先順位に基づく推奨事項を備えた検索可能なデータベースを利用することで、エージェントが視覚的に驚くべきかつユーザーフレンドリーなインターフェイスを作成できるようにし、最適な設計決定を下せるようにします。","ko":"50가지 이상의 스타일, 97개의 색상 팔레트, 57개의 폰트 조합을 활용하여 9개의 기술 스택에 걸친 99개의 UX 가이드ライン을 준수하고, 우선순위 기반의 추천을 제공하는 검색 가능한 데이터베이스를 활용함으로써, 에이전트가 시각적으로惊艳하고 사용자 친화적인 인터페이스를 생성할 수 있도록 하며, 최적의 디자인 결정에 도움이 됩니다.","es":"Habilita a los agentes a crear interfaces visualmente impresionantes y fáciles de usar mediante el aprovechamiento de más de 50 estilos, 97 paletas de colores y 57 combinaciones de fuentes, al mismo tiempo que garantiza el cumplimiento de 99 pautas de UX en 9 pilas tecnológicas, utilizando bases de datos buscables con recomendaciones basadas en prioridades para decisiones de diseño óptimas.","fr":"Permet aux agents de créer des interfaces visuellement époustouflantes et conviviales en exploitant plus de 50 styles, 97 palettes de couleurs et 57 appariements de polices, tout en assurant le respect de 99 directives d''UX sur 9 piles technologiques, en utilisant des bases de données consultables avec des recommandations basées sur les priorités pour des décisions de conception optimales.","de":"Ermächtigt Agenten, visuell ansprechende und benutzerfreundliche Schnittstellen zu erstellen, indem sie mehr als 50 Stile, 97 Farbpaletten und 57 Schriftkombinationen nutzen und gleichzeitig die Einhaltung von 99 UX-Richtlinien in 9 Technologie-Stacks sicherstellen, wobei sie durchsuchbare Datenbanken mit priorisierungsbezogenen Empfehlungen für optimale Designentscheidungen verwenden.","pt":"Habilita os agentes a criar interfaces visualmente impressionantes e amigáveis ao usuário, aproveitando mais de 50 estilos, 97 paletas de cores e 57 combinações de fontes, garantindo também a adesão a 99 diretrizes de UX em 9 pilhas de tecnologia, utilizando bancos de dados pesquisáveis com recomendações baseadas em prioridade para decisões de design ótimas.","ru":"Наделяет агентов возможностью создавать визуально впечатляющие и удобные интерфейсы, используя более 50 стилей, 97 цветовых палитр и 57 комбинаций шрифтов, а также обеспечивая соблюдение 99 руководящих принципов UX в 9 технологических стеках, используя поисковые базы данных с рекомендациями, основанными на приоритете, для оптимальных дизайнерских решений.","ar":"يتمكن الوكلاء من إنشاء واجهات مستخدم بصريًا مذهلة وسهلة الاستخدام من خلال استخدام أكثر من 50 نمطًا و97 لوحة ألوان و57 زوجًا من الخطوط، مع ضمان الالتزام بدليل UX البالغ 99 دليلًا عبر 9 كومات تقنية، باستخدام قواعد بيانات قابلة للبحث مع توصيات قائمة على الأسبقية لاتخاذ قرارات التصميم الأمثل."},"useCases":{"en":["Designing new UI components or pages with consistent branding","Selecting optimal color palettes and typography for enhanced user experience","Reviewing code for UX issues and implementing corrective measures"],"zh":["设计具有统一品牌的新UI组件或页面","选择最佳的颜色调色板和字体以提高用户体验","查看代码中的UX问题并实施纠正措施"],"ja":["一貫したブランドを備えた新しいUIコンポーネントまたはページを設計する","ユーザーエクスペリエンスを高めるための最適なカラーパレットとフォントを選択する","コードのUXの問題を確認し、是正措置を実施する"],"ko":["일관된 브랜드를 가진 새로운 UI 컴포넌트 또는 페이지를 설계한다","사용자 경험을 향상시키기 위한 최적의 색상 팔레트와 글꼴을 선택한다","코드의 UX 문제를 검토하고 수정 조치를 구현한다"],"es":["Diseñar nuevos componentes de UI o páginas con una marca consistente","Seleccionar paletas de colores y tipografía óptimas para una experiencia de usuario mejorada","Revisar el código para problemas de UX y implementar medidas correctivas"],"fr":["Concevoir de nouveaux composants d''interface utilisateur ou des pages avec une marque cohérente","Sélectionner des palettes de couleurs et une typographie optimales pour une expérience utilisateur améliorée","Examiner le code pour les problèmes d''UX et mettre en œuvre des mesures correctives"],"de":["Neue UI-Komponenten oder -Seiten mit konsistenter Markenidentität entwerfen","Optimale Farbpaletten und Typografie für eine verbesserte Benutzererfahrung auswählen","Code auf UX-Probleme überprüfen und korrektive Maßnahmen ergreifen"],"pt":["Projetar novos componentes de UI ou páginas com marcação consistente","Selecionar paletas de cores e tipografia ótimas para uma experiência do usuário aprimorada","Revisar códigos para problemas de UX e implementar medidas corretivas"],"ru":["Разрабатывать новые компоненты UI или страницы с последовательной брендингом","Выбирать оптимальные цветовые палитры и типографику для улучшения пользовательского опыта","Проверять код на проблемы UX и реализовывать корректирующие меры"],"ar":["تصميم مكونات واجهة المستخدم الجديدة أو الصفحات مع العلامة التجارية المتسقة","اختيار لوحات الألوان والخطوط المثالية لتحسين تجربة المستخدم","استعراض الشفرات البرمجية لتحديد مشاكل تجربة المستخدم وتنفيذ الإجراءات التصحيحية"]},"limitations":{"en":["Requires access to the searchable database for priority-based recommendations","Limited to design guidelines for web and mobile applications"],"zh":["需要访问可搜索数据库以获得优先级推荐","仅适用于网页和移动应用的设计指南"],"ja":["優先順位に基づく推奨事項を得るために検索可能なデータベースへのアクセスが必要","Webおよびモバイルアプリケーションの設計ガイドラインのみに限定される"],"ko":["우선순위 기반의 추천을 얻기 위해 검색 가능한 데이터베이스에 액세스해야 합니다","웹 및 모바일 애플리케이션의 디자인 가이드라인만 해당"],"es":["Requiere acceso a la base de datos buscable para recomendaciones basadas en prioridades","Limitado a pautas de diseño para aplicaciones web y móviles"],"fr":["Nécessite un accès à la base de données consultable pour des recommandations basées sur les priorités","Limité aux directives de conception pour les applications Web et mobiles"],"de":["Erfordert Zugriff auf die durchsuchbare Datenbank für priorisierungsbezogene Empfehlungen","Begrenzt auf Designrichtlinien für Web- und Mobile-Anwendungen"],"pt":["Requer acesso ao banco de dados pesquisável para recomendações baseadas em prioridade","Limitado a diretrizes de design para aplicações web e móveis"],"ru":["Требует доступа к поисковой базе данных для рекомендаций, основанных на приоритете","Ограничен руководящими принципами дизайна для веб- и мобильных приложений"],"ar":["يتطلب الوصول إلى قاعدة البيانات القابلة للبحث للتوصيات القائمة على الأسبقية","محدود بإرشادات التصميم لتطبيقات الويب والمحمول"]},"version":3},"qualityScore":65}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ANcpLua/qyl/type-ownership', 'community', 'ANcpLua', 'qyl', 'ANcpLua/qyl', 'type-ownership', 0, 0, 55, '2026-02-18T01:08:43.448Z', '2026-02-18T06:32:43.749Z', NULL, '{"id":"ANcpLua/qyl/type-ownership","name":"type-ownership","description":{"zh":"类型所有权验证是AI观察平台的一项功能，用于扫描代码仓库并识别类型所有权问题","ja":"タイプ所有権バリデーターは、AI観察プラットフォームの機能で、コードリポジトリをスキャンしてタイプ所有権の問題を識別します","ko":"타입 소유권 검증은 AI 관찰 플랫폼의 기능으로 코드 저장소를扫描하여 타입 소유권 문제를 식별합니다","es":"Type Ownership es una plataforma de observabilidad de IA que analiza registros y tipos de datos para optimizar las cargas de trabajo de GenAI/LLM","fr":"Type Ownership est une plateforme d''observabilité de l''IA qui analyse les journaux et les types de données pour optimiser les charges de travail GenAI/LLM","de":"Type Ownership ist eine KI-Beobachtungsplattform, die Log-Daten und Datentypen analysiert, um GenAI/LLM-Workloads zu optimieren","pt":"A plataforma Type Ownership é uma solução de observabilidade de IA para trabalhos de GenAI/LLM, com recursos como OTLP e DuckDB.","ru":"Платформа Type Ownership — это решение для наблюдения за ИИ для задач GenAI/LLM, с функциями như OTLP и DuckDB.","ar":"منصة Type Ownership هي حل لمراقبة الذكاء الاصطناعي لأعمال الجيل الثاني للذكاء الاصطناعي، مع ميزات مثل OTLP و DuckDB.","en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"seo":{"title":{"zh":"类型所有权验证 - AI观察平台","ja":"タイプ所有権バリデーター - AI観察プラットフォーム","ko":"타입 소유권 검증 - AI 관찰 플랫폼","es":"Type Ownership: Validación de tipos para GenAI/LLM","fr":"Type Ownership: Validation des types pour GenAI/LLM","de":"Type Ownership: Typ-Überprüfung für GenAI/LLM","pt":"Type Ownership: Plataforma de Observabilidade para GenAI/LLM","ru":"Type Ownership: Платформа для наблюдения за GenAI/LLM","ar":"Type Ownership: منصة مراقبة للذكاء الاصطناعي","en":"type-ownership"},"description":{"zh":"类型所有权验证是AI观察平台的一项功能，用于扫描代码仓库并识别类型所有权问题","ja":"タイプ所有権バリデーターは、AI観察プラットフォームの機能で、コードリポジトリをスキャンしてタイプ所有権の問題を識別します","ko":"타입 소유권 검증은 AI 관찰 플랫폼의 기능으로 코드 저장소를扫描하여 타입 소유권 문제를 식별합니다","es":"Type Ownership es una plataforma de observabilidad de IA que analiza registros y tipos de datos para optimizar las cargas de trabajo de GenAI/LLM","fr":"Type Ownership est une plateforme d''observabilité de l''IA qui analyse les journaux et les types de données pour optimiser les charges de travail GenAI/LLM","de":"Type Ownership ist eine KI-Beobachtungsplattform, die Log-Daten und Datentypen analysiert, um GenAI/LLM-Workloads zu optimieren","pt":"A plataforma Type Ownership é uma solução de observabilidade de IA para trabalhos de GenAI/LLM, com recursos como OTLP e DuckDB.","ru":"Платформа Type Ownership — это решение для наблюдения за ИИ для задач GenAI/LLM, с функциями như OTLP и DuckDB.","ar":"منصة Type Ownership هي حل لمراقبة الذكاء الاصطناعي لأعمال الجيل الثاني للذكاء الاصطناعي، مع ميزات مثل OTLP و DuckDB.","en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"definition":{"en":" question your logs | AI Observability Platform for GenAI/LLM workloads. OTLP ingestion, DuckDB storage, semantic conventions for AI telemetry."},"features":{"zh":["并行扫描多个代码仓库","识别公共类型和共享类型","检测类型重复和不一致","支持OTLP和DuckDB存储","提供语义约定用于AI遥测"],"ja":["複数のコードリポジトリを並列スキャン","パブリックタイプと共有タイプの識別","タイプの重複と矛盾の検出","OTLPとDuckDBストレージのサポート","AIテレメトリ用のセマンティック規約の提供"],"ko":["여러 코드 저장소를 병렬 스캔","공개 타입과 공유 타입 식별","타입 중복과 불일치 감지","OTLP와 DuckDB 저장소 지원","AI 원격 측정을 위한 의미 규약 제공"],"es":["Análisis de registros y tipos de datos","Validación de tipos para GenAI/LLM","Ingestión de OTLP","Almacenamiento en DuckDB","Convenciones semánticas para telemetría de IA"],"fr":["Analyse des journaux et des types de données","Validation des types pour GenAI/LLM","Ingestion de OTLP","Stockage en DuckDB","Conventions sémantiques pour la télémétrie de l''IA"],"de":["Analyse von Log-Daten und Datentypen","Überprüfung von Datentypen für GenAI/LLM","OTLP-Eingabe","Speicherung in DuckDB","Semantische Konventionen für KI-Telemetrie"],"pt":["Ingestão de OTLP","Armazenamento de DuckDB","Convenções semânticas para telemetria de IA","Análise de tipos para melhorar a eficiência","Suporte a trabalhos de GenAI/LLM"],"ru":["Ввод данных OTLP","Хранилище DuckDB","Семантические конвенции для телеметрии ИИ","Анализ типов для улучшения эффективности","Поддержка задач GenAI/LLM"],"ar":["استيعاب OTLP","تخزين DuckDB","اتفاقيات دلالية للبرمجيات الذكاء الاصطناعي","تحليل الأنواع لتحسين الكفاءة","دعم أعمال الجيل الثاني للذكاء الاصطناعي"]},"keywords":{"zh":["类型所有权验证","AI观察平台","代码分析","类型所有权问题","OTLP","DuckDB","语义约定","AI遥测"],"ja":["タイプ所有権バリデーター","AI観察プラットフォーム","コード分析","タイプ所有権の問題","OTLP","DuckDB","セマンティック規約","AIテレメトリ"],"ko":["타입 소유권 검증","AI 관찰 플랫폼","코드 분석","타입 소유권 문제","OTLP","DuckDB","의미 규약","AI 원격 측정"],"es":["Type Ownership","GenAI","LLM","Observabilidad de IA","Análisis de registros","Validación de tipos","OTLP","DuckDB","Telemetría de IA"],"fr":["Type Ownership","GenAI","LLM","Observabilité de l''IA","Analyse des journaux","Validation des types","OTLP","DuckDB","Télémétrie de l''IA"],"de":["Type Ownership","GenAI","LLM","KI-Beobachtung","Log-Datenanalyse","Überprüfung von Datentypen","OTLP","DuckDB","KI-Telemetrie"],"pt":["Type Ownership","Observabilidade de IA","GenAI/LLM","OTLP","DuckDB","Telemetria de IA","Análise de tipos","Eficiência de trabalhos"],"ru":["Type Ownership","Наблюдение за ИИ","GenAI/LLM","OTLP","DuckDB","Телеметрия ИИ","Анализ типов","Эффективность задач"],"ar":["Type Ownership","مراقبة الذكاء الاصطناعي","الجيل الثاني للذكاء الاصطناعي","OTLP","DuckDB","برمجيات الذكاء الاصطناعي","تحليل الأنواع","كفاءة العمل"]}},"owner":"ANcpLua","repo":"qyl","repoPath":"ANcpLua/qyl","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"type-ownership","description":"|","bodyPreview":"## Source Metadata\n\n```yaml\n# none\n```\n\n\n# Type Ownership Validator\n\nLaunch 3 agents parallel to scan each project:\n\n### Agent 1: Collector Types\n```yaml\nsubagent_type: feature-dev:code-reviewer\nprompt: |\n  TERRITORY: core/qyl.collector/**/*.cs\n\n  MISSION: Find types that should be in protocol.\n\n  RULE: If a type in collector is used by mcp or dashboard → VIOLATION\n\n  SCAN FOR:\n  1. Public types that could be shared\n  2. Types duplicated from protocol\n  3. DTOs that mcp might need\n  4. Types ref","body":"## Source Metadata\n\n```yaml\n# none\n```\n\n\n# Type Ownership Validator\n\nLaunch 3 agents parallel to scan each project:\n\n### Agent 1: Collector Types\n```yaml\nsubagent_type: feature-dev:code-reviewer\nprompt: |\n  TERRITORY: core/qyl.collector/**/*.cs\n\n  MISSION: Find types that should be in protocol.\n\n  RULE: If a type in collector is used by mcp or dashboard → VIOLATION\n\n  SCAN FOR:\n  1. Public types that could be shared\n  2. Types duplicated from protocol\n  3. DTOs that mcp might need\n  4. Types referenced in API responses\n\n  KNOWN INTERNAL (OK):\n  - DuckDbStore\n  - DuckDbSchema\n  - SpanStorageRow\n  - OtlpJsonSpanParser\n  - OtlpTypes\n\n  FIND ANY public type not in this list that might be needed elsewhere.\n\n  Output: List of potential ownership violations\n```\n\n### Agent 2: MCP Types\n```yaml\nsubagent_type: feature-dev:code-reviewer\nprompt: |\n  TERRITORY: core/qyl.mcp/**/*.cs\n\n  MISSION: Find types that should be in protocol.\n\n  RULE: If a type in mcp is used by collector or dashboard → VIOLATION\n\n  SCAN FOR:\n  1. Request/Response DTOs that match collector APIs\n  2. Types duplicated from protocol\n  3. Any shared data structures\n\n  KNOWN INTERNAL (OK):\n  - Tool implementations\n  - MCP-specific configs\n\n  Output: List of potential ownership violations\n```\n\n### Agent 3: Protocol Completeness\n```yaml\nsubagent_type: feature-dev:code-explorer\nprompt: |\n  TERRITORY: core/qyl.protocol/**/*.cs\n\n  MISSION: Verify protocol has all shared types.\n\n  EXPECTED TYPES:\n  - SessionId, UnixNano, TraceId, SpanId (Primitives)\n  - SpanRecord, SessionSummary, TraceNode (Records)\n  - GenAiSpanData, GenAiAttributes (Attributes)\n  - ISpanStore, ISessionAggregator (Interfaces)\n\n  CHECK:\n  1. All expected types exist\n  2. No implementation details leaked\n  3. Types are records/interfaces only (no classes with logic)\n  4. Correct namespaces\n\n  Output: Protocol type inventory with status\n```\n\n---\n\n## Aggregation\n\n```markdown\n# Type Ownership Report\n\n## Golden Rule Compliance\n> Types used by >1 project MUST be in protocol\n> Types used by 1 project MUST be in that project\n\n## Violations Found\n\n| Type | Current Location | Should Be | Reason |\n|------|------------------|-----------|--------|\n| ... | collector | protocol | Used by mcp |\n\n## Protocol Inventory\n\n| Type | Status | Consumers |\n|------|--------|-----------|\n| SessionId | ✅ | collector, mcp |\n| ... | ... | ... |\n\n## Duplicate Types\n[Any types defined in multiple places]\n\n## Recommendations\n1. Move X to protocol\n2. Delete duplicate Y\n```\n"},"lastSynced":"2026-02-18T06:32:43.749Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring advanced type ownership analysis and OTLP ingestion for GenAI/LLM workloads.","zh":"适用于需要高级类型所有权分析和OTLP摄取的GenAI/LLM工作负载的代码审查代理的理想选择。","ja":"コードレビューエージェントが高度なタイプ所有権分析およびOTLPの取り込みを必要とするGenAI/LLMワークロードに最適です。","ko":"코드 리뷰 에이전트가 고급 형 소유권 분석 및 OTLP 수신을 필요로 하는 GenAI/LLM 워크로드에 적합합니다.","es":"Ideal para agentes de revisión de código que requieren un análisis avanzado de propiedad de tipo y la ingesta de OTLP para cargas de trabajo de GenAI/LLM.","fr":"Idéal pour les agents de revue de code nécessitant une analyse avancée de propriété de type et l''ingestion OTLP pour les charges de travail GenAI/LLM.","de":"Ideal für Code-Review-Agents, die eine erweiterte Analyse des Typbesitzes und die OTLP-Eintragung für GenAI/LLM-Workloads erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem análise avançada de propriedade de tipo e ingestão de OTLP para cargas de trabalho de GenAI/LLM.","ru":"Идеально для агентов проверки кода, требующих расширенного анализа владения типами и ингестии OTLP для рабочих нагрузок GenAI/LLM.","ar":"مثالي لعميل مراجعة الشفرة الذي يتطلب تحليل متقدم لملكية النوع واستهلاك OTLP لتحميل العمل GenAI/LLM."},"recommendation":{"en":"Empowers agents to scan projects for type ownership violations using semantic conventions for AI telemetry, DuckDB storage, and OTLP ingestion, ensuring protocol adherence and reducing type duplication.","zh":"赋予代理扫描项目的类型所有权违规使用语义约定进行AI遥测、DuckDB存储和OTLP摄取，确保协议遵守并减少类型重复。","ja":"エージェントに、AIテレメトリ、DuckDBストレージ、OTLP取り込みのためのセマンティック規約を使用して、プロジェクトのタイプ所有権違反をスキャンする機能を提供し、プロトコル遵守を確保し、タイプの重複を減らします。","ko":"에이전트가 프로젝트의 형 소유권 위반을 스캔하기 위해 AI 원격 분석, DuckDB 저장소 및 OTLP 수신을 위한 의미 규약을 사용하여 프로토콜 준수를 보장하고 형식 중복을 줄입니다.","es":"Habilita a los agentes para escanear proyectos en busca de violaciones de propiedad de tipo utilizando convenciones semánticas para telemetría de IA, almacenamiento DuckDB y la ingesta de OTLP, garantizando el cumplimiento del protocolo y reduciendo la duplicación de tipos.","fr":"Permet aux agents d''analyser les projets pour les violations de propriété de type en utilisant des conventions sémantiques pour la télémétrie IA, le stockage DuckDB et l''ingestion OTLP, assurant ainsi le respect du protocole et réduisant la duplication de types.","de":"Ermächtigt die Agenten, Projekte auf Verletzungen des Typbesitzes zu scannen, indem sie semantische Konventionen für die KI-Telemetrie, den DuckDB-Speicher und die OTLP-Eintragung verwenden, um die Einhaltung des Protokolls sicherzustellen und die Typduplizierung zu reduzieren.","pt":"Habilita os agentes a escanear projetos para violações de propriedade de tipo usando convenções semânticas para telemetria de IA, armazenamento DuckDB e ingestão de OTLP, garantindo a adesão ao protocolo e reduzindo a duplicação de tipos.","ru":"Наделяет агентов возможностью сканировать проекты на наличие нарушений владения типами с использованием семантических конвенций для телеметрии ИИ, хранилища DuckDB и ингестии OTLP, обеспечивая соблюдение протокола и уменьшая дублирование типов.","ar":"يمنح الوكلاء القدرة على مسح المشاريع للتحقق من انتهاكات ملكية النوع باستخدام الاتفاقيات الدلالية لتелеметрия الذكاء الاصطناعي وتخزين DuckDB واستهلاك OTLP، مما يضمن الالتزام بالبروتوكول وتقليل تكرار النوع."},"useCases":{"en":["Validating public types for sharing across projects","Identifying duplicated types from protocol for refactoring","Analyzing DTOs for potential usage in MCP or dashboard","Debugging type references for ownership inconsistencies"],"zh":["验证公共类型以在项目间共享","根据协议识别重复类型以进行重构","分析DTO以便在MCP或仪表板中使用","调试类型引用以解决所有权不一致性"],"ja":["プロジェクト間で共有するためのパブリックタイプの検証","プロトコルから重複するタイプを識別してリファクタリングする","MCPまたはダッシュボードで使用するためのDTOの分析","所有権の不一致を解決するためのタイプ参照のデバッグ"],"ko":["프로젝트 간에 공유하기 위한 공용 형식의 유효성 검사","프로토콜에서 중복 형식을 식별하여 리팩토링","MCP 또는 대시보드에서 사용하기 위한 DTO 분석","소유권 불일치를 해결하기 위한 형식 참조 디버깅"],"es":["Validar tipos públicos para compartir entre proyectos","Identificar tipos duplicados del protocolo para refactorizar","Analizar DTO para su uso potencial en MCP o panel de control","Depurar referencias de tipo para incoherencias de propiedad"],"fr":["Valider les types publics pour les partager entre les projets","Identifier les types dupliqués du protocole pour les refactoriser","Analyser les DTO pour une utilisation potentielle dans MCP ou tableau de bord","Déboguer les références de type pour les incohérences de propriété"],"de":["Überprüfen öffentlicher Typen für den Austausch zwischen Projekten","Duplizierte Typen aus dem Protokoll identifizieren, um sie neu zu strukturieren","DTO analysieren für den potenziellen Einsatz in MCP oder Dashboard","Typreferenzen für Inkonsistenzen des Besitzes debuggen"],"pt":["Validar tipos públicos para compartilhamento entre projetos","Identificar tipos duplicados do protocolo para refatoração","Analizar DTOs para uso potencial em MCP ou painel","Depurar referências de tipo para inconsistências de propriedade"],"ru":["Проверять общие типы для обмена между проектами","Определять дублирующие типы из протокола для рефакторинга","Анализировать DTO для потенциального использования в MCP или на панели","Отлаживать ссылки на типы для несоответствий владения"],"ar":["التحقق من أنواع عامة للمشاركة بين المشاريع","تحديد أنواع مكررة من البروتوكول لإعادة الهيكلة","تحليل DTO للاستخدام المحتمل في MCP أو لوحة","تصحيح أخطاء مراجع النوع للاختلافات في الملكية"]},"limitations":{"en":["Requires YAML configuration for subagent types and prompts","Limited to C# projects with collector types","Dependent on OTLP ingestion and DuckDB storage for telemetry"],"zh":["需要YAML配置用于子代理类型和提示","仅限于具有收集器类型的C#项目","依赖于OTLP摄取和DuckDB存储进行遥测"],"ja":["サブエージェントのタイプとプロンプトにYAML構成が必要","コレクタータイプを含むC#プロジェクトのみ","テレメトリを行うためにOTLP取り込みとDuckDBストレージに依存"],"ko":["서브 에이전트 유형 및 프롬프트에 대한 YAML 구성이 필요","수집기 유형을 포함하는 C# 프로젝트만","원격 분석을 위해 OTLP 수신 및 DuckDB 저장소에 종속"],"es":["Requiere configuración YAML para tipos de subagentes y solicitudes","Limitado a proyectos C# con tipos de coleccionador","Dependiente de la ingesta de OTLP y el almacenamiento de DuckDB para la telemetría"],"fr":["Nécessite une configuration YAML pour les types de sous-agents et les invites","Limité aux projets C# avec des types de collecteur","Dépend de l''ingestion OTLP et du stockage DuckDB pour la télémétrie"],"de":["Benötigt YAML-Konfiguration für Subagenten-Typen und Prompts","Begrenzt auf C#-Projekte mit Sammler-Typen","Abhängig von OTLP-Eintragung und DuckDB-Speicher für Telemetrie"],"pt":["Exige configuração YAML para tipos de subagentes e prompts","Limitado a projetos C# com tipos de colecionador","Dependente da ingestão de OTLP e armazenamento DuckDB para telemetria"],"ru":["Требует конфигурации YAML для типов субагентов и подсказок","Ограничен проектами C# с типами коллектора","Зависит от ингестии OTLP и хранилища DuckDB для телеметрии"],"ar":["يتطلب تكوين YAML لأنواع الوكيل الفرعي والتعليمات","محدود بمشاريع C# ذات أنواع المجمع","يعتمد على استهلاك OTLP وتخزين DuckDB لتелеметрия"]},"version":3},"qualityScore":55}');
