INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LDmoxeii/only-danmuku/cleanddd-kotlin-coding', 'community', 'LDmoxeii', 'only-danmuku', 'LDmoxeii/only-danmuku', 'cleanddd-kotlin-coding', 0, 0, 50, '2026-02-18T01:08:43.448Z', '2026-02-18T06:35:09.490Z', NULL, '{"id":"LDmoxeii/only-danmuku/cleanddd-kotlin-coding","name":"cleanddd-kotlin-coding","description":{"zh":"CleanDDD Kotlin 编码技巧是一种 Domain-Driven Design 的实现方法，强调 CQRS、聚合边界和持久化等技术要点","ja":"CleanDDD Kotlin コーディングスキルは、Domain-Driven Design の実装方法の一つで、CQRS、集約境界、永続化などの技術的ポイントを強調しています","ko":"CleanDDD Kotlin 코딩 스킬은 도메인 주도 설계의 구현 방법 중 하나로 CQRS, 집계 경계 및 지속성 등을 강조합니다","es":"Clean DDD en Kotlin es un enfoque de codificación que combina principios de diseño de dominio y arquitectura limpia para desarrollar aplicaciones robustas y mantenibles","fr":"Clean DDD en Kotlin est une approche de codage qui combine des principes de conception de domaine et d''architecture propre pour développer des applications robustes et maintenables","de":"Clean DDD in Kotlin ist ein Codieransatz, der Prinzipien des Domain-Designs und der sauberen Architektur kombiniert, um robuste und wartbare Anwendungen zu entwickeln","pt":"Clean DDD Kotlin é uma abordagem de desenvolvimento de software que combina Domain-Driven Design com CQRS, visando melhorar a manutenção e escalabilidade dos sistemas","ru":"Clean DDD Kotlin - это подход к разработке программного обеспечения, сочетающий Domain-Driven Design с CQRS, направленный на улучшение поддержки и масштабируемости систем","ar":"Clean DDD Kotlin هو نهج لتنمية البرمجيات يجمع بين Domain-Driven Design و CQRS، لتحسين الصيانة والتماسك للنظم","en":""},"seo":{"title":{"zh":"CleanDDD Kotlin 编码技巧","ja":"CleanDDD Kotlin コーディングスキル","ko":"CleanDDD Kotlin 코딩 스킬","es":"Codificación Clean DDD en Kotlin","fr":"Codage Clean DDD en Kotlin","de":"Clean DDD-Kotlin-Codierung","pt":"Clean DDD Kotlin: Desenvolvimento de Software com CQRS","ru":"Clean DDD Kotlin: Разработка программного обеспечения с CQRS","ar":"Clean DDD Kotlin: تنمية البرمجيات باستخدام CQRS","en":"cleanddd-kotlin-coding"},"description":{"zh":"CleanDDD Kotlin 编码技巧是一种 Domain-Driven Design 的实现方法，强调 CQRS、聚合边界和持久化等技术要点","ja":"CleanDDD Kotlin コーディングスキルは、Domain-Driven Design の実装方法の一つで、CQRS、集約境界、永続化などの技術的ポイントを強調しています","ko":"CleanDDD Kotlin 코딩 스킬은 도메인 주도 설계의 구현 방법 중 하나로 CQRS, 집계 경계 및 지속성 등을 강조합니다","es":"Clean DDD en Kotlin es un enfoque de codificación que combina principios de diseño de dominio y arquitectura limpia para desarrollar aplicaciones robustas y ...","fr":"Clean DDD en Kotlin est une approche de codage qui combine des principes de conception de domaine et d''architecture propre pour développer des applications r...","de":"Clean DDD in Kotlin ist ein Codieransatz, der Prinzipien des Domain-Designs und der sauberen Architektur kombiniert, um robuste und wartbare Anwendungen zu e...","pt":"Clean DDD Kotlin é uma abordagem de desenvolvimento de software que combina Domain-Driven Design com CQRS, visando melhorar a manutenção e escalabilidade dos...","ru":"Clean DDD Kotlin - это подход к разработке программного обеспечения, сочетающий Domain-Driven Design с CQRS, направленный на улучшение поддержки и масштабиру...","ar":"Clean DDD Kotlin هو نهج لتنمية البرمجيات يجمع بين Domain-Driven Design و CQRS، لتحسين الصيانة والتماسك للنظم","en":""},"definition":{"en":""},"features":{"zh":["CQRS 实现","聚合边界管理","持久化机制","防腐层设计","JSR-303 校验"],"ja":["CQRS 実装","集約境界管理","永続化メカニズム","防腐層設計","JSR-303 検証"],"ko":["CQRS 구현","집계 경계 관리","지속성 메커니즘","방부층 설계","JSR-303 검증"],"es":["Separación de la lógica de negocio y la infraestructura","Uso de CQRS para comando y consulta","Validación de datos con JSR-303","Uso de DTO con sufijos Request/Response","Arquitectura limpia y escalable"],"fr":["Séparation de la logique métier et de l''infrastructure","Utilisation de CQRS pour les commandes et les requêtes","Validation des données avec JSR-303","Utilisation de DTO avec des suffixes Request/Response","Architecture propre et évolutuve"],"de":["Trennung der Geschäftslogik und der Infrastruktur","Verwendung von CQRS für Befehle und Abfragen","Datenvalidierung mit JSR-303","Verwendung von DTO mit Request/Response-Suffixen","Saubere und skalierbare Architektur"],"pt":["Separação de responsabilidades com CQRS","Melhoria da manutenção e escalabilidade","Aplicação de boas práticas de codificação","Utilização de Domain-Driven Design","Suporte a desenvolvimento de software robusto"],"ru":["Разделение ответственности с помощью CQRS","Улучшение поддержки и масштабируемости","Применение лучших практик кодирования","Использование Domain-Driven Design","Поддержка разработки прочного программного обеспечения"],"ar":["فصل المسؤوليات باستخدام CQRS","تحسين الصيانة والتماسك","تطبيق أفضل الممارسات للبرمجة","استخدام Domain-Driven Design","دعم تطوير البرمجيات القوية"]},"keywords":{"zh":["CleanDDD","Kotlin","Domain-Driven Design","CQRS","聚合边界","持久化","防腐层"],"ja":["CleanDDD","Kotlin","Domain-Driven Design","CQRS","集約境界","永続化","防腐層"],"ko":["CleanDDD","Kotlin","도메인 주도 설계","CQRS","집계 경계","지속성","방부층"],"es":["Clean DDD","Kotlin","CQRS","arquitectura limpia","desarrollo de software","patrones de diseño","validación de datos","DTO"],"fr":["Clean DDD","Kotlin","CQRS","architecture propre","développement de logiciels","modèles de conception","validation des données","DTO"],"de":["Clean DDD","Kotlin","CQRS","saubere Architektur","Softwareentwicklung","Entwurfsmuster","Datenvalidierung","DTO"],"pt":["Clean DDD Kotlin","Desenvolvimento de software","CQRS","Domain-Driven Design","Boas práticas de codificação","Manutenção de software","Escalabilidade de software"],"ru":["Clean DDD Kotlin","Разработка программного обеспечения","CQRS","Domain-Driven Design","Лучшие практики кодирования","Поддержка программного обеспечения","Масштабируемость программного обеспечения"],"ar":["Clean DDD Kotlin","تنمية البرمجيات","CQRS","Domain-Driven Design","أفضل الممارسات للبرمجة","صيانة البرمجيات","تماسك البرمجيات"]}},"owner":"LDmoxeii","repo":"only-danmuku","repoPath":"LDmoxeii/only-danmuku","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.448Z","topics":[],"category":"community","skillMd":{"name":"cleanddd-kotlin-coding","description":"在 only-danmuku 的 CleanDDD Kotlin 项目中编写或修改聚合/命令/查询/API 端点/事件/防腐层 Client/仓储/配置/测试时使用；遵循 代码实现规约.md 与 design/_gen + genDesign 的生成流程。","bodyPreview":"# CleanDDD Kotlin Coding（only-danmuku）\n\n## 必读参考\n- 若仓库存在 `代码实现规约.md`，先阅读并以其为准；此技能用于补足执行步骤与易错点。\n- 需要新增命令/查询/事件/校验器/Client 时，先更新 `design/*_gen.json`，再执行 `./gradlew genDesign`。\n\n## 前置输入\n- 已有 cleanddd-modeling 交付：`iterate/<feature>/*_gen.json` 与 `*_update.sql`。\n- 已确认聚合边界、不变式、命令/查询清单与事件链路。\n\n## 快速检查\n- 遵循 CQRS：命令不依赖查询、查询不依赖仓储；命令内禁止使用读端 `sqlClient`。\n- 聚合边界：仅聚合根发布领域事件；命令/事件不以子实体 ID 作为入参。\n- 持久化：命令通过仓储整体加载聚合并使用领域方法变更，禁止直接改字段。\n- 防腐层：仅做外部系统/文件交互，不包含数据库 ID 概念。\n- 规范：DTO 使用 `Request`/`Response` 后缀；JSR-303 校验 + `","body":"# CleanDDD Kotlin Coding（only-danmuku）\n\n## 必读参考\n- 若仓库存在 `代码实现规约.md`，先阅读并以其为准；此技能用于补足执行步骤与易错点。\n- 需要新增命令/查询/事件/校验器/Client 时，先更新 `design/*_gen.json`，再执行 `./gradlew genDesign`。\n\n## 前置输入\n- 已有 cleanddd-modeling 交付：`iterate/<feature>/*_gen.json` 与 `*_update.sql`。\n- 已确认聚合边界、不变式、命令/查询清单与事件链路。\n\n## 快速检查\n- 遵循 CQRS：命令不依赖查询、查询不依赖仓储；命令内禁止使用读端 `sqlClient`。\n- 聚合边界：仅聚合根发布领域事件；命令/事件不以子实体 ID 作为入参。\n- 持久化：命令通过仓储整体加载聚合并使用领域方法变更，禁止直接改字段。\n- 防腐层：仅做外部系统/文件交互，不包含数据库 ID 概念。\n- 规范：DTO 使用 `Request`/`Response` 后缀；JSR-303 校验 + `KnownException` 处理业务错误。\n- Kotlin 风格：4 空格缩进；简单返回用表达式体；避免通配符导入。\n\n## 推荐流程\n1) 补设计元素：在 `design/*_gen.json` 中补命令/查询/事件/校验器/Client，执行 `./gradlew genDesign`。\n2) 实现 domain：聚合/实体/值对象/领域方法/领域事件。\n3) 实现 application：命令/查询契约、校验器、Handler、订阅者。\n4) 实现 adapter：Controller、QueryHandler、ClientHandler。\n5) 补配置与日志：关键路径配置化，关键行为打点。\n\n## 分层职责\n- adapter 层：仅做编排与入参校验，调用 `Mediator.commands.send(...)` 或 `Mediator.queries.send(...)`；不写业务分支、不操作聚合、不访问仓储/事务。\n- application 层：组织用例流程与事务边界；命令写端、查询读端分离。\n- domain 层：聚合根/实体/领域方法/领域事件；不关注 Web 与持久化细节。\n\n## API 端点（Controller）\n- 位置：`only-danmuku-adapter/.../portal/api`，按业务拆分文件，统一 `@PostMapping`。\n- 使用 `Request` DTO + JSR-303 注解；必要时配合自定义校验器。\n- 只做上下文解析与调用 Mediator，不直接操作聚合或仓储。\n\n## 命令（Command）\n- 位置：`only-danmuku-application/.../commands`。\n- 单命令只修改一个聚合根；跨聚合通过领域事件 + 额外命令解耦。\n- 从仓储加载聚合，调用领域方法完成变更，`Mediator.uow.save()` 提交。\n- 复杂校验用“校验器 + 查询”承担；缺查询先在 design 中定义并生成。\n\n## 查询（Query）\n- 契约：`only-danmuku-application/.../queries`。\n- 实现：`only-danmuku-adapter/.../application/queries`，依赖 `KSqlClient` 而非仓储。\n- 返回 DTO 或投影模型；在查询层完成过滤/分页/排序/拼装。\n\n## 聚合与领域方法\n- 聚合/实体可变字段统一 `internal set`；禁止在命令中直接赋值。\n- 通过领域方法封装状态变更、约束检查与事件触发。\n- 生命周期使用 `onCreate/onUpdate/onDelete` 框架回调，禁止业务代码手动调用。\n\n## 领域事件与订阅\n- 命名：`实体 + 过去式动作`，如 `VideoPostTranscodingRequiredDomainEvent`。\n- 监听器只做编排并触发命令；同一事件多动作时拆分监听方法。\n- 事件定义缺失时，先在 design 中补齐并 `genDesign` 生成骨架。\n\n## 防腐层 Client\n- 契约：`only-danmuku-application/.../distributed/clients`。\n- Handler：`only-danmuku-adapter/.../application/distributed/clients`，仅做外部调用与结果映射。\n- 设计元素使用 `cli`（或别名 `client`）；先在 design 中定义再生成。\n\n## 校验器\n- 位置：`only-danmuku-application/.../validater`（以仓库实际目录为准）。\n- 依赖查询、不依赖仓储；尽早失败并抛 `KnownException`。\n\n## 代码生成与设计文件\n- 设计文件位于 `only-danmuku/design/*_gen.json`，支持标签别名（如 `cmd/command`、`qry/query`、`cli/client`）。\n- 执行 `./gradlew genDesign` 生成命令/查询/事件/校验器/Client 骨架。\n\n## 其他通用约定\n- 日志：只记录关键行为（转码、外部调用），包含关键标识（videoId、uploadId 等）。\n- 配置：路径、阈值用配置类管理，避免硬编码。\n- 规模限制：列表/数量等限制放在命令或聚合内统一收敛。\n\n## 提交前自检\n- 领域事件发布完整，监听器不直接跨聚合改数据。\n- 命令未混入查询逻辑，查询未依赖仓储。\n- 相关新增元素已落入 design 并通过 `genDesign` 生成骨架。\n"},"lastSynced":"2026-02-18T06:35:09.490Z","agentAnalysis":{"suitability":{"en":"Ideal for Kotlin-based AI Agents requiring advanced Domain-Driven Design (DDD) and Clean Architecture implementation in Kotlin","zh":"适用于需要在Kotlin中实现高级领域驱动设计（DDD）和清晰架构的Kotlin基于AI代理","ja":"KotlinベースのAIエージェントで、Kotlinにおける高度なドメイン駆動設計（DDD）とクリーンアーキテクチャの実装が必要な場合に最適","ko":"Kotlin 기반 AI 에이전트에서 Kotlin의 고급 도메인 주도 설계(DDD) 및 클린 아키텍처 구현이 필요한 경우 적합","es":"Ideal para agentes de IA basados en Kotlin que requieren una implementación avanzada de Diseño Orientado a Dominio (DDD) y Arquitectura Limpia en Kotlin","fr":"Idéal pour les agents d''IA basés sur Kotlin nécessitant une mise en œuvre avancée de la conception orientée domaine (DDD) et de l''architecture propre en Kotlin","de":"Ideal für auf Kotlin basierende KI-Agents, die eine erweiterte Umsetzung von Domain-Driven Design (DDD) und Clean Architecture in Kotlin erfordern","pt":"Ideal para Agentes de IA baseados em Kotlin que exigem implementação avançada de Domain-Driven Design (DDD) e Arquitetura Limpa em Kotlin","ru":"Идеально для агентов ИИ на основе Kotlin, требующих продвинутой реализации Domain-Driven Design (DDD) и Чистой Архитектуры в Kotlin","ar":"مثالي لعميل الذكاء الاصطناعي المبني على Kotlin الذي يتطلب تنفيذا متقدمًا لتصميم الدومين الموجه (DDD) وتصميم الهيكل النظيف في Kotlin"},"recommendation":{"en":"Empowers agents to enforce CQRS principles, utilize JSR-303 validation, and adhere to strict domain modeling guidelines, ensuring robust and maintainable codebases through the use of Gradle and Kotlin-specific design patterns","zh":"赋予代理执行CQRS原则、利用JSR-303验证和遵守严格的领域建模指南，通过使用Gradle和Kotlin特定的设计模式确保强壮且可维护的代码库","ja":"エージェントにCQRS原則の実行、JSR-303バリデーションの利用、厳格なドメインモデリングガイドラインの遵守を可能にし、GradleおよびKotlin固有のデザインパターンを使用して堅牢で保守可能なコードベースを確保する","ko":"에이전트가 CQRS 원칙을 적용하고 JSR-303 검증을 사용하며 엄격한 도메인 모델링 지침을 준수하여 Gradle과 Kotlin 전용 디자인 패턴을 사용하여 강력하고 유지 가능한 코드베이스를 보장","es":"Habilita a los agentes a aplicar los principios CQRS, utilizar la validación JSR-303 y adherirse a las estrictas pautas de modelado de dominio, garantizando bases de código robustas y mantenibles a través del uso de Gradle y patrones de diseño específicos de Kotlin","fr":"Permet aux agents d''appliquer les principes CQRS, d''utiliser la validation JSR-303 et de suivre les directives de modélisation de domaine strictes, garantissant ainsi des bases de code robustes et maintenables grâce à l''utilisation de Gradle et de modèles de conception spécifiques à Kotlin","de":"Ermächtigt Agents, CQRS-Prinzipien durchzusetzen, JSR-303-Validierung zu nutzen und strikten Domain-Modellierungsrichtlinien zu folgen, um robuste und wartbare Codebasen durch den Einsatz von Gradle und Kotlin-spezifischen Entwurfsmustern sicherzustellen","pt":"Habilita os agentes a impor princípios CQRS, utilizar validação JSR-303 e aderir a diretrizes rigorosas de modelagem de domínio, garantindo código-fonte robusto e mantido por meio do uso de Gradle e padrões de design específicos do Kotlin","ru":"Наделяет агентов возможностью обеспечивать соблюдение принципов CQRS, использовать валидацию JSR-303 и следовать строгим рекомендациям по моделированию домена, гарантируя прочную и поддерживаемую базу кода посредством использования Gradle и шаблонов проектирования, специфичных для Kotlin","ar":"يُطلق العميل القدرة على فرض مبادئ CQRS، واستخدام التحقق من JSR-303، والالتزام بإرشادات نمذجة النطاق الصارمة، مما يضمن قاعدة شفرة قوية وقابلة للصيانة من خلال استخدام Gradle وأنماط التصميم الخاصة بالكوتلين"},"useCases":{"en":["Implementing Domain-Driven Design principles in Kotlin applications","Generating and validating domain events and commands","Enforcing data integrity through JSR-303 validation and strict domain modeling"],"zh":["在Kotlin应用中实现领域驱动设计原则","生成和验证领域事件和命令","通过JSR-303验证和严格的领域建模强制执行数据完整性"],"ja":["Kotlinアプリケーションでドメイン駆動設計原則を実装する","ドメインイベントとコマンドを生成および検証する","JSR-303バリデーションと厳格なドメインモデリングを通じてデータの完全性を強制する"],"ko":["Kotlin 애플리케이션에서 도메인 주도 설계 원칙을 구현","도메인 이벤트 및 명령을 생성하고 검증","JSR-303 검증 및 엄격한 도메인 모델링을 통해 데이터 무결성을 적용"],"es":["Implementar principios de Diseño Orientado a Dominio en aplicaciones Kotlin","Generar y validar eventos y comandos de dominio","Garantizar la integridad de los datos a través de la validación JSR-303 y el modelado de dominio estricto"],"fr":["Mettre en œuvre les principes de conception orientée domaine dans les applications Kotlin","Générer et valider les événements et les commandes de domaine","Assurer l''intégrité des données grâce à la validation JSR-303 et à la modélisation de domaine stricte"],"de":["Prinzipien des Domain-Driven Design in Kotlin-Anwendungen umsetzen","Generieren und Validieren von Domain-Ereignissen und -Befehlen","Durch die Verwendung von JSR-303-Validierung und strenger Domain-Modellierung die Datenintegrität gewährleisten"],"pt":["Implementação de princípios de Domain-Driven Design em aplicações Kotlin","Geração e validação de eventos e comandos de domínio","Garantia da integridade dos dados por meio da validação JSR-303 e modelagem de domínio rigorosa"],"ru":["Реализация принципов Domain-Driven Design в приложениях Kotlin","Генерация и проверка событий и команд домена","Обеспечение целостности данных посредством валидации JSR-303 и строгого моделирования домена"],"ar":["تنفيذ مبادئ تصميم الدومين الموجه في تطبيقات Kotlin","إنشاء وتحقق من أحداث وأوامر الدومين","ضمان سلامة البيانات من خلال التحقق من JSR-303 ونمذجة الدومين الصارمة"]},"limitations":{"en":["Requires prior knowledge of Domain-Driven Design and Clean Architecture principles","Specific to Kotlin programming language","Needs Gradle build tool for design generation and validation"],"zh":["需要预先了解领域驱动设计和清晰架构原则","特定于Kotlin编程语言","需要Gradle构建工具进行设计生成和验证"],"ja":["ドメイン駆動設計とクリーンアーキテクチャ原則の事前知識が必要","Kotlinプログラミング言語に特有","デザイン生成とバリデーションのためにGradleビルドツールが必要"],"ko":["도메인 주도 설계 및 클린 아키텍처 원칙에 대한 사전 지식이 필요","Kotlin 프로그래밍 언어에 특정","디자인 생성 및 검증을 위해 Gradle 빌드 도구가 필요"],"es":["Requiere conocimientos previos de los principios de Diseño Orientado a Dominio y Arquitectura Limpia","Específico del lenguaje de programación Kotlin","Necesita la herramienta de construcción Gradle para la generación y validación de diseño"],"fr":["Nécessite des connaissances préalables des principes de conception orientée domaine et d''architecture propre","Spécifique au langage de programmation Kotlin","Nécessite l''outil de construction Gradle pour la génération et la validation de la conception"],"de":["Benötigt Vorkenntnisse in den Prinzipien von Domain-Driven Design und Clean Architecture","Spezifisch für die Programmiersprache Kotlin","Benötigt das Build-Tool Gradle für Design-Generierung und -Validierung"],"pt":["Exige conhecimento prévio de princípios de Domain-Driven Design e Arquitetura Limpa","Específico para a linguagem de programação Kotlin","Necessita da ferramenta de construção Gradle para geração e validação de design"],"ru":["Требует предварительных знаний принципов Domain-Driven Design и Чистой Архитектуры","Специфичен для языка программирования Kotlin","Требует инструмента построения Gradle для генерации и проверки дизайна"],"ar":["يتطلب معرفة سابقة بمبادئ تصميم الدومين الموجه والهيكل النظيف","محدد للغة البرمجة Kotlin","يحتاج إلى أداة بناء Gradle لتوليد وتحقق من التصميم"]},"version":3},"qualityScore":50}');
